function clearVolatileMarketSnapshots(reason = "CLEAR_VOLATILE_MARKET_SNAPSHOTS") {
  for (const key of VOLATILE_MARKET_SNAPSHOT_KEYS) {
    if (Array.isArray(engineState?.[key])) {
      engineState[key] = [];
    } else if (key === "liveQuoteCache" || key === "liveMarketMemory") {
      engineState[key] = {};
    } else {
      engineState[key] = null;
    }
  }

  engineState.staleSnapshotClearedAt = new Date().toISOString();
  engineState.staleSnapshotClearReason = reason;
}

function resetDailySafetyStateIfNewDay(account) {
  const todayKey = getTodayKeyET();
  const equity = Number(account?.equity || 0);

  if (!equity || equity <= 0) return false;

  if (engineState.dailyDateKey !== todayKey) {
    engineState.dailyDateKey = todayKey;

    engineState.dailyStartEquity = equity;
    engineState.dailyPeakEquity = equity;

    engineState.profitLockFloorEquity = null;

    engineState.dailyLossLocked = false;
    engineState.profitLocked = false;

    saveRecentOrder("DAILY_SAFETY_RESET", "ACCOUNT", {
      todayKey,
      equity,
    });

    saveEngineState("DAILY_SAFETY_RESET");

    return true;
  }

  return false;
}

let engineStateSaveTimer = null;
let pendingEngineStateSnapshot = null;
let pendingEngineStateReason = "STATE_UPDATE";

function flushEngineStateSave() {
  if (!pendingEngineStateSnapshot) return Promise.resolve();

  const snapshot = pendingEngineStateSnapshot;
  pendingEngineStateSnapshot = null;

  return fs.promises.writeFile(
    ENGINE_STATE_FILE,
    JSON.stringify(snapshot, null, 2)
  ).catch((err) => {
    console.error("Async engine-state save failed:", err.message);
  });
}


