const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function runInBatches(items, batchSize, worker) {
  const results = [];

  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize);

    const batchResults = await Promise.all(
      batch.map((item) => worker(item))
    );

    results.push(...batchResults.filter(Boolean));

    await sleep(2000);
  }

  return results;
}
function updateAccountPeaks(account) {
  const mode = TRADING_MODE;
  const equity = Number(account?.equity || 0);
  const cash = Number(account?.cash || 0);

  if (!engineState.peaksByMode[mode]) {
    engineState.peaksByMode[mode] = {
      peakEquity: equity,
      peakCash: cash,
    };
  }

  engineState.peaksByMode[mode].peakEquity = Math.max(
    Number(engineState.peaksByMode[mode].peakEquity || 0),
    equity
  );

  engineState.peaksByMode[mode].peakCash = Math.max(
    Number(engineState.peaksByMode[mode].peakCash || 0),
    cash
  );

  return engineState.peaksByMode[mode];
}


function isCryptoSymbol(symbol = "") {
  const normalized = String(symbol || "")
    .trim()
    .toUpperCase();

  return (
    normalized.includes("/") ||
    normalized.endsWith("USD") ||
    normalized.includes("USDT")
  );
}

function normalizeSymbol(symbol) {
  return String(symbol || "").trim().toUpperCase();
}

function isValidStockTicker(symbol = "") {
  const clean = normalizeSymbol(symbol);

  if (!clean) return false;
  if (isCryptoSymbol(clean)) return false;
  if (clean.includes("/")) return false;
  if (clean.includes("-")) return false;
  if (clean.includes(".")) return false;
  if (clean.length < 1 || clean.length > 5) return false;
  if (clean.length === 5 && /[YF]$/.test(clean)) return false;

  return /^[A-Z]+$/.test(clean);
}


function normalizeCryptoSymbolForPolygon(symbol = "") {
  const clean = normalizeSymbol(symbol)
    .replace(/^X:/, "")
    .replace("/", "-")
    .replace("_", "-");

  if (!clean) return "";

  if (clean.includes("-")) return clean;

  if (clean.endsWith("USDT") && clean.length > 4) {
    return `${clean.slice(0, -4)}-USDT`;
  }

  if (clean.endsWith("USD") && clean.length > 3) {
    return `${clean.slice(0, -3)}-USD`;
  }

  return clean;
}

function normalizePolygonCryptoPairToAppSymbol(pair = "") {
  const clean = normalizeSymbol(pair)
    .replace(/^X:/, "")
    .replace("_", "-");

  if (!clean) return "";

  if (clean.includes("-")) {
    const [base, quote] = clean.split("-");
    return base && quote ? `${base}/${quote}` : clean;
  }

  if (clean.endsWith("USDT") && clean.length > 4) {
    return `${clean.slice(0, -4)}/USDT`;
  }

  if (clean.endsWith("USD") && clean.length > 3) {
    return `${clean.slice(0, -3)}/USD`;
  }

  return clean;
}

function markAiManagedSymbol(symbol) {
  const clean = normalizeSymbol(symbol);

  if (!clean) return;

  if (!Array.isArray(engineState.aiManagedSymbols)) {
    engineState.aiManagedSymbols = [];
  }

  if (!engineState.aiManagedSymbols.includes(clean)) {
    engineState.aiManagedSymbols.push(clean);
    saveEngineState("AI_MANAGED_SYMBOL_ADDED");
  }
}

function unmarkAiManagedSymbol(symbol) {
  const clean = normalizeSymbol(symbol);

  if (!clean || !Array.isArray(engineState.aiManagedSymbols)) return;

  engineState.aiManagedSymbols = engineState.aiManagedSymbols.filter(
    (item) => normalizeSymbol(item) !== clean
  );

  saveEngineState("AI_MANAGED_SYMBOL_REMOVED");
}

function isAiManagedOpenPosition(position = {}, aiOwnedSymbols = new Set()) {
  const symbol = normalizeSymbol(position.symbol);

  if (!symbol) return false;

  const managedSymbols = new Set(
    Array.isArray(engineState.aiManagedSymbols)
      ? engineState.aiManagedSymbols.map((item) => normalizeSymbol(item))
      : []
  );

  return (
    aiOwnedSymbols.has(symbol) ||
    managedSymbols.has(symbol) ||
    Boolean(engineState.aiEntryScores?.[symbol])
  );
}

function clearAiManagedPositionState(symbol) {
  const clean = normalizeSymbol(symbol);

  if (!clean) return;

  delete engineState.highWaterMarks[clean];
  delete engineState.aiEntryScores[clean];
  delete engineState.runnerPositions[clean];

  unmarkAiManagedSymbol(clean);
}

