function getReinforcementLearnedMultiplier(confidenceScore = 0) {
  const score = Number(confidenceScore || 0);

  const confidenceBand =
    score >= 85
      ? "ELITE_CONFIDENCE"
      : score >= 75
        ? "HIGH_CONFIDENCE"
        : score >= 65
          ? "NORMAL_CONFIDENCE"
          : "LOW_CONFIDENCE";

  const bandStats =
    engineState.reinforcementWeightState?.confidenceBands?.[
    confidenceBand
    ];

  const learnedMultiplier = Number(
    bandStats?.learnedMultiplier || 1
  );

  return {
    confidenceBand,
    learnedMultiplier,
    bandStats: bandStats || null,
  };
}

function calculatePhase7ReinforcementLearning(signal = {}) {
  const symbol = normalizeSymbol(signal.symbol);
  const setupType = classifyInstitutionalSetup(signal);

  const regimeKey =
    signal.marketRegime ||
    engineState.marketRegime?.state ||
    "unknown_regime";

  const sectorKey =
    signal.estimatedSector ||
    signal.sector ||
    "General Market";

  const setupStats =
    engineState.statisticalMemoryState?.setupPerformance?.[setupType] ||
    {};

  const strategyStats =
    engineState.strategyPerformanceState?.[
    signal.strategy || setupType
    ] || {};

  const regimeStats =
    engineState.regimePerformanceState?.[regimeKey] || {};

  const sectorStats =
    engineState.sectorPerformanceState?.[sectorKey] || {};

  const confirmationKeys = [
    signal.confirmations?.aboveVwap === true ? "ABOVE_VWAP" : "BELOW_VWAP",
    signal.confirmations?.closeNearHigh === true ? "CLOSE_NEAR_HIGH" : "WEAK_CLOSE",
    signal.confirmations?.volumeSpike === true ? "VOLUME_SPIKE" : "NO_VOLUME_SPIKE",
    signal.confirmations?.fakeBreakout === true ? "FAKE_BREAKOUT" : "NO_FAKE_BREAKOUT",
  ];

  const confirmationStats = confirmationKeys
    .map((key) => engineState.confirmationPerformanceState?.[key])
    .filter(Boolean);

  const reviewedBuckets = [
    setupStats,
    strategyStats,
    regimeStats,
    sectorStats,
    ...confirmationStats,
  ].filter((bucket) => Number(bucket.trades || bucket.exits || 0) > 0);

  const weightedTrust =
    reviewedBuckets.length > 0
      ? reviewedBuckets.reduce((sum, bucket) => {
        const trades = Number(bucket.trades || bucket.exits || 0);
        const winRate = Number(bucket.winRate || 50);
        const averageProfitPercent = Number(bucket.averageProfitPercent || 0);
        const expectancyScore = Number(
          bucket.expectancyScore ||
          clampScore(50 + (winRate - 50) * 0.6 + averageProfitPercent * 4)
        );

        return sum + expectancyScore * Math.min(1.5, Math.max(0.75, trades / 5));
      }, 0) /
      reviewedBuckets.reduce((sum, bucket) => {
        const trades = Number(bucket.trades || bucket.exits || 0);
        return sum + Math.min(1.5, Math.max(0.75, trades / 5));
      }, 0)
      : 50;

  const runnerScore = Number(
    signal.runnerScore ||
    signal.explosiveRunnerScore ||
    signal.explosiveRunnerPrediction?.explosiveRunnerScore ||
    signal.adaptiveRunnerScore ||
    0
  );

  const institutionalBrainScore = Number(
    signal.institutionalBrainScore ||
    signal.fullInstitutionalAiBrain?.dynamicConvictionScore ||
    0
  );

  const baseScore = Number(signal.score || 0);

  const setupTrustScore = clampScore(
    weightedTrust +
    (runnerScore >= 80 ? 6 : 0) +
    (institutionalBrainScore >= 80 ? 5 : 0) +
    (baseScore >= 85 ? 4 : 0) -
    (signal.confirmations?.fakeBreakout ? 15 : 0)
  );

  const probabilityAdjustment =
    setupTrustScore >= 78
      ? 6
      : setupTrustScore >= 68
        ? 3
        : setupTrustScore <= 35
          ? -9
          : setupTrustScore <= 45
            ? -5
            : 0;

  const learnedSizingMultiplier =
    setupTrustScore >= 80
      ? 1.15
      : setupTrustScore >= 70
        ? 1.08
        : setupTrustScore <= 35
          ? 0.72
          : setupTrustScore <= 45
            ? 0.85
            : 1;

  const suppressEntry =
    setupTrustScore <= 38 &&
    baseScore < 82 &&
    runnerScore < 80 &&
    institutionalBrainScore < 82;

  const trustLabel =
    setupTrustScore >= 80
      ? "ELITE_LEARNED_SETUP"
      : setupTrustScore >= 68
        ? "TRUSTED_SETUP"
        : setupTrustScore <= 38
          ? "SUPPRESSED_WEAK_SETUP"
          : setupTrustScore <= 48
            ? "LOW_TRUST_SETUP"
            : "NEUTRAL_SETUP";

  return {
    phase: "7_REINFORCEMENT_LEARNING_EXPANSION",
    updatedAt: new Date().toISOString(),
    symbol,
    setupType,
    regimeKey,
    sectorKey,
    confirmationKeys,
    reviewedBucketCount: reviewedBuckets.length,
    setupTrustScore,
    trustLabel,
    probabilityAdjustment,
    learnedSizingMultiplier,
    suppressEntry,
    reason:
      `${trustLabel} • Setup ${setupType} • Trust ${setupTrustScore}/100 • ` +
      `Probability adjustment ${probabilityAdjustment} • Size x${learnedSizingMultiplier}`,
  };
}

function updatePhase7ReinforcementLearningState(signals = []) {
  const reviewed = signals.map((signal) => {
    const phase7 =
      signal.phase7Reinforcement ||
      calculatePhase7ReinforcementLearning(signal);

    return {
      symbol: signal.symbol,
      score: signal.score,
      setupType: phase7.setupType,
      setupTrustScore: phase7.setupTrustScore,
      trustLabel: phase7.trustLabel,
      probabilityAdjustment: phase7.probabilityAdjustment,
      learnedSizingMultiplier: phase7.learnedSizingMultiplier,
      suppressEntry: phase7.suppressEntry,
    };
  });

  const suppressed = reviewed.filter((item) => item.suppressEntry);
  const trusted = reviewed.filter(
    (item) => Number(item.setupTrustScore || 0) >= 68
  );

  const averageSetupTrust =
    reviewed.length > 0
      ? reviewed.reduce((sum, item) => sum + Number(item.setupTrustScore || 0), 0) /
      reviewed.length
      : 50;

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "7_REINFORCEMENT_LEARNING_EXPANSION",
    reviewedCount: reviewed.length,
    trustedSetupCount: trusted.length,
    suppressedSetupCount: suppressed.length,
    averageSetupTrust: Number(averageSetupTrust.toFixed(2)),
    strongestLearnedSetups: reviewed
      .filter((item) => Number(item.setupTrustScore || 0) >= 68)
      .sort((a, b) => b.setupTrustScore - a.setupTrustScore)
      .slice(0, 10),
    suppressedSetups: suppressed.slice(0, 10),
    reason:
      `Phase 7 reviewed ${reviewed.length} signals, trusted ${trusted.length}, ` +
      `and suppressed ${suppressed.length} weak learned setups.`,
  };

  engineState.probabilityReinforcementState = {
    ...(engineState.probabilityReinforcementState || {}),
    updatedAt: new Date().toISOString(),
    phase: "7_REINFORCEMENT_LEARNING_EXPANSION",
    setupTrust: {
      ...(engineState.probabilityReinforcementState?.setupTrust || {}),
      ...Object.fromEntries(
        reviewed.map((item) => [
          item.symbol,
          {
            setupType: item.setupType,
            setupTrustScore: item.setupTrustScore,
            trustLabel: item.trustLabel,
            probabilityAdjustment: item.probabilityAdjustment,
            learnedSizingMultiplier: item.learnedSizingMultiplier,
            suppressEntry: item.suppressEntry,
            updatedAt: new Date().toISOString(),
          },
        ])
      ),
    },
    latestState: state,
  };

  if (!Array.isArray(engineState.probabilityReinforcementHistory)) {
    engineState.probabilityReinforcementHistory = [];
  }

  engineState.probabilityReinforcementHistory.unshift(state);
  engineState.probabilityReinforcementHistory =
    engineState.probabilityReinforcementHistory.slice(0, 200);

  saveEngineState("PHASE_7_REINFORCEMENT_LEARNING_UPDATED");

  return state;
}

function updateInstitutionalMarketMemoryFromClosedTrade(
  closedTrade = {},
  setupType = "GENERAL_SETUP"
) {
  if (!engineState.statisticalMemoryState) {
    engineState.statisticalMemoryState = {
      updatedAt: null,
      setupHistory: [],
      setupPerformance: {},
      expectancyHistory: [],
      probabilityHistory: [],
    };
  }

  const profitPercent = Number(closedTrade.profitPercent || 0);
  const isWin = profitPercent > 0;

  const regimeKey =
    closedTrade.marketRegime || "unknown_regime";

  const sectorKey =
    closedTrade.sector || "General Market";

  const strategyKey =
    closedTrade.strategy || setupType || "institutional_momentum";

  const confirmations = closedTrade.confirmations || {};

  const confirmationKeys = [
    confirmations.aboveVwap === true ? "ABOVE_VWAP" : "BELOW_VWAP",
    confirmations.closeNearHigh === true ? "CLOSE_NEAR_HIGH" : "WEAK_CLOSE",
    confirmations.volumeSpike === true ? "VOLUME_SPIKE" : "NO_VOLUME_SPIKE",
    confirmations.fakeBreakout === true ? "FAKE_BREAKOUT" : "NO_FAKE_BREAKOUT",
  ];

  function updateMemoryBucket(store, key) {
    if (!store[key]) {
      store[key] = {
        key,
        trades: 0,
        wins: 0,
        losses: 0,
        totalProfitPercent: 0,
        averageProfitPercent: 0,
        winRate: 0,
        expectancyScore: 50,
        trustMultiplier: 1,
        lastUpdated: null,
      };
    }

    const bucket = store[key];

    bucket.trades += 1;
    if (isWin) bucket.wins += 1;
    if (profitPercent < 0) bucket.losses += 1;

    bucket.totalProfitPercent =
      Number(bucket.totalProfitPercent || 0) + profitPercent;

    bucket.averageProfitPercent = Number(
      (
        bucket.totalProfitPercent /
        Math.max(1, bucket.trades)
      ).toFixed(2)
    );

    bucket.winRate = Number(
      ((bucket.wins / Math.max(1, bucket.trades)) * 100).toFixed(2)
    );

    bucket.expectancyScore = clampScore(
      50 +
      bucket.averageProfitPercent * 4 +
      (bucket.winRate - 50) * 0.6
    );

    bucket.trustMultiplier =
      bucket.trades < 5
        ? 1
        : bucket.expectancyScore >= 70
          ? 1.08
          : bucket.expectancyScore <= 40
            ? 0.88
            : 1;

    bucket.lastUpdated = new Date().toISOString();

    return bucket;
  }

  const setupMemory =
    updateMemoryBucket(
      engineState.statisticalMemoryState.setupPerformance,
      setupType
    );

  const strategyMemory =
    updateMemoryBucket(
      engineState.strategyPerformanceState,
      strategyKey
    );

  const regimeMemory =
    updateMemoryBucket(
      engineState.regimePerformanceState,
      regimeKey
    );

  const sectorMemory =
    updateMemoryBucket(
      engineState.sectorPerformanceState,
      sectorKey
    );

  const confirmationMemory = confirmationKeys.map((key) =>
    updateMemoryBucket(
      engineState.confirmationPerformanceState,
      key
    )
  );

  const snapshot = {
    updatedAt: new Date().toISOString(),
    symbol: closedTrade.symbol,
    setupType,
    strategyKey,
    regimeKey,
    sectorKey,
    profitPercent,
    setupExpectancyScore: setupMemory.expectancyScore,
    strategyExpectancyScore: strategyMemory.expectancyScore,
    regimeExpectancyScore: regimeMemory.expectancyScore,
    sectorExpectancyScore: sectorMemory.expectancyScore,
    confirmationKeys,
    reason:
      `Market memory updated • Setup ${setupMemory.expectancyScore}/100 • ` +
      `Regime ${regimeMemory.expectancyScore}/100 • Sector ${sectorMemory.expectancyScore}/100`,
  };

  engineState.statisticalMemoryState.expectancyHistory.unshift(snapshot);
  engineState.statisticalMemoryState.expectancyHistory =
    engineState.statisticalMemoryState.expectancyHistory.slice(0, 300);

  engineState.statisticalMemoryState.probabilityHistory.unshift({
    updatedAt: new Date().toISOString(),
    symbol: closedTrade.symbol,
    setupType,
    winRate: setupMemory.winRate,
    averageProfitPercent: setupMemory.averageProfitPercent,
    trustMultiplier: setupMemory.trustMultiplier,
  });

  engineState.statisticalMemoryState.probabilityHistory =
    engineState.statisticalMemoryState.probabilityHistory.slice(0, 300);

  engineState.statisticalMemoryState.updatedAt =
    new Date().toISOString();

  return {
    snapshot,
    setupMemory,
    strategyMemory,
    regimeMemory,
    sectorMemory,
    confirmationMemory,
  };
}

function updateExecutionStyleMemoryFromClosedTrade(closedTrade = {}) {
  if (!engineState.executionStyleMemoryState) {
    engineState.executionStyleMemoryState = {};
  }

  if (!Array.isArray(engineState.executionStyleMemoryHistory)) {
    engineState.executionStyleMemoryHistory = [];
  }

  const executionStyle =
    closedTrade.executionStyle ||
    closedTrade.centralCoreExecutionStyle ||
    closedTrade.centralCoreExecution?.executionStyle ||
    "UNKNOWN_EXECUTION_STYLE";

  const tradeArchetype =
    closedTrade.tradeArchetype ||
    classifyTradeArchetype(closedTrade);

  const profitPercent = Number(closedTrade.profitPercent || 0);
  const isWin = profitPercent > 0;

  const key = `${tradeArchetype}_${executionStyle}`;

  const current =
    engineState.executionStyleMemoryState[key] || {
      key,
      tradeArchetype,
      executionStyle,
      trades: 0,
      wins: 0,
      losses: 0,
      totalProfitPercent: 0,
      averageProfitPercent: 0,
      winRate: 0,
      executionTrustScore: 50,
      executionTrustMultiplier: 1,
      lastUpdated: null,
    };

  current.trades += 1;
  if (isWin) current.wins += 1;
  if (profitPercent < 0) current.losses += 1;

  current.totalProfitPercent =
    Number(current.totalProfitPercent || 0) + profitPercent;

  current.averageProfitPercent = Number(
    (
      current.totalProfitPercent /
      Math.max(1, current.trades)
    ).toFixed(2)
  );

  current.winRate = Number(
    ((current.wins / Math.max(1, current.trades)) * 100).toFixed(2)
  );

  current.executionTrustScore = clampScore(
    50 +
    current.averageProfitPercent * 5 +
    (current.winRate - 50) * 0.7
  );

  current.executionTrustMultiplier =
    current.trades < 5
      ? 1
      : current.executionTrustScore >= 75
        ? 1.12
        : current.executionTrustScore >= 65
          ? 1.06
          : current.executionTrustScore <= 38
            ? 0.82
            : current.executionTrustScore <= 45
              ? 0.9
              : 1;

  current.lastUpdated = new Date().toISOString();

  engineState.executionStyleMemoryState[key] = current;

  const snapshot = {
    updatedAt: new Date().toISOString(),
    symbol: closedTrade.symbol,
    tradeArchetype,
    executionStyle,
    profitPercent,
    executionTrustScore: current.executionTrustScore,
    executionTrustMultiplier: current.executionTrustMultiplier,
    stats: current,
    reason:
      `${executionStyle} for ${tradeArchetype} now has trust ` +
      `${current.executionTrustScore}/100 and multiplier x${current.executionTrustMultiplier}`,
  };

  engineState.executionStyleMemoryHistory.unshift(snapshot);
  engineState.executionStyleMemoryHistory =
    engineState.executionStyleMemoryHistory.slice(0, 300);

  return snapshot;
}

