function updateReinforcementWeightStateFromClosedTrade(closedTrade = {}) {
  const confidenceScore = Number(
    closedTrade.autonomousConfidenceScore || 0
  );

  const profitPercent = Number(closedTrade.profitPercent || 0);

  const confidenceBand =
    confidenceScore >= 85
      ? "ELITE_CONFIDENCE"
      : confidenceScore >= 75
        ? "HIGH_CONFIDENCE"
        : confidenceScore >= 65
          ? "NORMAL_CONFIDENCE"
          : "LOW_CONFIDENCE";

  if (!engineState.reinforcementWeightState) {
    engineState.reinforcementWeightState = {
      updatedAt: null,
      confidenceBands: {},
      totalReviewedTrades: 0,
    };
  }

  const current =
    engineState.reinforcementWeightState.confidenceBands[
    confidenceBand
    ] || {
      trades: 0,
      wins: 0,
      losses: 0,
      totalProfitPercent: 0,
      averageProfitPercent: 0,
      winRate: 0,
      learnedMultiplier: 1,
    };

  current.trades += 1;

  if (profitPercent > 0) current.wins += 1;
  if (profitPercent < 0) current.losses += 1;

  current.totalProfitPercent =
    Number(current.totalProfitPercent || 0) + profitPercent;

  current.averageProfitPercent = Number(
    (
      current.totalProfitPercent /
      Math.max(1, current.trades)
    ).toFixed(2)
  );

  current.winRate = Number(
    ((current.wins / Math.max(1, current.trades)) * 100).toFixed(2)
  );

  current.learnedMultiplier =
    current.trades < 5
      ? 1
      : current.winRate >= 65 && current.averageProfitPercent > 0
        ? 1.08
        : current.winRate <= 40 || current.averageProfitPercent < 0
          ? 0.88
          : 1;

  engineState.reinforcementWeightState.confidenceBands[
    confidenceBand
  ] = current;

  engineState.reinforcementWeightState.updatedAt =
    new Date().toISOString();

  engineState.reinforcementWeightState.totalReviewedTrades =
    Number(
      engineState.reinforcementWeightState.totalReviewedTrades || 0
    ) + 1;

  if (!Array.isArray(engineState.reinforcementWeightHistory)) {
    engineState.reinforcementWeightHistory = [];
  }

  const snapshot = {
    updatedAt: new Date().toISOString(),
    symbol: closedTrade.symbol,
    confidenceBand,
    confidenceScore,
    profitPercent,
    learnedMultiplier: current.learnedMultiplier,
    bandStats: current,
  };

  engineState.reinforcementWeightHistory.unshift(snapshot);
  engineState.reinforcementWeightHistory =
    engineState.reinforcementWeightHistory.slice(0, 200);

  return snapshot;
}

function updateExitOutcomeLearningState(closedTrade = {}) {
  const exitReason = String(
    closedTrade.exitReason || "UNKNOWN_EXIT"
  );

  const assetClass = String(
    closedTrade.assetClass || "stock"
  );

  const profitPercent = Number(
    closedTrade.profitPercent || 0
  );

  const key = `${assetClass}_${exitReason}`;

  if (!engineState.smartExitIntelligenceState) {
    engineState.smartExitIntelligenceState = {
      updatedAt: null,
      exitReasonPerformance: {},
      totalReviewedExits: 0,
    };
  }

  if (!engineState.smartExitIntelligenceState.exitReasonPerformance) {
    engineState.smartExitIntelligenceState.exitReasonPerformance = {};
  }

  const current =
    engineState.smartExitIntelligenceState.exitReasonPerformance[key] || {
      key,
      assetClass,
      exitReason,
      exits: 0,
      wins: 0,
      losses: 0,
      totalProfitPercent: 0,
      averageProfitPercent: 0,
      winRate: 0,
      exitQuality: "UNPROVEN_EXIT",
      suggestedAdjustment: "KEEP_DEFAULT",
    };

  current.exits += 1;

  if (profitPercent > 0) current.wins += 1;
  if (profitPercent < 0) current.losses += 1;

  current.totalProfitPercent =
    Number(current.totalProfitPercent || 0) + profitPercent;

  current.averageProfitPercent = Number(
    (
      current.totalProfitPercent /
      Math.max(1, current.exits)
    ).toFixed(2)
  );

  current.winRate = Number(
    ((current.wins / Math.max(1, current.exits)) * 100).toFixed(2)
  );

  current.exitQuality =
    current.exits < 5
      ? "UNPROVEN_EXIT"
      : current.winRate >= 60 && current.averageProfitPercent > 0
        ? "STRONG_EXIT"
        : current.winRate <= 40 || current.averageProfitPercent < 0
          ? "WEAK_EXIT"
          : "NEUTRAL_EXIT";

  current.suggestedAdjustment =
    current.exitQuality === "STRONG_EXIT"
      ? "TRUST_THIS_EXIT"
      : current.exitQuality === "WEAK_EXIT"
        ? "REVIEW_OR_DELAY_IF_RUNNER"
        : "KEEP_DEFAULT";

  engineState.smartExitIntelligenceState.exitReasonPerformance[key] =
    current;

  engineState.smartExitIntelligenceState.updatedAt =
    new Date().toISOString();

  engineState.smartExitIntelligenceState.totalReviewedExits =
    Number(
      engineState.smartExitIntelligenceState.totalReviewedExits || 0
    ) + 1;

  if (!Array.isArray(engineState.smartExitIntelligenceHistory)) {
    engineState.smartExitIntelligenceHistory = [];
  }

  const snapshot = {
    updatedAt: new Date().toISOString(),
    symbol: closedTrade.symbol,
    assetClass,
    exitReason,
    profitPercent,
    exitQuality: current.exitQuality,
    suggestedAdjustment: current.suggestedAdjustment,
    stats: current,
  };

  engineState.smartExitIntelligenceHistory.unshift(snapshot);
  engineState.smartExitIntelligenceHistory =
    engineState.smartExitIntelligenceHistory.slice(0, 200);

  return snapshot;
}

function getExitReinforcementAdjustment(exitReason = "UNKNOWN_EXIT", assetClass = "stock") {
  const key = `${assetClass}_${exitReason}`;
  const stats =
    engineState.smartExitIntelligenceState?.exitReasonPerformance?.[key];

  if (!stats || Number(stats.exits || 0) < 5) {
    return {
      exitLearningMultiplier: 1,
      exitLearningQuality: "UNPROVEN_EXIT",
      reason: "Not enough exit history yet.",
    };
  }

  if (stats.exitQuality === "STRONG_EXIT") {
    return {
      exitLearningMultiplier: 1.1,
      exitLearningQuality: "STRONG_EXIT",
      stats,
      reason: "Historically strong exit type.",
    };
  }

  if (stats.exitQuality === "WEAK_EXIT") {
    return {
      exitLearningMultiplier: 0.85,
      exitLearningQuality: "WEAK_EXIT",
      stats,
      reason: "Historically weak exit type; delay if runner is still strong.",
    };
  }

  return {
    exitLearningMultiplier: 1,
    exitLearningQuality: "NEUTRAL_EXIT",
    stats,
    reason: "Neutral exit history.",
  };
}

function calculateRunnerExitDelayGate({
  symbol,
  reason,
  isRunner,
  unrealizedPercent,
  dropFromHigh,
  trendQualityHold,
  trendHoldDecision,
  exitLearningAdjustment,
}) {
  const emergencyReasons = [
    "STOP_LOSS",
    "EXIT_PARLIAMENT_EMERGENCY_EXIT",
    "CLIMAX_DISTRIBUTION_EXIT",
    "INSTITUTIONAL_FORCE_EXIT",
  ];

  if (emergencyReasons.includes(reason)) {
    return {
      shouldDelayExit: false,
      reason: "Emergency exit allowed.",
    };
  }

  const strongRunner =
    isRunner &&
    unrealizedPercent >= 4 &&
    dropFromHigh <= 2.5 &&
    (
      trendQualityHold?.shouldExtendHold === true ||
      trendHoldDecision?.mode === "TREND_HOLD" ||
      exitLearningAdjustment?.exitLearningQuality === "WEAK_EXIT"
    );

  if (strongRunner) {
    return {
      shouldDelayExit: true,
      symbol,
      reason:
        "Strong runner still has trend quality; delaying non-emergency exit.",
    };
  }

  return {
    shouldDelayExit: false,
    reason: "Normal exit allowed.",
  };
}

function calculateWeakSetupFastExitGate({
  symbol,
  unrealizedPercent,
  dropFromHigh,
  isRunner,
}) {
  const entry = engineState.aiEntryScores?.[symbol] || {};

  const weakScore = Number(entry.score || 0) < 62;
  const weakTechnical = Number(entry.technicalScore || 0) > 0 &&
    Number(entry.technicalScore || 0) < 55;
  const weakStatistical = Number(entry.statisticalScore || 0) > 0 &&
    Number(entry.statisticalScore || 0) < 55;

  const fading =
    unrealizedPercent < -1.2 ||
    dropFromHigh >= 4;

  if (!isRunner && fading && (weakScore || weakTechnical || weakStatistical)) {
    return {
      shouldFastExit: true,
      reason:
        "Weak non-runner setup is fading; fast exit protection triggered.",
      weakScore,
      weakTechnical,
      weakStatistical,
    };
  }

  return {
    shouldFastExit: false,
    reason: "No weak setup fast exit.",
  };
}

function calculateInstitutionalProfitExtraction({
  symbol,
  unrealizedPercent,
  dropFromHigh,
  isRunner,
  highWater,
  currentPrice,
}) {
  const entry = engineState.aiEntryScores?.[symbol] || {};

  const entryScore = Number(entry.score || 0);
  const institutionalBrainScore = Number(
    entry.institutionalBrainScore ||
    entry.autonomousConfidenceScore ||
    0
  );

  const technicalScore = Number(entry.technicalScore || 0);
  const statisticalScore = Number(entry.statisticalScore || 0);

  const trendPersistenceScore = Number(
    engineState.trendPersistenceState?.heldSymbols?.[symbol]
      ?.trendPersistenceScore || 0
  );

  const winnerStrengthScore = clampScore(
    unrealizedPercent * 3 +
    entryScore * 0.18 +
    institutionalBrainScore * 0.18 +
    technicalScore * 0.16 +
    statisticalScore * 0.14 +
    trendPersistenceScore * 0.14 -
    dropFromHigh * 4
  );

  const pressWinner =
    isRunner &&
    unrealizedPercent >= 8 &&
    dropFromHigh <= 1.5 &&
    winnerStrengthScore >= 72;

  const protectWinner =
    unrealizedPercent >= 5 &&
    dropFromHigh >= 3 &&
    winnerStrengthScore < 65;

  const trimWinner =
    unrealizedPercent >= 10 &&
    dropFromHigh >= 1.5 &&
    dropFromHigh <= 4 &&
    winnerStrengthScore >= 65;

  const dynamicRunnerTrailingStopPercent =
    pressWinner
      ? unrealizedPercent >= 20
        ? 3.5
        : unrealizedPercent >= 12
          ? 2.5
          : 2
      : protectWinner
        ? 1
        : CONFIG.runnerTrailingStopPercent;

  return {
    phase: "36_INSTITUTIONAL_PROFIT_EXTRACTION",
    updatedAt: new Date().toISOString(),
    winnerStrengthScore,
    pressWinner,
    protectWinner,
    trimWinner,
    dynamicRunnerTrailingStopPercent,
    reason:
      `${pressWinner ? "PRESS_WINNER" : protectWinner ? "PROTECT_WINNER" : trimWinner ? "TRIM_WINNER" : "NORMAL_WINNER_MANAGEMENT"} • ` +
      `WinnerStrength ${winnerStrengthScore}/100 • Profit ${unrealizedPercent.toFixed(2)}% • Drop ${dropFromHigh.toFixed(2)}%`,
  };
}

function calculateSmartTrimDecision({
  symbol,
  qty,
  unrealizedPercent,
  dropFromHigh,
  isRunner,
}) {
  const shouldTrim =
    isRunner &&
    qty > 1 &&
    unrealizedPercent >= 8 &&
    dropFromHigh >= 1.2 &&
    dropFromHigh <= 3.5;

  const trimQty = shouldTrim
    ? Math.max(1, Math.floor(qty * 0.35))
    : 0;

  return {
    shouldTrim,
    trimQty,
    reason: shouldTrim
      ? "Runner has profit and mild pullback; trim partial instead of full exit."
      : "No smart trim needed.",
  };
}

function updateReloadReentryMemory({
  symbol,
  reason,
  unrealizedPercent,
  isRunner,
}) {
  if (!engineState.institutionalReloadState) {
    engineState.institutionalReloadState = {
      updatedAt: null,
      reloadWatchlist: {},
    };
  }

  if (!engineState.institutionalReloadState.reloadWatchlist) {
    engineState.institutionalReloadState.reloadWatchlist = {};
  }

  const eligible =
    isRunner &&
    unrealizedPercent > 3 &&
    [
      "RUNNER_TRAILING_STOP",
      "PROFIT_PROTECTION",
      "TRAILING_STOP",
      "SMART_TRIM_EXIT",
    ].includes(reason);

  if (!eligible) {
    return {
      reloadEligible: false,
      reason: "Not reload eligible.",
    };
  }

  const reloadRecord = {
    symbol,
    lastExitAt: new Date().toISOString(),
    lastExitReason: reason,
    lastProfitPercent: Number(unrealizedPercent.toFixed(2)),
    reloadStatus: "WATCH_FOR_RESET",
    reason:
      "Winner exited; watch for reset and re-entry strength.",
  };

  engineState.institutionalReloadState.reloadWatchlist[symbol] =
    reloadRecord;
  engineState.institutionalReloadState.updatedAt =
    new Date().toISOString();

  if (!Array.isArray(engineState.institutionalReloadHistory)) {
    engineState.institutionalReloadHistory = [];
  }

  engineState.institutionalReloadHistory.unshift(reloadRecord);
  engineState.institutionalReloadHistory =
    engineState.institutionalReloadHistory.slice(0, 200);

  return {
    reloadEligible: true,
    reloadRecord,
  };
}

function calculateOvernightHoldRiskGate({
  symbol,
  unrealizedPercent,
  isRunner,
}) {
  const minutes = getEasternMarketMinutes();
  const nearClose = minutes >= 15 * 60 + 30;

  if (!nearClose) {
    return {
      shouldProtectBeforeClose: false,
      reason: "Not near market close.",
    };
  }

  const entry = engineState.aiEntryScores?.[symbol] || {};

  const strongEnoughToHold =
    isRunner &&
    unrealizedPercent >= 5 &&
    (
      Number(entry.score || 0) >= 72 ||
      Number(entry.autonomousConfidenceScore || 0) >= 75 ||
      Number(entry.institutionalBrainScore || 0) >= 72
    );

  return {
    shouldProtectBeforeClose: !strongEnoughToHold,
    strongEnoughToHold,
    reason: strongEnoughToHold
      ? "Strong runner can be considered for overnight hold."
      : "Near close and not strong enough; protect before close.",
  };
}

function updateExitDashboardState(snapshot = {}) {
  engineState.institutionalExitOrchestratorState = {
    ...(engineState.institutionalExitOrchestratorState || {}),
    updatedAt: new Date().toISOString(),
    latestExitCalibration: snapshot,
  };

  if (!Array.isArray(engineState.institutionalExitOrchestratorHistory)) {
    engineState.institutionalExitOrchestratorHistory = [];
  }

  engineState.institutionalExitOrchestratorHistory.unshift({
    updatedAt: new Date().toISOString(),
    ...snapshot,
  });

  engineState.institutionalExitOrchestratorHistory =
    engineState.institutionalExitOrchestratorHistory.slice(0, 200);
}

function journalTradeEntry(symbol, entry = {}) {
  ensureTradeJournalState();

  const cleanSymbol = normalizeSymbol(symbol);

  if (!cleanSymbol) return;

  engineState.tradeJournalOpenEntries[cleanSymbol] = {
    symbol: cleanSymbol,
    entryType: entry.entryType || "AI_ENTRY",
    assetClass: entry.assetClass || "stock",
    entryPrice: Number(entry.entryPrice || 0),
    score: Number(entry.score || 0),
    strategy: entry.strategy || "institutional_momentum",
    sector: entry.sector || "General Market",
    marketRegime:
      entry.marketRegime ||
      engineState.marketRegime?.state ||
      "unknown",
    confirmations: entry.confirmations || {},
    portfolioManager: entry.portfolioManager || null,
    institutionalExecutionPlan:
      entry.institutionalExecutionPlan || null,
    autonomousConfidenceScore:
      Number(entry.autonomousConfidenceScore || 0),
    autonomousConfidenceMultiplier:
      Number(entry.autonomousConfidenceMultiplier || 1),
    regimeProtectionMultiplier:
      Number(entry.regimeProtectionMultiplier || 1),
    tradeAmount: Number(entry.tradeAmount || 0),
    reinforcementSizing:
      entry.reinforcementSizing || null,
    enteredAt: new Date().toISOString(),
  };

  saveEngineState("TRADE_JOURNAL_ENTRY");
}

function journalTradeExit(symbol, exit = {}) {
  ensureTradeJournalState();

  const cleanSymbol = normalizeSymbol(symbol);

  if (!cleanSymbol) return;

  const entry =
    engineState.tradeJournalOpenEntries[cleanSymbol] || {};

  const profitPercent = Number(exit.profitPercent || 0);

  const closedTrade = {
    symbol: cleanSymbol,
    assetClass: exit.assetClass || entry.assetClass || "stock",
    entryType: entry.entryType || "AI_ENTRY",
    exitType: exit.exitType || "AI_EXIT",
    strategy: entry.strategy || exit.strategy || "institutional_momentum",
    sector: entry.sector || exit.sector || "General Market",
    marketRegime:
      entry.marketRegime ||
      exit.marketRegime ||
      engineState.marketRegime?.state ||
      "unknown",
    entryPrice: Number(entry.entryPrice || 0),
    exitPrice: Number(exit.exitPrice || 0),
    score: Number(entry.score || exit.score || 0),
    tradeAmount: Number(entry.tradeAmount || 0),
    profitPercent,
    exitReason: exit.exitReason || "UNKNOWN_EXIT",
    confirmations: entry.confirmations || {},
    portfolioManager: entry.portfolioManager || null,
    institutionalExecutionPlan:
      entry.institutionalExecutionPlan || null,
    autonomousConfidenceScore:
      Number(entry.autonomousConfidenceScore || 0),
    autonomousConfidenceMultiplier:
      Number(entry.autonomousConfidenceMultiplier || 1),
    regimeProtectionMultiplier:
      Number(entry.regimeProtectionMultiplier || 1),
    enteredAt: entry.enteredAt || null,
    reinforcementSizing:
      entry.reinforcementSizing || null,
    tradeArchetype:
      entry.tradeArchetype ||
      exit.tradeArchetype ||
      null,
    executionStyle:
      entry.executionStyle ||
      exit.executionStyle ||
      entry.centralCoreExecution?.executionStyle ||
      exit.centralCoreExecution?.executionStyle ||
      null,

    centralCoreExecution:
      entry.centralCoreExecution ||
      exit.centralCoreExecution ||
      null,
    exitedAt: new Date().toISOString(),
  };

  const executionStyleMemorySnapshot =
    updateExecutionStyleMemoryFromClosedTrade(closedTrade);

  const archetypeMemorySnapshot =
    updateArchetypeMemoryFromClosedTrade(closedTrade);

  const reinforcementSnapshot =
    updateReinforcementWeightStateFromClosedTrade(closedTrade);

  const exitOutcomeLearningSnapshot =
    updateExitOutcomeLearningState(closedTrade);

  if (!engineState.statisticalMemoryState) {
    engineState.statisticalMemoryState = {
      updatedAt: new Date().toISOString(),
      setupHistory: [],
      setupPerformance: {},
      expectancyHistory: [],
      probabilityHistory: [],
    };
  }

  const setupType = classifyInstitutionalSetup({
    symbol: cleanSymbol,
    score: closedTrade.score,
    assetClass: closedTrade.assetClass,
    marketRegime: closedTrade.marketRegime,
    confirmations: closedTrade.confirmations,
    portfolioManager: closedTrade.portfolioManager,
  });

  engineState.statisticalMemoryState.setupHistory.unshift({
    timestamp: new Date().toISOString(),
    symbol: cleanSymbol,
    setupType,
    profitPercent,
    score: closedTrade.score,
    assetClass: closedTrade.assetClass,
    marketRegime: closedTrade.marketRegime,
    exitReason: closedTrade.exitReason,
  });

  engineState.statisticalMemoryState.setupHistory =
    engineState.statisticalMemoryState.setupHistory.slice(0, 500);

  const institutionalMarketMemorySnapshot =
    updateInstitutionalMarketMemoryFromClosedTrade(
      closedTrade,
      setupType
    );

  engineState.statisticalMemoryState.updatedAt =
    new Date().toISOString();

  engineState.tradeJournalHistory.unshift(closedTrade);
  engineState.tradeJournalHistory =
    engineState.tradeJournalHistory.slice(0, 500);

  engineState.tradeJournalState.totalClosedTrades += 1;

  if (profitPercent > 0) {
    engineState.tradeJournalState.winningTrades += 1;
  } else if (profitPercent < 0) {
    engineState.tradeJournalState.losingTrades += 1;
  } else {
    engineState.tradeJournalState.breakevenTrades += 1;
  }

  engineState.tradeJournalState.totalProfitPercent =
    Number(engineState.tradeJournalState.totalProfitPercent || 0) +
    profitPercent;

  engineState.tradeJournalState.averageProfitPercent =
    Number(
      (
        engineState.tradeJournalState.totalProfitPercent /
        Math.max(1, engineState.tradeJournalState.totalClosedTrades)
      ).toFixed(2)
    );

  engineState.tradeJournalState.winRate =
    Number(
      (
        (engineState.tradeJournalState.winningTrades /
          Math.max(1, engineState.tradeJournalState.totalClosedTrades)) *
        100
      ).toFixed(2)
    );

  if (
    !engineState.tradeJournalState.bestTrade ||
    profitPercent >
    Number(engineState.tradeJournalState.bestTrade.profitPercent || 0)
  ) {
    engineState.tradeJournalState.bestTrade = closedTrade;
  }

  if (
    !engineState.tradeJournalState.worstTrade ||
    profitPercent <
    Number(engineState.tradeJournalState.worstTrade.profitPercent || 0)
  ) {
    engineState.tradeJournalState.worstTrade = closedTrade;
  }

  engineState.tradeJournalState.lastUpdated =
    new Date().toISOString();

  delete engineState.tradeJournalOpenEntries[cleanSymbol];

  saveEngineState("TRADE_JOURNAL_EXIT");
}


function canRunSwingSafeRotation(position = {}, context = {}) {
  const todayKey = getTodayKeyET();

  if (engineState.lastRotationDateKey !== todayKey) {
    engineState.lastRotationDateKey = todayKey;
    engineState.rotationCountToday = 0;
  }

  if (
    Number(engineState.rotationCountToday || 0) >=
    Number(CONFIG.maxRotationsPerDay || engineState.maxRotationsPerDay || 6)
  ) {
    return {
      allowed: false,
      reason: "Daily rotation limit reached",
    };
  }

  const profitPercent = Number(position.unrealized_plpc || 0) * 100;
  const scoreGap = Number(context.scoreGap || 0);
  const requiredGap = Number(CONFIG.replaceWeakestMinScoreGap || 8);
  const emergencyGap = requiredGap + 5;

  if (scoreGap < requiredGap) {
    return {
      allowed: false,
      reason: `Replacement score gap ${scoreGap.toFixed(2)} is below required ${requiredGap}`,
    };
  }

  if (profitPercent >= 2 && scoreGap < emergencyGap) {
    return {
      allowed: false,
      reason: "Position is profitable; only emergency-grade score upgrade can rotate it",
    };
  }

  return {
    allowed: true,
    reason: `Rotation allowed: replacement is ${scoreGap.toFixed(2)} points stronger`,
  };
}

function markSwingSafeRotationUsed(symbol, replacementSymbol) {
  engineState.lastRotationDateKey = getTodayKeyET();
  engineState.rotationCountToday =
    Number(engineState.rotationCountToday || 0) + 1;

  saveRecentOrder("SWING_SAFE_ROTATION_USED", symbol, {
    replacementSymbol,
    rotationCountToday: engineState.rotationCountToday,
    maxRotationsPerDay: Number(CONFIG.maxRotationsPerDay || engineState.maxRotationsPerDay || 6),
  });

  saveEngineState("SWING_SAFE_ROTATION_USED");
}

function saveRecentOrder(type, symbol, extra = {}) {
  engineState.recentOrders.unshift({
    type,
    symbol,
    at: new Date().toISOString(),
    ...extra,
  });

  pushBackendStreamEvent("ORDER_EVENT", {
    type,
    symbol,
    ...extra,
  });

  if (/PENDING_EXIT|EXIT_PENDING|TRAILING|STOP|LIMIT_EXIT|SELL_ORDER/i.test(String(type || ""))) {
    pushBackendStreamEvent("EXIT_PENDING", {
      type,
      symbol,
      ...extra,
    });
  }

  if (/RISK_BLOCK|BLOCKED_MACRO_RISK|TRADING_BLOCKED/i.test(String(type || ""))) {
    pushBackendStreamEvent("RISK_BLOCK", {
      scope: "ORDER_LOG",
      type,
      symbol,
      ...extra,
    });
  }

  engineState.recentOrders = engineState.recentOrders.slice(0, 100);
  saveEngineState("RECENT_ORDER");
}

function getSignalTapeApproval(signal = {}) {
  if (signal.finalTradeApproval) {
    return String(signal.finalTradeApproval);
  }

  if (signal.phase6ScoringLayers?.finalTradeApproval) {
    return String(signal.phase6ScoringLayers.finalTradeApproval);
  }

  if (signal.qualifiedToBuy === true && signal.autoTradeApproved === true) {
    return "APPROVED";
  }

  if (signal.autoTradeApproved === false || signal.approved === false) {
    return "BLOCKED";
  }

  return "WATCHLIST";
}

function getSignalTapeRiskBlocked(signal = {}) {
  return Boolean(
    signal.phase6ScoringLayers?.hardReject === true ||
    signal.centralCoreHardBlock === true ||
    signal.portfolioHardBlock === true ||
    signal.riskBlocked === true ||
    signal.autoTradeApproved === false ||
    signal.finalTradeApproval === "BLOCK" ||
    signal.finalTradeApproval === "REJECT_WEAK_TIMING"
  );
}

function emitSignalTapeTransitions(signals = []) {
  if (!engineState.previousSignalTapeSnapshot) {
    engineState.previousSignalTapeSnapshot = {};
  }

  const now = new Date().toISOString();

  for (const signal of signals) {
    const symbol = normalizeSymbol(signal.symbol);
    if (!symbol) continue;

    const current = {
      symbol,
      score: Number(signal.score || 0),
      approval: getSignalTapeApproval(signal),
      decisionLevel: signal.decisionLevel || "",
      riskBlocked: getSignalTapeRiskBlocked(signal),
      source: signal.source || "",
      updatedAt: now,
    };

    const previous = engineState.previousSignalTapeSnapshot[symbol];

    if (previous) {
      const scoreChange =
        Number(current.score || 0) - Number(previous.score || 0);

      if (scoreChange >= 5) {
        broadcastBackendTapeEvent("SIGNAL_UPGRADED", {
          symbol,
          previousScore: previous.score,
          currentScore: current.score,
          scoreChange: Number(scoreChange.toFixed(2)),
          previousApproval: previous.approval,
          currentApproval: current.approval,
          decisionLevel: current.decisionLevel,
        });
      }

      if (scoreChange <= -5) {
        broadcastBackendTapeEvent("SIGNAL_DOWNGRADED", {
          symbol,
          previousScore: previous.score,
          currentScore: current.score,
          scoreChange: Number(scoreChange.toFixed(2)),
          previousApproval: previous.approval,
          currentApproval: current.approval,
          decisionLevel: current.decisionLevel,
        });
      }

      if (previous.approval !== current.approval) {
        broadcastBackendTapeEvent("APPROVAL_CHANGED", {
          symbol,
          previousApproval: previous.approval,
          currentApproval: current.approval,
          previousScore: previous.score,
          currentScore: current.score,
          decisionLevel: current.decisionLevel,
        });
      }

      if (!previous.riskBlocked && current.riskBlocked) {
        broadcastBackendTapeEvent("RISK_BLOCK", {
          symbol,
          score: current.score,
          approval: current.approval,
          decisionLevel: current.decisionLevel,
          reason:
            signal.finalRejectionReason ||
            signal.portfolioManagerReason ||
            signal.reason ||
            "Signal became risk-blocked.",
        });
      }
    } else if (current.score >= 85 || current.approval === "APPROVED") {
      broadcastBackendTapeEvent("SIGNAL_UPGRADED", {
        symbol,
        previousScore: null,
        currentScore: current.score,
        scoreChange: current.score,
        previousApproval: null,
        currentApproval: current.approval,
        decisionLevel: current.decisionLevel,
        reason: "New high-conviction signal entered the live tape.",
      });
    }

    engineState.previousSignalTapeSnapshot[symbol] = current;
  }

  const liveSymbols = new Set(signals.map((signal) => normalizeSymbol(signal.symbol)));

  for (const symbol of Object.keys(engineState.previousSignalTapeSnapshot)) {
    if (!liveSymbols.has(symbol)) {
      delete engineState.previousSignalTapeSnapshot[symbol];
    }
  }
}

function emitSystemRiskTapeState(extra = {}) {
  const marketCrashProtection =
    engineState.marketCrashProtectionState || {};

  const blocked =
    marketCrashProtection?.shouldBlockNewTrades === true ||
    engineState.portfolioGovernorState?.shouldBlockNewTrades === true ||
    (
      engineState.macroRiskState?.shouldBlockNewTrades === true &&
      engineState.macroProbeOverrideState?.allowed !== true
    ) ||
    autoTradingEnabled === false;

  const current = {
    blocked,
    marketCrashBlock: marketCrashProtection?.shouldBlockNewTrades === true,
    portfolioGovernorBlock:
      engineState.portfolioGovernorState?.shouldBlockNewTrades === true,
    macroRiskBlock:
      engineState.macroRiskState?.shouldBlockNewTrades === true &&
      engineState.macroProbeOverrideState?.allowed !== true,
    autoTradingEnabled,
    marketRegime: engineState.marketRegime?.state || null,
    updatedAt: new Date().toISOString(),
    ...extra,
  };

  const previous = engineState.previousSystemRiskTapeState || null;

  if (
    current.blocked &&
    (
      !previous ||
      previous.blocked !== current.blocked ||
      previous.marketCrashBlock !== current.marketCrashBlock ||
      previous.portfolioGovernorBlock !== current.portfolioGovernorBlock ||
      previous.macroRiskBlock !== current.macroRiskBlock
    )
  ) {
    broadcastBackendTapeEvent("RISK_BLOCK", {
      scope: "SYSTEM",
      ...current,
      reason:
        extra.reason ||
        engineState.macroProbeOverrideState?.reason ||
        "System risk controls blocked new trade deployment.",
    });
  }

  engineState.previousSystemRiskTapeState = current;
}

function getEngineFreshness() {
  const lastScanTime = engineState.lastScanAt
    ? new Date(engineState.lastScanAt).getTime()
    : 0;

  const ageSeconds = lastScanTime
    ? Math.round((Date.now() - lastScanTime) / 1000)
    : null;

  return {
    lastScanAt: engineState.lastScanAt,
    ageSeconds,
    stale: ageSeconds === null || ageSeconds > 180,
    staleAfterSeconds: 180,
  };
}

function getMarketSession(clock = {}) {
  if (clock?.is_open === true) {
    return "regular";
  }

  const nowET = new Date(
    new Date().toLocaleString("en-US", {
      timeZone: "America/New_York",
    })
  );

  const hour = nowET.getHours();
  const minute = nowET.getMinutes();
  const minutes = hour * 60 + minute;

  const premarketStart = 4 * 60;
  const regularStart = 9 * 60 + 30;
  const regularEnd = 16 * 60;
  const afterhoursEnd = 20 * 60;

  if (minutes >= premarketStart && minutes < regularStart) {
    return "premarket";
  }

  if (minutes >= regularEnd && minutes < afterhoursEnd) {
    return "afterhours";
  }

  return "closed";
}

function getLatestLiveQuoteUpdateAt() {
  const quotes = Object.values(engineState.liveQuoteCache || {});

  return quotes.reduce((latest, quote) => {
    const time = quote?.updatedAt
      ? new Date(quote.updatedAt).getTime()
      : 0;

    if (!time || !Number.isFinite(time)) return latest;

    return !latest || time > new Date(latest).getTime()
      ? quote.updatedAt
      : latest;
  }, null);
}

