function buildLiveQuotesPayload(symbols = []) {
  const requestedSymbols = symbols
    .map(normalizeSymbol)
    .filter(Boolean);

  const entries = Object.entries(engineState.liveQuoteCache || {})
    .filter(([symbol]) => {
      return requestedSymbols.length === 0 || requestedSymbols.includes(symbol);
    })
    .map(([symbol, quote]) => {
      const memory = engineState.liveMarketMemory?.[symbol] || {};

      return {
        symbol,
        price: Number(quote?.price || quote?.current || 0),
        current: Number(quote?.current || quote?.price || 0),
        bid: Number(quote?.bid || memory.bid || 0),
        ask: Number(quote?.ask || memory.ask || 0),
        spread: Number(quote?.spread || memory.spread || 0),
        spreadPercent: Number(quote?.spreadPercent || memory.spreadPercent || 0),
        volume: Number(quote?.volume || memory.lastVolume || 0),
        change: Number(quote?.change || 0),
        percentChange: Number(
          quote?.displayPercent ??
          quote?.todayPercent ??
          quote?.livePercentChange ??
          quote?.percentChange ??
          0
        ),
        todayPercent: Number(quote?.todayPercent || memory.todayPercent || 0),
        afterhoursPercent: Number(quote?.afterhoursPercent || memory.afterhoursPercent || 0),
        intradayPercent: Number(quote?.intradayPercent || memory.intradayPercent || 0),
        displayPercent: Number(quote?.displayPercent || memory.displayPercent || 0),
        displayPercentLabel:
          quote?.displayPercentLabel ||
          memory.displayPercentLabel ||
          "Today",
        source: quote?.source || "live_cache",
        livePrice: Number(quote?.price || quote?.current || 0),
        displayPrice: Number(quote?.price || quote?.current || 0),
        liveQuoteSource:
          quote?.liveQuoteSource ||
          quote?.source ||
          "live_cache",
        liveQuoteUpdatedAt:
          quote?.liveQuoteUpdatedAt ||
          quote?.updatedAt ||
          null,
        priceIsLive: quote?.priceIsLive === true,
        updatedAt: quote?.updatedAt || null,
        previousPrice: quote?.previousPrice || null,
        liveMoveFromPreviousPercent:
          Number(quote?.liveMoveFromPreviousPercent || 0),
        fastRunnerScore: Number(
          quote?.fastRunnerScore || memory.fastRunnerScore || 0
        ),
        liveMomentumPercent: Number(
          quote?.liveMomentumPercent || memory.liveMomentumPercent || 0
        ),
        tapeSpeed: Number(quote?.tapeSpeed || memory.tapeSpeed || 0),
        liquidityPressure: Number(
          quote?.liquidityPressure || memory.liquidityPressure || 0
        ),
        fastRunnerBreakdown: memory.fastRunnerBreakdown || null,
        oneSecondCandles:
          memory.secondCandles?.slice(-20) ||
          quote?.oneSecondCandles ||
          [],
      };
    })
    .filter((quote) => quote.price > 0)
    .sort((a, b) => String(a.symbol).localeCompare(String(b.symbol)));

  return {
    generatedAt: new Date().toISOString(),
    marketSession: getMarketSession({
      is_open: Boolean(engineState.marketOpen),
    }),
    polygonLiveStreamState: engineState.polygonLiveStreamState || null,
    finnhubLiveStreamState: engineState.liveQuoteStreamState || null,
    count: entries.length,
    quotes: entries,
  };
}


function buildQuoteFreshnessEngine(quote = {}) {
  const updatedAt = quote?.updatedAt || quote?.timestamp || null;

  const ageSeconds = updatedAt
    ? Math.max(
      0,
      Math.round(
        (Date.now() - new Date(updatedAt).getTime()) / 1000
      )
    )
    : null;

  const marketSession = getMarketSession({
    is_open: Boolean(engineState.marketOpen),
  });

  const session = String(marketSession || "closed");

  const maxFreshAgeSeconds =
    session === "regular"
      ? 20
      : session === "premarket" ||
        session === "afterhours"
        ? 45
        : 180;

  const freshnessLabel =
    ageSeconds === null
      ? "NO_TIMESTAMP"
      : ageSeconds <= maxFreshAgeSeconds
        ? "FRESH"
        : ageSeconds <= maxFreshAgeSeconds * 3
          ? "AGING"
          : "STALE";

  return {
    updatedAt,
    ageSeconds,
    maxFreshAgeSeconds,
    freshnessLabel,
    isFresh: freshnessLabel === "FRESH",
    isStale: freshnessLabel === "STALE",
    marketSession: session,
  };
}

function buildLiquiditySnapshot(signalOrQuote = {}) {
  const price = Number(
    signalOrQuote.price ||
    signalOrQuote.current ||
    signalOrQuote.c ||
    signalOrQuote.last ||
    0
  );

  const volume = Number(
    signalOrQuote.volume ||
    signalOrQuote.v ||
    signalOrQuote.lastVolume ||
    signalOrQuote.avgVolume ||
    0
  );

  const dollarVolume = Number(
    signalOrQuote.dollarVolume ||
    signalOrQuote.notional ||
    (price > 0 && volume > 0 ? price * volume : 0)
  );

  const spreadPercent = Number(
    signalOrQuote.spreadPercent ||
    signalOrQuote.spreadPct ||
    signalOrQuote.spread ||
    0
  );

  const relativeVolume = Number(
    signalOrQuote.relativeVolume ||
    signalOrQuote.volumeRatio ||
    signalOrQuote.confirmations?.volumeSpikeRatio ||
    0
  );

  const liquidityScore = clampScore(
    35 +
    (dollarVolume >= 5000000
      ? 25
      : dollarVolume >= 1000000
        ? 18
        : dollarVolume >= 250000
          ? 10
          : 0) +
    (volume >= 1000000
      ? 18
      : volume >= 250000
        ? 10
        : volume >= 50000
          ? 5
          : 0) +
    (relativeVolume >= 3 ? 15 : relativeVolume >= 1.5 ? 9 : 0) -
    (spreadPercent >= 2
      ? 25
      : spreadPercent >= 1
        ? 14
        : spreadPercent >= 0.5
          ? 6
          : 0)
  );

  return {
    price,
    volume,
    dollarVolume: Number(dollarVolume.toFixed(2)),
    relativeVolume,
    spreadPercent,
    liquidityScore,
    liquidityLabel:
      liquidityScore >= 80
        ? "INSTITUTIONAL_LIQUIDITY"
        : liquidityScore >= 65
          ? "STABLE_LIQUIDITY"
          : liquidityScore >= 45
            ? "THIN_BUT_TRADEABLE"
            : "LIQUIDITY_RISK",
  };
}

function calculateFifteenPhaseMarketScanner(signal = {}) {
  const percentChange = Number(signal.percentChange || 0);

  const relativeVolume = Number(
    signal.relativeVolume ||
    signal.volumeRatio ||
    signal.confirmations?.volumeSpikeRatio ||
    0
  );

  const marketMomentum = Number(engineState.marketMomentumScore || 0);

  const session = getMarketSession({
    is_open: Boolean(engineState.marketOpen),
  });

  const unusualVolume =
    relativeVolume >= 1.5 ||
    signal.confirmations?.volumeSpike === true;

  const momentumAcceleration =
    percentChange >= 2 &&
    percentChange <= CONFIG.maxPercentChange;

  const relativeStrengthVsMarket =
    percentChange - marketMomentum;

  const compressionBeforeBreakout = Boolean(
    signal.phase41InstitutionalCompression?.compressionDetected ||
    signal.institutionalCompression?.compressionDetected ||
    signal.volatilityContraction === true ||
    (Math.abs(percentChange) <= 2 && relativeVolume >= 1.25)
  );

  const scannerScore = clampScore(
    40 +
    (unusualVolume ? 18 : 0) +
    (relativeVolume >= 3 ? 14 : relativeVolume >= 2 ? 9 : 0) +
    (momentumAcceleration ? 14 : 0) +
    (session === "premarket" &&
      percentChange >= CONFIG.minPremarketGapPercent
      ? 12
      : 0) +
    (session === "afterhours" && percentChange > 0 ? 8 : 0) +
    (relativeStrengthVsMarket >= 2
      ? 10
      : relativeStrengthVsMarket <= -2
        ? -8
        : 0) +
    (compressionBeforeBreakout ? 10 : 0)
  );

  return {
    phase: "2_INSTITUTIONAL_MARKET_SCANNER",
    updatedAt: new Date().toISOString(),
    scannerScore,
    unusualVolume,
    relativeVolumeExpansion: relativeVolume,
    sectorRotation: engineState.sectorRotationState || null,
    momentumAcceleration,
    premarketStrength: session === "premarket" && percentChange > 0,
    afterHoursContinuation:
      session === "afterhours" && percentChange > 0,
    relativeStrengthVsMarket: Number(
      relativeStrengthVsMarket.toFixed(2)
    ),
    compressionBeforeBreakout,
    candidateUniverseQualified: scannerScore >= 62,
  };
}

function calculateFifteenPhaseRunnerIntelligence(signal = {}) {
  const percentChange = Number(signal.percentChange || 0);

  const relativeVolume = Number(
    signal.relativeVolume ||
    signal.volumeRatio ||
    signal.confirmations?.volumeSpikeRatio ||
    0
  );

  const rsi = Number(signal.technicals?.rsi || 50);
  const macd = Number(signal.technicals?.macd || 0);
  const macdSignal = Number(signal.technicals?.macdSignal || 0);

  const phase5 =
    signal.phase5SignalQuality ||
    calculatePhase5InstitutionalSignalQuality(signal);

  const accumulationScore = clampScore(
    45 +
    (relativeVolume >= 1.5 ? 15 : 0) +
    (signal.confirmations?.closeNearHigh ? 12 : 0) +
    (signal.confirmations?.aboveVwap ? 12 : 0) -
    phase5.candleRejectionRisk * 0.2
  );

  const multiTimeframeAlignment = clampScore(
    45 +
    (macd > macdSignal ? 15 : -8) +
    (rsi >= 45 && rsi <= 72 ? 12 : rsi > 80 ? -15 : 0) +
    Number(
      signal.multiTimeframe?.alignmentScore ||
      signal.multiTimeframeScore ||
      0
    ) *
    0.25
  );

  const volatilityContraction = clampScore(
    55 -
    Math.min(35, Math.abs(percentChange) * 1.2) +
    Number(signal.phase41InstitutionalCompression?.compressionScore || 0) *
    0.25
  );

  const breakoutPressure = clampScore(
    40 +
    (percentChange > 0 ? 12 : -8) +
    (relativeVolume >= 2 ? 18 : relativeVolume >= 1.25 ? 10 : 0) +
    (signal.confirmations?.aboveVwap ? 12 : -8) +
    (phase5.breakoutRetestConfirmation ? 10 : 0)
  );

  const runnerProbabilityScore = clampScore(
    accumulationScore * 0.28 +
    multiTimeframeAlignment * 0.22 +
    volatilityContraction * 0.18 +
    breakoutPressure * 0.22 +
    Number(signal.score || 0) * 0.1 -
    phase5.exhaustionRisk * 0.18
  );

  const continuationProbability = clampScore(
    runnerProbabilityScore +
    (signal.confirmations?.closeNearHigh ? 8 : -5) -
    (phase5.antiChaseRisk > 75 ? 12 : 0)
  );

  const squeezeProbability = clampScore(
    35 +
    (Number(signal.shortInterestPercent || 0) >= 20 ? 25 : 0) +
    (signal.lowFloat === true ||
      (Number(signal.floatShares || 0) > 0 &&
        Number(signal.floatShares || 0) <= 20000000)
      ? 18
      : 0) +
    (relativeVolume >= 3 ? 15 : 0) +
    (percentChange > 0 ? 8 : 0)
  );

  const expansionProbability = clampScore(
    runnerProbabilityScore * 0.55 +
    continuationProbability * 0.25 +
    squeezeProbability * 0.2
  );

  return {
    phase: "3_INSTITUTIONAL_RUNNER_INTELLIGENCE",
    updatedAt: new Date().toISOString(),
    accumulationScore,
    liquidityAbsorptionScore:
      signal.liquidityStabilityScore ||
      phase5.liquidityStabilityScore,
    hiddenBuyingPressureScore: accumulationScore,
    multiTimeframeAlignment,
    volatilityContraction,
    breakoutPressure,
    runnerProbabilityScore,
    continuationProbability,
    squeezeProbability,
    expansionProbability,
    runnerLabel:
      expansionProbability >= 82
        ? "ELITE_EXPANSION_CANDIDATE"
        : expansionProbability >= 70
          ? "HIGH_PROBABILITY_RUNNER"
          : expansionProbability >= 58
            ? "WATCHLIST_RUNNER"
            : "LOW_RUNNER_PROBABILITY",
  };
}

function calculateFifteenPhaseCatalystIntelligence(signal = {}) {
  const text = String(
    signal.newsTitle ||
    signal.newsHeadline ||
    signal.catalystText ||
    signal.reason ||
    ""
  ).toLowerCase();

  const earningsBeat = Boolean(
    signal.earningsBeat ||
    /earnings beat|beats estimates|beat estimates/.test(text)
  );

  const raisedGuidance = Boolean(
    signal.raisedGuidance ||
    /raised guidance|raises guidance|guidance hike|higher guidance/.test(
      text
    )
  );

  const analystUpgrade = Boolean(
    signal.analystUpgrade ||
    /upgrade|price target raised|strong buy/.test(text)
  );

  const unusualOptionsActivity = Boolean(
    signal.unusualOptionsActivity ||
    Number(signal.optionsVolumeRatio || 0) >= 5
  );

  const insiderBuying = Boolean(
    signal.insiderBuying ||
    signal.form4InsiderBuying ||
    /insider buying|form 4/.test(text)
  );

  const shortInterestPercent = Number(
    signal.shortInterestPercent ||
    signal.shortInterest ||
    0
  );

  const highShortInterest = shortInterestPercent >= 20;

  const floatShares = Number(signal.floatShares || signal.float || 0);

  const lowFloat = Boolean(
    signal.lowFloat ||
    (floatShares > 0 && floatShares <= 20000000)
  );

  const newsMomentum = Boolean(
    signal.newsMomentum ||
    signal.hasNews ||
    text.length > 0
  );

  const sectorMomentum = Number(
    engineState.sectorRotationState?.strongestSectorScore ||
    signal.sectorMomentumScore ||
    0
  );

  const catalystStrength = clampScore(
    25 +
    (earningsBeat ? 15 : 0) +
    (raisedGuidance ? 16 : 0) +
    (analystUpgrade ? 10 : 0) +
    (unusualOptionsActivity ? 13 : 0) +
    (insiderBuying ? 12 : 0) +
    (highShortInterest ? 12 : 0) +
    (lowFloat ? 8 : 0) +
    (newsMomentum ? 8 : 0) +
    (sectorMomentum >= 70 ? 8 : sectorMomentum >= 55 ? 4 : 0)
  );

  return {
    phase: "4_CATALYST_INTELLIGENCE",
    updatedAt: new Date().toISOString(),
    catalystStrength,
    earningsBeat,
    raisedGuidance,
    analystUpgrade,
    unusualOptionsActivity,
    insiderBuying,
    shortInterestPercent,
    highShortInterest,
    floatShares: floatShares || null,
    lowFloat,
    newsMomentum,
    sectorMomentumScore: sectorMomentum,
    catalystLabel:
      catalystStrength >= 80
        ? "ELITE_CATALYST_STACK"
        : catalystStrength >= 65
          ? "STRONG_CATALYST"
          : catalystStrength >= 50
            ? "MODERATE_CATALYST"
            : "WEAK_OR_UNKNOWN_CATALYST",
  };
}

function applyFifteenPhaseInstitutionalArchitecture(signal = {}) {
  const scanner = calculateFifteenPhaseMarketScanner(signal);
  const runner = calculateFifteenPhaseRunnerIntelligence(signal);
  const catalyst = calculateFifteenPhaseCatalystIntelligence(signal);
  const liquiditySnapshot = buildLiquiditySnapshot(signal);

  signal.phase2MarketScanner = scanner;
  signal.phase3RunnerIntelligence = runner;
  signal.phase4CatalystIntelligence = catalyst;
  signal.liquiditySnapshot = liquiditySnapshot;

  signal.runnerProbabilityScore = runner.runnerProbabilityScore;
  signal.continuationProbability = runner.continuationProbability;
  signal.squeezeProbability = runner.squeezeProbability;
  signal.expansionProbability = runner.expansionProbability;

  signal.institutionalCatalystStrength = catalyst.catalystStrength;
  signal.candidateUniverseQualified =
    scanner.candidateUniverseQualified;

  signal.fifteenPhaseSummary = {
    updatedAt: new Date().toISOString(),
    marketScannerScore: scanner.scannerScore,
    runnerProbabilityScore: runner.runnerProbabilityScore,
    catalystStrength: catalyst.catalystStrength,
    signalQualityScore:
      signal.signalQualityScore ||
      signal.phase5SignalQuality?.qualityScore ||
      null,
    entryTimingScore:
      signal.entryTimingScore ||
      signal.phase6ScoringLayers?.entryTimingScore ||
      null,
    executionConfidence:
      signal.executionConfidence ||
      signal.phase6ScoringLayers?.executionConfidence ||
      null,
    liquidityScore: liquiditySnapshot.liquidityScore,
  };

  return signal;
}


function saveSkippedSymbol(symbol, reason) {
  engineState.skippedSymbols.unshift({
    symbol,
    reason,
    at: new Date().toISOString(),
  });

  engineState.skippedSymbols = engineState.skippedSymbols.slice(0, 150);
  saveEngineState("SKIPPED_SYMBOL");
}

function getBotExposure(openPositions = []) {
  return openPositions.reduce((sum, position) => {
    return sum + Math.abs(Number(position.market_value || 0));
  }, 0);
}

function getEasternMarketMinutes() {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: "America/New_York",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).formatToParts(new Date());

  const hour = Number(parts.find((part) => part.type === "hour")?.value || 0);
  const minute = Number(parts.find((part) => part.type === "minute")?.value || 0);

  return hour * 60 + minute;
}

function isPremarketMomentumWindow() {
  const minutes = getEasternMarketMinutes();

  return minutes >= 4 * 60 && minutes < 9 * 60 + 30;
}

function isMorningStrikeWindow() {
  const minutes = getEasternMarketMinutes();

  const startMinutes =
    Number(CONFIG.morningStrikeStartHourET || 9) * 60 + 30;

  const endMinutes =
    Number(CONFIG.morningStrikeEndHourET || 11) * 60;

  return minutes >= startMinutes && minutes <= endMinutes;
}

function calculateGapContinuationIntelligence(signal = {}) {
  const confirmations = signal.confirmations || {};

  const percentChange = Number(
    signal.percentChange ||
    signal.changePercent ||
    0
  );

  const relativeVolume = Number(
    signal.relativeVolume ||
    signal.volumeRatio ||
    signal.volumeSpikeRatio ||
    confirmations.volumeSpikeRatio ||
    0
  );

  const closeNearHighPercent = Number(
    confirmations.closeNearHighPercent || 0
  );

  const pullbackFromHighPercent = Number(
    confirmations.pullbackFromHighPercent || 0
  );

  const aboveVwap = confirmations.aboveVwap === true;
  const fakeBreakout = confirmations.fakeBreakout === true;

  const premarketContinuationRelief =
    !engineState.marketOpen &&
    (
      isPremarketMomentumWindow() ||
      isMorningStrikeWindow()
    ) &&
    Number(
      signal.premarketContinuationScore ||
      signal.premarketDominanceScore ||
      signal.openingDriveProbability ||
      signal.continuationProbability ||
      signal.breakoutProbability ||
      0
    ) >= 70;

  const gapContinuationScore = clampScore(
    45 +
    (percentChange >= 5 ? 10 : 0) +
    (percentChange >= 15 ? 10 : 0) +
    (relativeVolume >= 2 ? 12 : 0) +
    (relativeVolume >= 4 ? 10 : 0) +
    (closeNearHighPercent >= 80 ? 12 : 0) +
    (aboveVwap ? 10 : premarketContinuationRelief ? 4 : 0) -
    (pullbackFromHighPercent >= 3 ? (premarketContinuationRelief ? 5 : 15) : 0) -
    (pullbackFromHighPercent >= 6 ? (premarketContinuationRelief ? 7 : 15) : 0) -
    (fakeBreakout ? (premarketContinuationRelief ? 8 : 25) : 0) -
    (percentChange >= 80 ? (premarketContinuationRelief ? 8 : 20) : 0)
  );

  const gapFadeRisk = clampScore(
    35 +
    (percentChange >= 50 ? (premarketContinuationRelief ? 6 : 15) : 0) +
    (percentChange >= 80 ? (premarketContinuationRelief ? 10 : 25) : 0) +
    (pullbackFromHighPercent >= 3 ? (premarketContinuationRelief ? 5 : 15) : 0) +
    (pullbackFromHighPercent >= 6 ? (premarketContinuationRelief ? 7 : 20) : 0) +
    (relativeVolume < 1.5 ? 15 : 0) +
    (fakeBreakout ? (premarketContinuationRelief ? 8 : 25) : 0) -
    (aboveVwap ? 10 : premarketContinuationRelief ? 4 : 0) -
    (closeNearHighPercent >= 80 ? 10 : 0)
  );

  const openingRangeBreakoutProbability = clampScore(
    gapContinuationScore * 0.7 +
    (100 - gapFadeRisk) * 0.3
  );

  const gapContinuationLabel =
    openingRangeBreakoutProbability >= 80
      ? "HIGH_CONTINUATION_GAP"
      : openingRangeBreakoutProbability >= 65
        ? "WATCH_CONTINUATION_GAP"
        : gapFadeRisk >= 70
          ? "HIGH_FADE_RISK"
          : "NEUTRAL_GAP";

  return {
    gapContinuationScore,
    gapFadeRisk,
    openingRangeBreakoutProbability,
    gapContinuationLabel,
  };
}

function calculateFloatRotationIntelligence(signal = {}) {
  const symbol = normalizeSymbol(signal.symbol);

  const price = Number(signal.current || signal.price || 0);

  const volume = Number(
    signal.volume ||
    signal.barVolume ||
    0
  );

  const relativeVolume = Number(
    signal.volumeRatio ||
    signal.relativeVolume ||
    signal.volumeSpikeRatio ||
    signal.confirmations?.volumeSpikeRatio ||
    0
  );

  const percentChange = Number(
    signal.percentChange ||
    signal.changePercent ||
    signal.change ||
    0
  );

  const floatRotationScore = clampScore(
    40 +
    (relativeVolume >= 2 ? 18 : 0) +
    (relativeVolume >= 4 ? 18 : 0) +
    (percentChange >= 15 ? 12 : 0) +
    (percentChange >= 30 ? 12 : 0) +
    (volume >= 50000 ? 8 : 0) -
    (price > 150 ? 12 : 0)
  );

  const squeezeProbability = clampScore(
    floatRotationScore +
    (relativeVolume >= 5 ? 20 : 0) +
    (percentChange >= 25 ? 15 : 0)
  );

  const dilutionRisk = clampScore(
    20 +
    (price < 2 ? 20 : 0) +
    (relativeVolume >= 8 ? 15 : 0)
  );

  const floatRotationLabel =
    squeezeProbability >= 85
      ? "HIGH_SQUEEZE_ROTATION"
      : squeezeProbability >= 70
        ? "ROTATION_BREAKOUT"
        : dilutionRisk >= 70
          ? "DILUTION_RISK"
          : "NORMAL_ROTATION";

  return {
    symbol,
    floatRotationScore,
    squeezeProbability,
    dilutionRisk,
    floatRotationLabel,
    relativeVolume,
  };
}

function calculatePremarketMomentumEngine(signal = {}) {
  const symbol = normalizeSymbol(signal.symbol);

  const currentPrice = Number(
    signal.current ||
    signal.price ||
    signal.c ||
    0
  );

  const previousClose = Number(
    signal.previousClose ||
    signal.prevClose ||
    signal.pc ||
    0
  );

  const percentChange = Number(
    signal.percentChange ||
    signal.changePercent ||
    (
      previousClose > 0 && currentPrice > 0
        ? ((currentPrice - previousClose) / previousClose) * 100
        : 0
    )
  );

  const confirmations = signal.confirmations || {};

  const premarketContinuationRelief =
    !engineState.marketOpen &&
    (
      isPremarketMomentumWindow() ||
      isMorningStrikeWindow()
    ) &&
    Number(
      signal.premarketContinuationScore ||
      signal.premarketDominanceScore ||
      signal.openingDriveProbability ||
      signal.continuationProbability ||
      signal.breakoutProbability ||
      0
    ) >= 70;

  const volume = Number(
    signal.volume ||
    signal.barVolume ||
    confirmations.lastVolume ||
    0
  );

  const averageVolume = Number(
    signal.averageVolume ||
    signal.avgVolume ||
    signal.avgDailyVolume ||
    signal.avgBarVolume ||
    confirmations.avgVolume ||
    0
  );

  const relativeVolume = Number(
    signal.relativeVolume ||
    signal.volumeRatio ||
    signal.volumeSpikeRatio ||
    confirmations.volumeSpikeRatio ||
    (
      averageVolume > 0 && volume > 0
        ? (volume / averageVolume).toFixed(2)
        : 0
    )
  );

  const riskyHeadlineText = (
    confirmations.riskyNewsHeadlines ||
    signal.newsHeadlines ||
    []
  )
    .join(" ")
    .toLowerCase();

  const catalystWords = [
    "earnings",
    "revenue",
    "guidance",
    "fda",
    "approval",
    "contract",
    "partnership",
    "acquisition",
    "buyout",
    "merger",
    "upgrade",
    "analyst",
    "ai",
    "patent",
    "trial",
    "phase 2",
    "phase 3",
    "record",
  ];

  const negativeCatalystWords = [
    "offering",
    "bankruptcy",
    "delisting",
    "investigation",
    "lawsuit",
    "downgrade",
    "misses",
    "cuts guidance",
    "weak guidance",
  ];

  const catalystHits = catalystWords.filter((word) =>
    riskyHeadlineText.includes(word)
  );

  const negativeCatalystHits = negativeCatalystWords.filter((word) =>
    riskyHeadlineText.includes(word)
  );

  const catalystQualityScore = clampScore(
    45 +
    catalystHits.length * 10 -
    negativeCatalystHits.length * 18 +
    (riskyHeadlineText.includes("offering") ? -25 : 0) +
    (riskyHeadlineText.includes("reverse split") ? -25 : 0) +
    (riskyHeadlineText.includes("bankruptcy") ? -35 : 0) +
    (riskyHeadlineText.includes("fda approval") ? 25 : 0) +
    (riskyHeadlineText.includes("contract") ? 18 : 0) +
    (riskyHeadlineText.includes("acquisition") ? 20 : 0) +
    (riskyHeadlineText.includes("buyout") ? 25 : 0) +
    (riskyHeadlineText.includes("earnings") && percentChange > 0 ? 15 : 0)
  );

  const catalystRiskLabel =
    catalystQualityScore >= 80
      ? "STRONG_POSITIVE_CATALYST"
      : catalystQualityScore >= 65
        ? "POSITIVE_CATALYST"
        : catalystQualityScore <= 30
          ? "DANGEROUS_CATALYST"
          : "NO_CLEAR_CATALYST";


  const gapStrengthScore = clampScore(
    40 +
    (percentChange >= Number(CONFIG.minPremarketGapPercent || 5) ? 15 : 0) +
    (percentChange >= 10 ? 15 : 0) +
    (percentChange >= 20 ? 10 : 0) +
    (percentChange >= 40 ? 5 : 0) -
    (percentChange <= 0 ? 25 : 0)
  );

  const relativeVolumeScore = clampScore(
    35 +
    (relativeVolume >= Number(CONFIG.minPremarketRelativeVolume || 3) ? 20 : 0) +
    (relativeVolume >= 5 ? 15 : 0) +
    (relativeVolume >= 10 ? 15 : 0) +
    (volume >= Number(CONFIG.minVolume || 4000) ? 10 : -15)
  );

  const catalystStrength = clampScore(
    catalystQualityScore +
    (catalystRiskLabel === "STRONG_POSITIVE_CATALYST" ? 10 : 0) -
    (catalystRiskLabel === "DANGEROUS_CATALYST" ? 20 : 0)
  );

  const floatRotation =
    calculateFloatRotationIntelligence(signal);

  const gapContinuation =
    calculateGapContinuationIntelligence(signal);

  const liquidityQuality = clampScore(
    35 +
    (volume >= 1000000 ? 35 : 0) +
    (volume >= 250000 ? 20 : 0) +
    (volume >= 50000 ? 10 : 0) +
    (currentPrice >= Number(CONFIG.minStockPrice || 1) ? 10 : -20)
  );

  const premarketTrendScore = clampScore(
    40 +
    (percentChange > 0 ? 15 : -20) +
    (relativeVolume >= 3 ? 15 : 0) +
    (confirmations.closeNearHigh ? 10 : 0) +
    (confirmations.aboveVwap ? 10 : 0) -
    (confirmations.fakeBreakout ? 20 : 0)
  );

  const fadeRisk = clampScore(
    35 +
    (percentChange >= 50 ? 20 : 0) +
    (relativeVolume < 1.5 ? 20 : 0) +
    (confirmations.fakeBreakout ? (premarketContinuationRelief ? 8 : 25) : 0) +
    (negativeCatalystHits.length > 0 ? 20 : 0) -
    (relativeVolume >= 5 ? 15 : 0) -
    (catalystHits.length > 0 ? 10 : 0)
  );

  const openingDriveProbability = clampScore(
    gapStrengthScore * 0.2 +
    relativeVolumeScore * 0.22 +
    catalystStrength * 0.16 +
    premarketTrendScore * 0.14 +
    liquidityQuality * 0.08 +
    gapContinuation.openingRangeBreakoutProbability * 0.2 -
    fadeRisk * 0.12
  );

  const morningMomentumScore = clampScore(
    gapStrengthScore * 0.24 +
    relativeVolumeScore * 0.24 +
    liquidityQuality * 0.16 +
    catalystStrength * 0.16 +
    floatRotation.floatRotationScore * 0.2
  );

  const morningTier =
    morningMomentumScore >= 82 && openingDriveProbability >= 75
      ? "TIER_1_ATTACK"
      : morningMomentumScore >= 68
        ? "TIER_2_WATCH"
        : "IGNORE";

  return {
    symbol,
    phase: "16.2_PREMARKET_MOMENTUM_ENGINE",
    premarketGapPercent: Number(percentChange.toFixed(2)),
    premarketPrice: Number(currentPrice.toFixed(4)),
    previousClose: Number(previousClose.toFixed(4)),
    premarketVolume: volume,
    relativeVolume,
    gapStrengthScore,
    relativeVolumeScore,
    catalystStrength,
    catalystHits,
    negativeCatalystHits,
    floatRotation,
    gapContinuation,
    catalystQualityScore,
    catalystRiskLabel,
    liquidityQuality,
    premarketTrendScore,
    fadeRisk,
    openingDriveProbability,
    morningMomentumScore,
    morningTier,
    isPremarketWindow: isPremarketMomentumWindow(),
    isMorningStrikeWindow: isMorningStrikeWindow(),
    reason:
      `${morningTier} • Gap ${percentChange.toFixed(2)}% • ` +
      `RVOL ${relativeVolume}x • Catalyst ${catalystStrength}/100 • ` +
      `OpenDrive ${openingDriveProbability}/100`,
  };
}


function calculatePremarketDominanceEngine(signal = {}) {
  const symbol = normalizeSymbol(signal.symbol);

  const premarket =
    signal.premarketMomentum ||
    calculatePremarketMomentumEngine(signal);

  const confirmations = signal.confirmations || {};

  const percentChange = Number(
    signal.percentChange ||
    premarket.premarketGapPercent ||
    0
  );

  const relativeVolume = Number(
    signal.relativeVolume ||
    signal.volumeRatio ||
    signal.volumeSpikeRatio ||
    premarket.relativeVolume ||
    confirmations.volumeSpikeRatio ||
    0
  );

  const volume = Number(
    signal.volume ||
    signal.barVolume ||
    premarket.premarketVolume ||
    0
  );

  const bid = Number(signal.bid || 0);
  const ask = Number(signal.ask || 0);
  const current = Number(signal.current || signal.price || 0);

  const spreadPercent =
    bid > 0 && ask > 0 && current > 0
      ? ((ask - bid) / current) * 100
      : 0;

  const bidStrengthScore = clampScore(
    50 +
    (bid > 0 && ask > 0 ? 10 : 0) +
    (spreadPercent > 0 && spreadPercent <= 0.4 ? 15 : 0) +
    (spreadPercent > 0.4 && spreadPercent <= 1 ? 8 : 0) -
    (spreadPercent > 1.5 ? 18 : 0) -
    (spreadPercent > 3 ? 25 : 0)
  );

  const overnightInstitutionalActivityScore = clampScore(
    40 +
    (percentChange >= 4 ? 12 : 0) +
    (percentChange >= 8 ? 12 : 0) +
    (percentChange >= 15 ? 10 : 0) +
    (relativeVolume >= 2 ? 12 : 0) +
    (relativeVolume >= 5 ? 14 : 0) +
    (volume >= 250000 ? 10 : 0) +
    (volume >= 1000000 ? 10 : 0) -
    (percentChange >= 70 ? 18 : 0)
  );

  const gapQualityScore = clampScore(
    Number(premarket.gapStrengthScore || 0) * 0.35 +
    Number(premarket.gapContinuation?.openingRangeBreakoutProbability || 0) * 0.35 +
    Number(premarket.catalystStrength || 0) * 0.2 +
    Number(premarket.liquidityQuality || 0) * 0.1 -
    Number(premarket.fadeRisk || 0) * 0.15
  );

  const premarketDominanceScore = clampScore(
    Number(premarket.openingDriveProbability || 0) * 0.28 +
    Number(premarket.morningMomentumScore || 0) * 0.24 +
    bidStrengthScore * 0.14 +
    overnightInstitutionalActivityScore * 0.18 +
    gapQualityScore * 0.16
  );

  const dominanceTier =
    premarketDominanceScore >= 85
      ? "PREMARKET_SNIPER"
      : premarketDominanceScore >= 75
        ? "DOMINANT_PREMARKET_LEADER"
        : premarketDominanceScore >= 65
          ? "PREMARKET_WATCH"
          : "NO_DOMINANCE_EDGE";

  return {
    symbol,
    phase: "26_PREMARKET_DOMINANCE_ENGINE",
    premarketDominanceScore,
    dominanceTier,
    bidStrengthScore,
    overnightInstitutionalActivityScore,
    gapQualityScore,
    spreadPercent: Number(spreadPercent.toFixed(3)),
    openingDriveProbability: premarket.openingDriveProbability,
    morningMomentumScore: premarket.morningMomentumScore,
    premarket,
    reason:
      `${dominanceTier} • Dominance ${premarketDominanceScore}/100 • ` +
      `Bid ${bidStrengthScore}/100 • Overnight ${overnightInstitutionalActivityScore}/100`,
  };
}

function updatePremarketDominanceState(signals = []) {
  const reviewed = (Array.isArray(signals) ? signals : [])
    .filter((signal) => {
      const assetClass = signal.assetClass || signal.asset_class || "stock";
      return assetClass === "stock";
    })
    .map((signal) => {
      const premarketDominance =
        signal.premarketDominance ||
        calculatePremarketDominanceEngine(signal);

      return {
        ...signal,
        premarketDominance,
        premarketDominanceScore:
          Number(premarketDominance?.premarketDominanceScore || 0),
      };

    })
    .sort(
      (a, b) =>
        Number(b.premarketDominance?.premarketDominanceScore || 0) -
        Number(a.premarketDominance?.premarketDominanceScore || 0)
    );

  const sniperCandidates = reviewed
    .filter((signal) =>
      ["PREMARKET_SNIPER", "DOMINANT_PREMARKET_LEADER"].includes(
        signal.premarketDominance?.dominanceTier
      )
    )
    .slice(0, Number(CONFIG.eliteMorningStrikeLimit || 10));

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "26_PREMARKET_DOMINANCE_ENGINE",
    isPremarketWindow: isPremarketMomentumWindow(),
    isMorningStrikeWindow: isMorningStrikeWindow(),
    reviewedCount: reviewed.length,
    sniperCount: sniperCandidates.length,
    sniperCandidates,
    topTwoSymbols: sniperCandidates.map((signal) => signal.symbol),
    dominanceRadar: reviewed.slice(0, 10),
    reason:
      `Premarket dominance reviewed ${reviewed.length} stocks • ` +
      `${sniperCandidates.length} sniper candidates found.`,
  };

  engineState.premarketDominanceState = state;

  if (!Array.isArray(engineState.premarketDominanceHistory)) {
    engineState.premarketDominanceHistory = [];
  }

  engineState.premarketDominanceHistory.unshift(state);
  engineState.premarketDominanceHistory =
    engineState.premarketDominanceHistory.slice(0, 200);

  saveEngineState("PREMARKET_DOMINANCE_UPDATED");

  return state;
}


