function calculateFullInstitutionalAiBrain(signals = []) {
  const reviewed = (Array.isArray(signals) ? signals : []).map((signal) => {
    const score = Number(signal.score || 0);

    const runnerScore = Number(
      signal.explosiveRunnerPrediction?.explosiveRunnerScore ||
      signal.adaptiveRunnerScore ||
      0
    );

    const premarketScore = Number(
      signal.premarketDominance?.premarketDominanceScore ||
      signal.premarketDominanceScore ||
      signal.premarketMomentum?.openingDriveProbability ||
      signal.explosiveRunnerPrediction?.premarket?.openingDriveProbability ||
      signal.explosiveRunnerPrediction?.premarket?.morningMomentumScore ||
      0
    );
    const accumulationScore = Number(
      signal.multiDayAccumulationScore ||
      signal.multiDayAccumulation?.preBreakoutScore ||
      0
    );

    const themeScore = Number(
      signal.themeMomentum?.themeMomentumScore || 0
    );

    const executionScore = Number(
      signal.institutionalExecutionPlan?.executionConfidence ||
      signal.executionConfidence ||
      0
    );

    const capitalRotationBoost = Number(
      signal.autonomousCapitalRotation?.allocationBoost || 0
    );

    const marketIntelligence =
      engineState.autonomousMarketIntelligenceState || {};

    const marketReadiness = Number(
      marketIntelligence.selfOptimizationReadiness || 50
    );

    const governorBlock =
      engineState.portfolioGovernorState?.shouldBlockNewTrades === true;

    const macroBlock =
      engineState.macroRiskState?.shouldBlockNewTrades === true;

    const liquidityBlock =
      engineState.liquidityIntelligenceState?.shouldBlockWeakLiquidity === true;


    const eliteRecognition =
      calculateEliteSetupRecognitionScore(signal);

    const confidenceAccuracyBoost =
      eliteRecognition.eliteRecognitionTier === "S_TIER_ELITE"
        ? 7
        : eliteRecognition.eliteRecognitionTier === "A_TIER_ELITE"
          ? 4
          : eliteRecognition.eliteRecognitionTier === "HIGH_QUALITY"
            ? 2
            : 0;


    const consensusScore = clampScore(
      score * 0.18 +
      runnerScore * 0.16 +
      premarketScore * 0.12 +
      accumulationScore * 0.12 +
      themeScore * 0.08 +
      executionScore * 0.12 +
      eliteRecognition.eliteRecognitionScore * 0.16 +
      marketReadiness * 0.04 +
      capitalRotationBoost * 3 +
      confidenceAccuracyBoost
    );

    const riskPenalty =
      (governorBlock ? 18 : 0) +
      (macroBlock ? 18 : 0) +
      (liquidityBlock ? 12 : 0);

    const dynamicConvictionScore = clampScore(
      consensusScore - riskPenalty
    );

    const opportunityTier =
      dynamicConvictionScore >= 85
        ? "MASTER_CONVICTION"
        : dynamicConvictionScore >= 75
          ? "HIGH_CONVICTION"
          : dynamicConvictionScore >= 65
            ? "QUALIFIED_OPPORTUNITY"
            : dynamicConvictionScore >= 55
              ? "WATCHLIST_ONLY"
              : "LOW_PRIORITY";

    const brainAction =
      ["MASTER_CONVICTION", "HIGH_CONVICTION"].includes(opportunityTier)
        ? "PRIORITIZE"
        : opportunityTier === "QUALIFIED_OPPORTUNITY"
          ? "ALLOW_IF_CAPITAL_AVAILABLE"
          : opportunityTier === "WATCHLIST_ONLY"
            ? "WATCH"
            : "IGNORE";

    return {
      ...signal,
      fullInstitutionalAiBrain: {
        phase: "33_FULL_INSTITUTIONAL_AI_BRAIN",
        consensusScore,
        dynamicConvictionScore,
        opportunityTier,
        brainAction,
        components: {
          baseScore: score,
          runnerScore,
          premarketScore,
          accumulationScore,
          themeScore,
          executionScore,
          marketReadiness,
          capitalRotationBoost,
          riskPenalty,
        },
        reason:
          `${opportunityTier} • Conviction ${dynamicConvictionScore}/100 • ` +
          `Consensus ${consensusScore}/100`,
      },
      institutionalBrainScore: dynamicConvictionScore,
    };
  });

  const rankedOpportunities = reviewed
    .sort(
      (a, b) =>
        Number(b.institutionalBrainScore || 0) -
        Number(a.institutionalBrainScore || 0)
    );

  const masterOpportunities = rankedOpportunities.filter((signal) =>
    ["MASTER_CONVICTION", "HIGH_CONVICTION"].includes(
      signal.fullInstitutionalAiBrain?.opportunityTier
    )
  );

  return {
    updatedAt: new Date().toISOString(),
    phase: "33_FULL_INSTITUTIONAL_AI_BRAIN",
    reviewedCount: reviewed.length,
    masterOpportunityCount: masterOpportunities.length,
    rankedOpportunities: rankedOpportunities.slice(0, 20),
    masterOpportunities: masterOpportunities.slice(0, 10),
    topTwoSymbols: masterOpportunities
      .slice(0, 5)
      .map((signal) => signal.symbol),
    crossEngineLearningActive: true,
    unifiedConsensusActive: true,
    portfolioWideOptimizationActive: true,
    reason:
      `Full Institutional AI Brain ranked ${reviewed.length} opportunities • ` +
      `${masterOpportunities.length} high-conviction candidates found.`,
  };
}

function updateFullInstitutionalAiBrainState(signals = []) {
  const state = calculateFullInstitutionalAiBrain(signals);

  engineState.fullInstitutionalAiBrainState = state;

  if (!Array.isArray(engineState.fullInstitutionalAiBrainHistory)) {
    engineState.fullInstitutionalAiBrainHistory = [];
  }

  engineState.fullInstitutionalAiBrainHistory.unshift(state);
  engineState.fullInstitutionalAiBrainHistory =
    engineState.fullInstitutionalAiBrainHistory.slice(0, 200);

  saveEngineState("FULL_INSTITUTIONAL_AI_BRAIN_UPDATED");

  return state;
}


function detectAutonomousStrategyType(signal = {}) {
  const score = Number(signal.score || 0);
  const institutionalBrainScore = Number(
    signal.institutionalBrainScore || score
  );

  const percentChange = Number(
    signal.percentChange ||
    signal.changePercent ||
    0
  );

  const volumeSpikeRatio = Number(
    signal.confirmations?.volumeSpikeRatio ||
    signal.volumeSpikeRatio ||
    signal.relativeVolume ||
    signal.volumeRatio ||
    0
  );

  const runnerScore = Number(
    signal.runnerScore ||
    signal.explosiveRunnerScore ||
    signal.explosiveRunnerPrediction?.explosiveRunnerScore ||
    0
  );

  const accumulationScore = Number(
    signal.multiDayAccumulation?.accumulationScore ||
    signal.accumulationScore ||
    0
  );

  const premarketScore = Number(
    signal.premarketDominanceScore ||
    signal.premarketDominance?.premarketDominanceScore ||
    0
  );

  const opportunityTier =
    signal.fullInstitutionalAiBrain?.opportunityTier || "";

  if (
    opportunityTier === "MASTER_CONVICTION" ||
    institutionalBrainScore >= 88
  ) {
    return "MOMENTUM";
  }

  if (
    runnerScore >= 75 ||
    premarketScore >= 75 ||
    percentChange >= 12
  ) {
    return "BREAKOUT";
  }

  if (
    institutionalBrainScore >= 78 &&
    percentChange >= 3 &&
    percentChange <= 15
  ) {
    return "CONTINUATION";
  }

  if (
    volumeSpikeRatio >= 2.5 &&
    percentChange >= 2 &&
    percentChange <= 10
  ) {
    return "SQUEEZE";
  }

  if (
    accumulationScore >= 65 ||
    (
      volumeSpikeRatio >= 1.5 &&
      percentChange >= 0 &&
      percentChange <= 5
    )
  ) {
    return "ACCUMULATION";
  }

  return "DEFENSIVE_PROBE";
}

function calculateAutonomousMetaStrategyOrchestrator(signals = []) {
  const reviewed = Array.isArray(signals) ? signals : [];

  const marketRegime = String(
    engineState.marketRegime?.state ||
    engineState.marketRegime?.label ||
    "neutral"
  ).toLowerCase();

  const macroStress = Number(
    engineState.macroRiskState?.macroStressScore ||
    engineState.marketStressLevel ||
    0
  );

  const portfolioGovernorMode =
    engineState.portfolioGovernorState?.governorMode ||
    "NORMAL";

  const liquidityBlocked =
    engineState.liquidityIntelligenceState
      ?.shouldBlockWeakLiquidity === true;

  const baseWeights = {
    BREAKOUT: 1,
    CONTINUATION: 1,
    SQUEEZE: 1,
    ACCUMULATION: 1,
    MOMENTUM: 1,
    DEFENSIVE_PROBE: 0.75,
  };

  if (
    marketRegime.includes("aggressive") ||
    marketRegime.includes("bullish")
  ) {
    baseWeights.BREAKOUT += 0.25;
    baseWeights.MOMENTUM += 0.25;
    baseWeights.CONTINUATION += 0.15;
  }

  if (
    marketRegime.includes("defensive") ||
    marketRegime.includes("panic") ||
    macroStress >= 60
  ) {
    baseWeights.DEFENSIVE_PROBE += 0.35;
    baseWeights.ACCUMULATION += 0.2;
    baseWeights.BREAKOUT -= 0.25;
    baseWeights.MOMENTUM -= 0.15;
  }

  if (
    marketRegime.includes("neutral") ||
    marketRegime.includes("chop")
  ) {
    baseWeights.SQUEEZE += 0.2;
    baseWeights.ACCUMULATION += 0.15;
  }

  if (portfolioGovernorMode === "PROBE_DEPLOYMENT") {
    baseWeights.DEFENSIVE_PROBE += 0.25;
    baseWeights.BREAKOUT -= 0.15;
  }

  if (portfolioGovernorMode === "CONTROLLED_EXPANSION") {
    baseWeights.CONTINUATION += 0.15;
    baseWeights.MOMENTUM += 0.1;
  }

  if (liquidityBlocked) {
    baseWeights.DEFENSIVE_PROBE += 0.25;
    baseWeights.BREAKOUT -= 0.2;
    baseWeights.SQUEEZE -= 0.1;
  }

  const strategyBuckets = {
    BREAKOUT: [],
    CONTINUATION: [],
    SQUEEZE: [],
    ACCUMULATION: [],
    MOMENTUM: [],
    DEFENSIVE_PROBE: [],
  };

  const routedSignals = reviewed.map((signal) => {
    const strategyType = detectAutonomousStrategyType(signal);

    const baseScore = Number(
      signal.institutionalBrainScore ||
      signal.score ||
      0
    );

    const strategyWeight = Math.max(
      0.25,
      Number(baseWeights[strategyType] || 1)
    );

    const metaStrategyScore = clampScore(
      baseScore * strategyWeight
    );

    const routedSignal = {
      ...signal,
      score: Math.max(Number(signal.score || 0), metaStrategyScore),
      metaStrategyScore,
      autonomousMetaStrategy: {
        phase: "34_AUTONOMOUS_META_STRATEGY_ORCHESTRATOR",
        strategyType,
        strategyWeight: Number(strategyWeight.toFixed(2)),
        metaStrategyScore,
        marketRegime,
        macroStress,
        portfolioGovernorMode,
        liquidityBlocked,
        reason:
          `${strategyType} route • Weight ${strategyWeight.toFixed(2)}x • ` +
          `Meta score ${metaStrategyScore}/100`,
      },
    };

    strategyBuckets[strategyType].push(routedSignal);

    return routedSignal;
  });

  Object.keys(strategyBuckets).forEach((key) => {
    strategyBuckets[key] = strategyBuckets[key]
      .sort(
        (a, b) =>
          Number(b.metaStrategyScore || 0) -
          Number(a.metaStrategyScore || 0)
      )
      .slice(0, 10);
  });

  const strategyRanking = Object.entries(strategyBuckets)
    .map(([strategy, bucket]) => {
      const bestScore = Number(bucket[0]?.metaStrategyScore || 0);
      const count = bucket.length;
      const weight = Number(baseWeights[strategy] || 1);

      return {
        strategy,
        count,
        bestScore,
        weight: Number(weight.toFixed(2)),
        dominanceScore: Number(
          (bestScore * weight + count * 3).toFixed(2)
        ),
      };
    })
    .sort((a, b) => b.dominanceScore - a.dominanceScore);

  const dominantStrategy =
    strategyRanking[0]?.strategy || "DEFENSIVE_PROBE";

  const capitalRoutingMode =
    macroStress >= 75
      ? "CAPITAL_DEFENSE"
      : dominantStrategy === "BREAKOUT"
        ? "ATTACK_BREAKOUTS"
        : dominantStrategy === "CONTINUATION"
          ? "PRESS_CONTINUATION"
          : dominantStrategy === "SQUEEZE"
            ? "WAIT_FOR_EXPANSION"
            : dominantStrategy === "ACCUMULATION"
              ? "BUILD_EARLY_POSITION"
              : dominantStrategy === "MOMENTUM"
                ? "FOLLOW_LEADERSHIP"
                : "PROBE_ONLY";

  const rankedSignals = routedSignals.sort(
    (a, b) =>
      Number(b.metaStrategyScore || 0) -
      Number(a.metaStrategyScore || 0)
  );

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "34_AUTONOMOUS_META_STRATEGY_ORCHESTRATOR",
    reviewedCount: reviewed.length,
    dominantStrategy,
    capitalRoutingMode,
    marketRegime,
    macroStress,
    portfolioGovernorMode,
    liquidityBlocked,
    strategyWeights: baseWeights,
    strategyRanking,
    strategyBuckets,
    rankedSignals: rankedSignals.slice(0, 25),
    topTwoSymbols: rankedSignals.slice(0, 2).map((s) => s.symbol),
    adaptiveStrategyRotationActive: true,
    selfEvolvingCapitalRoutingActive: true,
    reason:
      `${capitalRoutingMode} • Dominant strategy ${dominantStrategy} • ` +
      `${rankedSignals.length} routed signals`,
  };

  engineState.autonomousMetaStrategyState = state;

  if (!Array.isArray(engineState.autonomousMetaStrategyHistory)) {
    engineState.autonomousMetaStrategyHistory = [];
  }

  engineState.autonomousMetaStrategyHistory.unshift(state);
  engineState.autonomousMetaStrategyHistory =
    engineState.autonomousMetaStrategyHistory.slice(0, 200);

  saveEngineState("AUTONOMOUS_META_STRATEGY_UPDATED");

  return {
    state,
    signals: rankedSignals,
  };
}

function calculatePhase63StrategyEvolutionEngine(signals = []) {
  if (!engineState.phase63StrategyEvolutionMemory) {
    engineState.phase63StrategyEvolutionMemory = {};
  }

  const marketStress = Number(engineState.marketStressLevel || 0);
  const regimeKey =
    engineState.marketRegime?.state ||
    engineState.marketRegime ||
    "unknown";

  const analyzedSignals = (Array.isArray(signals) ? signals : []).map((signal) => {
    const symbol = normalizeSymbol(signal.symbol);

    const strategyKey =
      signal.strategy ||
      signal.phase62MarketPersonality?.setupType ||
      (typeof classifyInstitutionalSetup === "function"
        ? classifyInstitutionalSetup(signal)
        : "GENERAL_SETUP");

    const score = Number(signal.score || 0);
    const orderFlowScore = Number(
      signal.orderFlowConvictionScore ||
      signal.phase59InstitutionalOrderFlow?.orderFlowConvictionScore ||
      0
    );
    const executionScore = Number(
      signal.adaptiveExecutionScore ||
      signal.phase60AdaptiveExecution?.adaptiveExecutionScore ||
      signal.executionConfidence ||
      0
    );
    const aggressionScore = Number(
      signal.profitAggressionScore ||
      signal.phase61ProfitAggression?.profitAggressionScore ||
      0
    );
    const personalityScore = Number(
      signal.personalityFitScore ||
      signal.phase62MarketPersonality?.personalityFitScore ||
      0
    );

    const strategyEvolutionValue = Number(
      signal.strategyEvolutionScore ||
      signal.phase63StrategyEvolution?.strategyEvolutionScore ||
      0
    );


    const runnerScore = Number(
      signal.runnerScore ||
      signal.explosiveRunnerScore ||
      signal.adaptiveRunnerScore ||
      0
    );

    const memoryKey = `${regimeKey}_${strategyKey}`;
    const memory =
      engineState.phase63StrategyEvolutionMemory[memoryKey] || {
        memoryKey,
        regimeKey,
        strategyKey,
        appearances: 0,
        strongSignals: 0,
        weakSignals: 0,
        averageScore: 0,
        averageOrderFlow: 0,
        averageExecution: 0,
        averageAggression: 0,
        averagePersonality: 0,
        evolutionTrustScore: 50,
        mutationBias: "NEUTRAL",
        lastUpdated: null,
      };

    memory.appearances += 1;
    memory.strongSignals +=
      score >= 75 && orderFlowScore >= 70 && executionScore >= 65 ? 1 : 0;
    memory.weakSignals +=
      score < 60 || orderFlowScore < 45 || executionScore < 45 ? 1 : 0;

    memory.averageScore = Number(
      ((Number(memory.averageScore || 0) * (memory.appearances - 1) + score) /
        memory.appearances).toFixed(2)
    );

    memory.averageOrderFlow = Number(
      ((Number(memory.averageOrderFlow || 0) * (memory.appearances - 1) + orderFlowScore) /
        memory.appearances).toFixed(2)
    );

    memory.averageExecution = Number(
      ((Number(memory.averageExecution || 0) * (memory.appearances - 1) + executionScore) /
        memory.appearances).toFixed(2)
    );

    memory.averageAggression = Number(
      ((Number(memory.averageAggression || 0) * (memory.appearances - 1) + aggressionScore) /
        memory.appearances).toFixed(2)
    );

    memory.averagePersonality = Number(
      ((Number(memory.averagePersonality || 0) * (memory.appearances - 1) + personalityScore) /
        memory.appearances).toFixed(2)
    );

    memory.evolutionTrustScore = clampScore(
      42 +
      memory.averageScore * 0.16 +
      memory.averageOrderFlow * 0.2 +
      memory.averageExecution * 0.18 +
      memory.averageAggression * 0.15 +
      memory.averagePersonality * 0.15 +
      memory.strongSignals * 1.6 -
      memory.weakSignals * 2.1 -
      (marketStress >= 70 ? 10 : 0)
    );

    memory.mutationBias =
      memory.evolutionTrustScore >= 82
        ? "AMPLIFY_STRATEGY"
        : memory.evolutionTrustScore >= 72
          ? "FAVOR_STRATEGY"
          : memory.evolutionTrustScore <= 42
            ? "SUPPRESS_STRATEGY"
            : memory.evolutionTrustScore <= 52
              ? "REDUCE_STRATEGY"
              : "NEUTRAL";

    memory.lastUpdated = new Date().toISOString();
    engineState.phase63StrategyEvolutionMemory[memoryKey] = memory;

    const strategyEvolutionScore = clampScore(
      memory.evolutionTrustScore * 0.5 +
      score * 0.14 +
      orderFlowScore * 0.12 +
      executionScore * 0.1 +
      aggressionScore * 0.08 +
      personalityScore * 0.06
    );

    const strategyAction =
      strategyEvolutionScore >= 82
        ? "EVOLVE_AND_AMPLIFY"
        : strategyEvolutionScore >= 72
          ? "FAVOR_THIS_STRATEGY"
          : strategyEvolutionScore <= 42
            ? "SUPPRESS_THIS_STRATEGY"
            : strategyEvolutionScore <= 52
              ? "REDUCE_THIS_STRATEGY"
              : "KEEP_STRATEGY_NEUTRAL";

    const strategyEvolutionMultiplier =
      strategyAction === "EVOLVE_AND_AMPLIFY"
        ? 1.22
        : strategyAction === "FAVOR_THIS_STRATEGY"
          ? 1.12
          : strategyAction === "REDUCE_THIS_STRATEGY"
            ? 0.85
            : strategyAction === "SUPPRESS_THIS_STRATEGY"
              ? 0.65
              : 1;

    const evolvedMinScoreOffset =
      strategyAction === "EVOLVE_AND_AMPLIFY"
        ? -4
        : strategyAction === "FAVOR_THIS_STRATEGY"
          ? -2
          : strategyAction === "REDUCE_THIS_STRATEGY"
            ? 3
            : strategyAction === "SUPPRESS_THIS_STRATEGY"
              ? 6
              : 0;

    const shouldStrategyBlock =
      strategyAction === "SUPPRESS_THIS_STRATEGY" &&
      score < 78 &&
      orderFlowScore < 65;

    return {
      phase: "63_STRATEGY_EVOLUTION_ENGINE",
      updatedAt: new Date().toISOString(),
      symbol,
      regimeKey,
      strategyKey,
      memoryKey,
      strategyEvolutionScore,
      strategyAction,
      strategyEvolutionMultiplier,
      evolvedMinScoreOffset,
      shouldStrategyBlock,
      components: {
        score,
        orderFlowScore,
        executionScore,
        aggressionScore,
        personalityScore,
        runnerScore,
      },
      memory,
      reason:
        `${strategyAction} • Evolution ${strategyEvolutionScore}/100 • ` +
        `${regimeKey}/${strategyKey} • Threshold offset ${evolvedMinScoreOffset}`,
    };
  });

  const amplified = analyzedSignals.filter((item) =>
    ["EVOLVE_AND_AMPLIFY", "FAVOR_THIS_STRATEGY"].includes(item.strategyAction)
  );

  const suppressed = analyzedSignals.filter((item) =>
    ["SUPPRESS_THIS_STRATEGY", "REDUCE_THIS_STRATEGY"].includes(item.strategyAction)
  );

  const averageStrategyEvolution =
    analyzedSignals.length > 0
      ? analyzedSignals.reduce(
        (sum, item) => sum + Number(item.strategyEvolutionScore || 0),
        0
      ) / analyzedSignals.length
      : 0;

  const state = {
    phase: "63_STRATEGY_EVOLUTION_ENGINE",
    updatedAt: new Date().toISOString(),
    reviewedCount: analyzedSignals.length,
    amplifiedCount: amplified.length,
    suppressedCount: suppressed.length,
    regimeKey,
    marketStress,
    averageStrategyEvolution: Number(averageStrategyEvolution.toFixed(2)),
    amplifiedStrategies: amplified.slice(0, 10),
    suppressedStrategies: suppressed.slice(0, 10),
    rankedStrategyEvolution: analyzedSignals
      .sort(
        (a, b) =>
          Number(b.strategyEvolutionScore || 0) -
          Number(a.strategyEvolutionScore || 0)
      )
      .slice(0, 25),
    reason:
      `Phase 63 reviewed ${analyzedSignals.length} signals • ` +
      `${amplified.length} amplified • ${suppressed.length} suppressed`,
  };

  return {
    state,
    analyzedSignals,
  };
}


function calculatePhase62MarketPersonalityMemory(signals = []) {
  if (!engineState.phase62MarketPersonalityMemory) {
    engineState.phase62MarketPersonalityMemory = {};
  }

  const now = new Date();
  const etHour = Number(
    now.toLocaleString("en-US", {
      timeZone: "America/New_York",
      hour: "2-digit",
      hour12: false,
    })
  );

  const sessionKey =
    etHour < 9
      ? "PREMARKET"
      : etHour < 11
        ? "MORNING_MOMENTUM"
        : etHour < 14
          ? "MIDDAY"
          : etHour < 16
            ? "POWER_HOUR"
            : "AFTER_HOURS";

  const regimeKey =
    engineState.marketRegime?.state ||
    engineState.marketRegime ||
    "unknown";

  const marketStress = Number(engineState.marketStressLevel || 0);

  const analyzedSignals = (Array.isArray(signals) ? signals : []).map((signal) => {
    const symbol = normalizeSymbol(signal.symbol);
    const sector = signal.estimatedSector || signal.sector || "General Market";

    const setupType =
      typeof classifyInstitutionalSetup === "function"
        ? classifyInstitutionalSetup(signal)
        : signal.strategy || "GENERAL_SETUP";

    const key = `${regimeKey}_${sessionKey}_${sector}_${setupType}`;

    const score = Number(signal.score || 0);
    const orderFlowScore = Number(
      signal.orderFlowConvictionScore ||
      signal.phase59InstitutionalOrderFlow?.orderFlowConvictionScore ||
      0
    );

    const executionScore = Number(
      signal.adaptiveExecutionScore ||
      signal.phase60AdaptiveExecution?.adaptiveExecutionScore ||
      signal.executionConfidence ||
      0
    );

    const runnerScore = Number(
      signal.runnerScore ||
      signal.explosiveRunnerScore ||
      signal.adaptiveRunnerScore ||
      0
    );

    const memory =
      engineState.phase62MarketPersonalityMemory[key] || {
        key,
        regimeKey,
        sessionKey,
        sector,
        setupType,
        appearances: 0,
        strongAppearances: 0,
        weakAppearances: 0,
        averageScore: 0,
        averageOrderFlow: 0,
        averageExecution: 0,
        averageRunnerScore: 0,
        personalityTrustScore: 50,
        lastSeenAt: null,
      };

    memory.appearances += 1;
    memory.strongAppearances += score >= 75 && orderFlowScore >= 70 ? 1 : 0;
    memory.weakAppearances += score < 60 || orderFlowScore < 45 ? 1 : 0;

    memory.averageScore = Number(
      (
        (Number(memory.averageScore || 0) * (memory.appearances - 1) + score) /
        memory.appearances
      ).toFixed(2)
    );

    memory.averageOrderFlow = Number(
      (
        (Number(memory.averageOrderFlow || 0) * (memory.appearances - 1) +
          orderFlowScore) /
        memory.appearances
      ).toFixed(2)
    );

    memory.averageExecution = Number(
      (
        (Number(memory.averageExecution || 0) * (memory.appearances - 1) +
          executionScore) /
        memory.appearances
      ).toFixed(2)
    );

    memory.averageRunnerScore = Number(
      (
        (Number(memory.averageRunnerScore || 0) * (memory.appearances - 1) +
          runnerScore) /
        memory.appearances
      ).toFixed(2)
    );

    memory.personalityTrustScore = clampScore(
      45 +
      memory.averageScore * 0.18 +
      memory.averageOrderFlow * 0.22 +
      memory.averageExecution * 0.18 +
      memory.averageRunnerScore * 0.14 +
      memory.strongAppearances * 1.8 -
      memory.weakAppearances * 2.2 -
      (marketStress >= 70 ? 10 : 0)
    );

    memory.lastSeenAt = new Date().toISOString();

    engineState.phase62MarketPersonalityMemory[key] = memory;

    const personalityFitScore = clampScore(
      memory.personalityTrustScore * 0.55 +
      score * 0.15 +
      orderFlowScore * 0.15 +
      executionScore * 0.15
    );

    const personalityMode =
      personalityFitScore >= 82
        ? "MARKET_PERSONALITY_ELITE_MATCH"
        : personalityFitScore >= 72
          ? "MARKET_PERSONALITY_STRONG_MATCH"
          : personalityFitScore >= 60
            ? "MARKET_PERSONALITY_ACCEPTABLE"
            : personalityFitScore <= 42
              ? "MARKET_PERSONALITY_REJECT"
              : "MARKET_PERSONALITY_WEAK";

    const personalityMultiplier =
      personalityMode === "MARKET_PERSONALITY_ELITE_MATCH"
        ? 1.18
        : personalityMode === "MARKET_PERSONALITY_STRONG_MATCH"
          ? 1.1
          : personalityMode === "MARKET_PERSONALITY_ACCEPTABLE"
            ? 1.03
            : personalityMode === "MARKET_PERSONALITY_REJECT"
              ? 0.65
              : 0.85;

    const shouldPersonalityBlock =
      personalityMode === "MARKET_PERSONALITY_REJECT" &&
      score < 75 &&
      orderFlowScore < 65;

    return {
      phase: "62_MARKET_PERSONALITY_MEMORY",
      updatedAt: new Date().toISOString(),
      symbol,
      key,
      regimeKey,
      sessionKey,
      sector,
      setupType,
      personalityFitScore,
      personalityMode,
      personalityMultiplier,
      shouldPersonalityBlock,
      memory,
      reason:
        `${personalityMode} • Fit ${personalityFitScore}/100 • ` +
        `${regimeKey}/${sessionKey}/${setupType}`,
    };
  });

  const eliteMatches = analyzedSignals.filter(
    (item) => item.personalityFitScore >= 82
  );

  const blockedMatches = analyzedSignals.filter(
    (item) => item.shouldPersonalityBlock
  );

  const averagePersonalityFit =
    analyzedSignals.length > 0
      ? analyzedSignals.reduce(
        (sum, item) => sum + Number(item.personalityFitScore || 0),
        0
      ) / analyzedSignals.length
      : 0;

  const state = {
    phase: "62_MARKET_PERSONALITY_MEMORY",
    updatedAt: new Date().toISOString(),
    reviewedCount: analyzedSignals.length,
    eliteMatchCount: eliteMatches.length,
    blockedCount: blockedMatches.length,
    regimeKey,
    sessionKey,
    marketStress,
    averagePersonalityFit: Number(averagePersonalityFit.toFixed(2)),
    elitePersonalityMatches: eliteMatches.slice(0, 10),
    blockedPersonalityMatches: blockedMatches.slice(0, 10),
    strongestPersonalitySignals: analyzedSignals
      .sort(
        (a, b) =>
          Number(b.personalityFitScore || 0) -
          Number(a.personalityFitScore || 0)
      )
      .slice(0, 25),
    reason:
      `Phase 62 reviewed ${analyzedSignals.length} signals • ` +
      `${eliteMatches.length} elite personality matches • ${blockedMatches.length} blocked`,
  };

  return {
    state,
    analyzedSignals,
  };
}

function calculatePhase61ProfitAggressionAI(signals = []) {
  if (!engineState.phase61AggressionMemory) {
    engineState.phase61AggressionMemory = {};
  }

  const marketStress = Number(engineState.marketStressLevel || 0);
  const regimeState =
    engineState.marketRegime?.state ||
    engineState.marketRegime ||
    "unknown";

  const governorThrottle = Number(
    engineState.portfolioGovernorState?.capitalThrottleMultiplier || 1
  );

  const centralCore =
    engineState.centralAutonomousDecisionCoreState || {};

  const analyzedSignals = (Array.isArray(signals) ? signals : []).map((signal) => {
    const symbol = normalizeSymbol(signal.symbol);

    const score = Number(signal.score || 0);
    const centralScore = Number(
      signal.finalAutonomousDecisionScore ||
      signal.centralAutonomousDecisionCore?.finalDecisionScore ||
      0
    );

    const orderFlowScore = Number(
      signal.orderFlowConvictionScore ||
      signal.phase59InstitutionalOrderFlow?.orderFlowConvictionScore ||
      0
    );

    const adaptiveExecutionScore = Number(
      signal.adaptiveExecutionScore ||
      signal.phase60AdaptiveExecution?.adaptiveExecutionScore ||
      signal.executionConfidence ||
      0
    );

    const runnerScore = Number(
      signal.runnerScore ||
      signal.explosiveRunnerScore ||
      signal.explosiveRunnerPrediction?.explosiveRunnerScore ||
      signal.adaptiveRunnerScore ||
      0
    );

    const institutionalScore = Number(
      signal.institutionalBrainScore ||
      signal.fullInstitutionalAiBrain?.dynamicConvictionScore ||
      signal.institutionalScore ||
      signal.aiConfidence ||
      0
    );

    const liquidityTrapScore = Number(
      signal.liquidityTrapScore ||
      signal.phase59InstitutionalOrderFlow?.liquidityTrapScore ||
      0
    );

    const exhaustionRiskScore = Number(
      signal.exhaustionRiskScore ||
      signal.phase59InstitutionalOrderFlow?.exhaustionRiskScore ||
      0
    );

    const fakeBreakout =
      signal.confirmations?.fakeBreakout === true ||
      liquidityTrapScore >= 75;

    const eliteSetup =
      score >= 75 &&
      centralScore >= 72 &&
      orderFlowScore >= 70 &&
      adaptiveExecutionScore >= 65 &&
      institutionalScore >= 70 &&
      liquidityTrapScore < 60 &&
      exhaustionRiskScore < 75 &&
      !fakeBreakout;

    const monsterSetup =
      score >= 82 &&
      centralScore >= 80 &&
      orderFlowScore >= 82 &&
      adaptiveExecutionScore >= 75 &&
      runnerScore >= 75 &&
      institutionalScore >= 78 &&
      marketStress < 45 &&
      !fakeBreakout;

    const aggressionPenalty =
      (marketStress >= 70 ? 25 : 0) +
      (marketStress >= 85 ? 25 : 0) +
      (governorThrottle < 0.75 ? 10 : 0) +
      (liquidityTrapScore >= 65 ? 18 : 0) +
      (exhaustionRiskScore >= 75 ? 16 : 0) +
      (fakeBreakout ? 25 : 0);

    const profitAggressionScore = clampScore(
      score * 0.18 +
      centralScore * 0.2 +
      orderFlowScore * 0.2 +
      adaptiveExecutionScore * 0.16 +
      runnerScore * 0.14 +
      institutionalScore * 0.12 -
      aggressionPenalty
    );

    const aggressionMode =
      monsterSetup && profitAggressionScore >= 85
        ? "MAX_CONTROLLED_ATTACK"
        : eliteSetup && profitAggressionScore >= 76
          ? "AGGRESSIVE_COMPOUND_ATTACK"
          : profitAggressionScore >= 66
            ? "SELECTIVE_PRESS"
            : profitAggressionScore <= 42
              ? "CAPITAL_DEFENSE"
              : "NORMAL_DEPLOYMENT";

    const aggressionMultiplier =
      aggressionMode === "MAX_CONTROLLED_ATTACK"
        ? 1.55
        : aggressionMode === "AGGRESSIVE_COMPOUND_ATTACK"
          ? 1.32
          : aggressionMode === "SELECTIVE_PRESS"
            ? 1.12
            : aggressionMode === "CAPITAL_DEFENSE"
              ? 0.55
              : 1;

    const maxAllowedExposurePercent =
      aggressionMode === "MAX_CONTROLLED_ATTACK"
        ? 35
        : aggressionMode === "AGGRESSIVE_COMPOUND_ATTACK"
          ? 28
          : aggressionMode === "SELECTIVE_PRESS"
            ? 22
            : 15;

    const shouldBlockAggression =
      fakeBreakout ||
      marketStress >= 88 ||
      liquidityTrapScore >= 78 ||
      exhaustionRiskScore >= 88;

    const memory =
      engineState.phase61AggressionMemory[symbol] || {
        symbol,
        appearances: 0,
        maxAggressionScore: 0,
        aggressiveApprovals: 0,
        defensiveBlocks: 0,
        lastMode: null,
        lastUpdated: null,
      };

    memory.appearances += 1;
    memory.maxAggressionScore = Math.max(
      Number(memory.maxAggressionScore || 0),
      profitAggressionScore
    );
    memory.aggressiveApprovals +=
      aggressionMode === "MAX_CONTROLLED_ATTACK" ||
        aggressionMode === "AGGRESSIVE_COMPOUND_ATTACK"
        ? 1
        : 0;
    memory.defensiveBlocks += shouldBlockAggression ? 1 : 0;
    memory.lastMode = aggressionMode;
    memory.lastUpdated = new Date().toISOString();

    engineState.phase61AggressionMemory[symbol] = memory;

    return {
      phase: "61_PROFIT_AGGRESSION_AI",
      updatedAt: new Date().toISOString(),
      symbol,
      regimeState,
      marketStress,
      score,
      centralScore,
      orderFlowScore,
      adaptiveExecutionScore,
      runnerScore,
      institutionalScore,
      liquidityTrapScore,
      exhaustionRiskScore,
      profitAggressionScore,
      aggressionMode,
      aggressionMultiplier,
      maxAllowedExposurePercent,
      eliteSetup,
      monsterSetup,
      shouldBlockAggression,
      memory,
      reason:
        `${aggressionMode} • Aggression ${profitAggressionScore}/100 • ` +
        `OrderFlow ${orderFlowScore}/100 • Execution ${adaptiveExecutionScore}/100`,
    };
  });

  const aggressiveSignals = analyzedSignals.filter((item) =>
    ["MAX_CONTROLLED_ATTACK", "AGGRESSIVE_COMPOUND_ATTACK"].includes(
      item.aggressionMode
    )
  );

  const defensiveSignals = analyzedSignals.filter(
    (item) => item.shouldBlockAggression || item.aggressionMode === "CAPITAL_DEFENSE"
  );

  const averageAggressionScore =
    analyzedSignals.length > 0
      ? analyzedSignals.reduce(
        (sum, item) => sum + Number(item.profitAggressionScore || 0),
        0
      ) / analyzedSignals.length
      : 0;

  const state = {
    phase: "61_PROFIT_AGGRESSION_AI",
    updatedAt: new Date().toISOString(),
    reviewedCount: analyzedSignals.length,
    aggressiveCount: aggressiveSignals.length,
    defensiveCount: defensiveSignals.length,
    averageAggressionScore: Number(averageAggressionScore.toFixed(2)),
    marketStress,
    regimeState,
    governorThrottle,
    centralCoreMode: centralCore.reason || null,
    strongestAggressionSignals: aggressiveSignals
      .sort(
        (a, b) =>
          Number(b.profitAggressionScore || 0) -
          Number(a.profitAggressionScore || 0)
      )
      .slice(0, 10),
    defensiveAggressionBlocks: defensiveSignals.slice(0, 10),
    reason:
      `Phase 61 reviewed ${analyzedSignals.length} signals • ` +
      `${aggressiveSignals.length} aggressive • ${defensiveSignals.length} defensive`,
  };

  return {
    state,
    analyzedSignals,
  };
}

function calculatePhase60AdaptiveExecutionAlgorithms(signal = {}, amount = 0) {
  const symbol = normalizeSymbol(signal.symbol);
  const tradeAmount = Number(amount || 0);

  const executionPlan = signal.institutionalExecutionPlan || {};
  const orderFlow = signal.phase59InstitutionalOrderFlow || {};
  const liquidity = signal.liquidityIntelligence || {};

  const executionConfidence = Number(
    signal.executionConfidence ||
    executionPlan.executionConfidence ||
    50
  );

  const liquidityScore = Number(
    executionPlan.liquidityScore ||
    liquidity.executionQualityScore ||
    liquidity.liquidityDepthScore ||
    50
  );

  const slippageRiskScore = Number(
    executionPlan.slippageRiskScore ||
    liquidity.estimatedSlippagePercent * 100 ||
    35
  );

  const orderFlowScore = Number(
    signal.orderFlowConvictionScore ||
    orderFlow.orderFlowConvictionScore ||
    50
  );

  const spreadPercent = Number(
    signal.spreadPercent ||
    executionPlan.spreadPercent ||
    orderFlow.spreadPercent ||
    0
  );

  const dollarVolume = Number(
    signal.dollarVolume ||
    executionPlan.dollarVolume ||
    liquidity.dollarVolume ||
    0
  );

  const marketStress = Number(engineState.marketStressLevel || 0);

  const weakExecution =
    executionConfidence < 45 ||
    liquidityScore < 40 ||
    slippageRiskScore >= 65 ||
    spreadPercent >= 2.5;

  const eliteExecution =
    executionConfidence >= 75 &&
    liquidityScore >= 65 &&
    orderFlowScore >= 75 &&
    slippageRiskScore <= 30 &&
    spreadPercent <= 0.75;

  let executionStyle = "SINGLE_MARKET_ORDER";
  let sliceCount = 1;
  let sliceDelayMs = 0;
  let priceProtectionMode = "NORMAL_MARKET";
  let shouldBlockExecution = false;
  let executionMultiplier = 1;

  if (weakExecution) {
    executionStyle = "BLOCK_OR_MICRO_PROBE";
    sliceCount = 1;
    sliceDelayMs = 0;
    priceProtectionMode = "PROTECT_FROM_SLIPPAGE";
    executionMultiplier = 0.35;
    shouldBlockExecution = executionConfidence < 35 || spreadPercent >= 3;
  } else if (eliteExecution && tradeAmount >= 30) {
    executionStyle = "ADAPTIVE_ICEBERG_SCALE_IN";
    sliceCount = 4;
    sliceDelayMs = 12000;
    priceProtectionMode = "STEALTH_ACCUMULATION";
    executionMultiplier = 1.12;
  } else if (orderFlowScore >= 70 && tradeAmount >= 20) {
    executionStyle = "VWAP_STYLE_STAGGERED_ENTRY";
    sliceCount = 3;
    sliceDelayMs = 10000;
    priceProtectionMode = "VWAP_PROTECTION";
    executionMultiplier = 1.05;
  } else if (marketStress >= 60 || slippageRiskScore >= 45) {
    executionStyle = "TWAP_DEFENSIVE_ENTRY";
    sliceCount = 2;
    sliceDelayMs = 15000;
    priceProtectionMode = "DEFENSIVE_TIMING";
    executionMultiplier = 0.8;
  }

  if (tradeAmount > 0 && tradeAmount / sliceCount < 1) {
    sliceCount = 1;
    sliceDelayMs = 0;
  }

  const adaptiveSliceAmount = Number(
    (tradeAmount / Math.max(1, sliceCount)).toFixed(2)
  );

  const adaptiveExecutionScore = clampScore(
    executionConfidence * 0.3 +
    liquidityScore * 0.25 +
    orderFlowScore * 0.25 +
    (100 - slippageRiskScore) * 0.15 -
    marketStress * 0.05
  );

  const decision = {
    phase: "60_ADAPTIVE_EXECUTION_ALGORITHMS",
    updatedAt: new Date().toISOString(),
    symbol,
    tradeAmount,
    executionStyle,
    sliceCount,
    adaptiveSliceAmount,
    sliceDelayMs,
    priceProtectionMode,
    shouldBlockExecution,
    executionMultiplier,
    adaptiveExecutionScore,
    executionConfidence,
    liquidityScore,
    slippageRiskScore,
    orderFlowScore,
    spreadPercent,
    dollarVolume,
    reason:
      `${executionStyle} • Exec ${adaptiveExecutionScore}/100 • ` +
      `Slices ${sliceCount} • Slice $${adaptiveSliceAmount}`,
  };

  if (!engineState.phase60ExecutionMemory) {
    engineState.phase60ExecutionMemory = {};
  }

  engineState.phase60ExecutionMemory[symbol] = {
    ...(engineState.phase60ExecutionMemory[symbol] || {}),
    symbol,
    lastExecutionStyle: executionStyle,
    lastAdaptiveExecutionScore: adaptiveExecutionScore,
    lastSliceCount: sliceCount,
    lastSliceAmount: adaptiveSliceAmount,
    lastUpdated: new Date().toISOString(),
  };

  engineState.phase60AdaptiveExecutionState = decision;

  if (!Array.isArray(engineState.phase60AdaptiveExecutionHistory)) {
    engineState.phase60AdaptiveExecutionHistory = [];
  }

  engineState.phase60AdaptiveExecutionHistory.unshift(decision);
  engineState.phase60AdaptiveExecutionHistory =
    engineState.phase60AdaptiveExecutionHistory.slice(0, 200);

  return decision;
}



function calculatePhase59InstitutionalOrderFlowIntelligence(stockSignals = [], cryptoSignals = []) {
  const allSignals = [...stockSignals, ...cryptoSignals].filter(Boolean);

  if (!engineState.phase59OrderFlowMemory) {
    engineState.phase59OrderFlowMemory = {};
  }

  const analyzedSignals = allSignals.map((signal) => {
    const symbol = normalizeSymbol(signal.symbol);
    const price = Number(signal.current || signal.price || signal.c || 0);
    const bid = Number(signal.bid || 0);
    const ask = Number(signal.ask || 0);
    const volume = Number(signal.volume || signal.barVolume || signal.v || 0);
    const avgVolume = Number(
      signal.avgVolume ||
      signal.confirmations?.avgVolume ||
      signal.confirmations?.averageVolume ||
      0
    );

    const volumeRatio = Number(
      signal.volumeRatio ||
      signal.relativeVolume ||
      signal.confirmations?.volumeSpikeRatio ||
      (avgVolume > 0 ? volume / avgVolume : 1)
    );

    const high = Number(signal.high || signal.h || 0);
    const low = Number(signal.low || signal.l || 0);
    const open = Number(signal.open || signal.o || 0);

    const spreadPercent =
      bid > 0 && ask > 0 && price > 0
        ? ((ask - bid) / price) * 100
        : Number(signal.spreadPercent || 0);

    const closeLocationPercent =
      high > low && price > 0
        ? ((price - low) / (high - low)) * 100
        : Number(signal.confirmations?.closeNearHighPercent || 50);

    const openToCloseStrength =
      open > 0 && price > 0
        ? ((price - open) / open) * 100
        : Number(signal.percentChange || signal.change || 0);

    const pullbackFromHighPercent =
      high > 0 && price > 0
        ? ((high - price) / high) * 100
        : Number(signal.confirmations?.pullbackFromHighPercent || 0);

    const bidAskQualityScore = clampScore(
      80 -
      spreadPercent * 18 +
      (bid > 0 && ask > 0 ? 8 : -8)
    );

    const tapeAggressionScore = clampScore(
      35 +
      volumeRatio * 12 +
      Math.max(0, openToCloseStrength) * 2.2 +
      (closeLocationPercent >= 85 ? 14 : 0) +
      (closeLocationPercent >= 95 ? 8 : 0) -
      (pullbackFromHighPercent >= 3 ? 14 : 0)
    );

    const absorptionScore = clampScore(
      40 +
      (volumeRatio >= 2 ? 14 : 0) +
      (volumeRatio >= 4 ? 10 : 0) +
      (closeLocationPercent >= 80 ? 14 : 0) +
      (pullbackFromHighPercent <= 1.5 ? 10 : 0) -
      (openToCloseStrength < 0 ? 20 : 0)
    );

    const exhaustionRiskScore = clampScore(
      20 +
      (pullbackFromHighPercent >= 4 ? 28 : 0) +
      (spreadPercent >= 1.5 ? 18 : 0) +
      (volumeRatio >= 6 && closeLocationPercent < 60 ? 24 : 0) +
      (openToCloseStrength > 35 ? 15 : 0) -
      (closeLocationPercent >= 90 ? 12 : 0)
    );

    const liquidityTrapScore = clampScore(
      15 +
      (signal.confirmations?.fakeBreakout ? 35 : 0) +
      (spreadPercent >= 2 ? 22 : 0) +
      (pullbackFromHighPercent >= 4 ? 18 : 0) +
      (volumeRatio >= 3 && closeLocationPercent < 55 ? 20 : 0)
    );

    const institutionalAccumulationPressure = clampScore(
      absorptionScore * 0.45 +
      tapeAggressionScore * 0.35 +
      bidAskQualityScore * 0.2 -
      liquidityTrapScore * 0.25
    );

    const orderFlowConvictionScore = clampScore(
      bidAskQualityScore * 0.18 +
      tapeAggressionScore * 0.28 +
      absorptionScore * 0.24 +
      institutionalAccumulationPressure * 0.2 -
      exhaustionRiskScore * 0.08 -
      liquidityTrapScore * 0.12
    );

    const flowLabel =
      orderFlowConvictionScore >= 82
        ? "ELITE_INSTITUTIONAL_FLOW"
        : orderFlowConvictionScore >= 72
          ? "STRONG_ORDER_FLOW"
          : orderFlowConvictionScore >= 60
            ? "ACCEPTABLE_FLOW"
            : liquidityTrapScore >= 65
              ? "LIQUIDITY_TRAP_RISK"
              : exhaustionRiskScore >= 70
                ? "EXHAUSTION_RISK"
                : "WEAK_ORDER_FLOW";

    const shouldBlock =
      liquidityTrapScore >= 75 ||
      (exhaustionRiskScore >= 82 && Number(signal.score || 0) < 85);

    const orderFlowMultiplier =
      orderFlowConvictionScore >= 85
        ? 1.18
        : orderFlowConvictionScore >= 75
          ? 1.1
          : orderFlowConvictionScore >= 65
            ? 1.04
            : orderFlowConvictionScore <= 45
              ? 0.78
              : 1;

    const memory =
      engineState.phase59OrderFlowMemory[symbol] || {
        symbol,
        appearances: 0,
        highestOrderFlowScore: 0,
        averageOrderFlowScore: 0,
        trapWarnings: 0,
        eliteFlowCount: 0,
        lastSeenAt: null,
      };

    memory.appearances += 1;
    memory.highestOrderFlowScore = Math.max(
      Number(memory.highestOrderFlowScore || 0),
      orderFlowConvictionScore
    );
    memory.averageOrderFlowScore = Number(
      (
        (
          Number(memory.averageOrderFlowScore || 0) *
          (memory.appearances - 1) +
          orderFlowConvictionScore
        ) / memory.appearances
      ).toFixed(2)
    );
    memory.trapWarnings += liquidityTrapScore >= 65 ? 1 : 0;
    memory.eliteFlowCount += orderFlowConvictionScore >= 82 ? 1 : 0;
    memory.lastSeenAt = new Date().toISOString();

    engineState.phase59OrderFlowMemory[symbol] = memory;

    return {
      symbol,
      phase: "59_INSTITUTIONAL_ORDER_FLOW_INTELLIGENCE",
      bidAskQualityScore,
      tapeAggressionScore,
      absorptionScore,
      exhaustionRiskScore,
      liquidityTrapScore,
      institutionalAccumulationPressure,
      orderFlowConvictionScore,
      orderFlowMultiplier,
      flowLabel,
      shouldBlock,
      spreadPercent: Number(spreadPercent.toFixed(3)),
      volumeRatio: Number(volumeRatio.toFixed(2)),
      closeLocationPercent: Number(closeLocationPercent.toFixed(2)),
      pullbackFromHighPercent: Number(pullbackFromHighPercent.toFixed(2)),
      memory,
      reason:
        `${flowLabel} • Flow ${orderFlowConvictionScore}/100 • ` +
        `Tape ${tapeAggressionScore}/100 • Absorption ${absorptionScore}/100 • ` +
        `Trap ${liquidityTrapScore}/100`,
    };
  });

  const eliteFlowSignals = analyzedSignals.filter(
    (item) => item.orderFlowConvictionScore >= 82
  );

  const blockedFlowSignals = analyzedSignals.filter(
    (item) => item.shouldBlock
  );

  const averageOrderFlowScore =
    analyzedSignals.length > 0
      ? analyzedSignals.reduce(
        (sum, item) => sum + Number(item.orderFlowConvictionScore || 0),
        0
      ) / analyzedSignals.length
      : 0;

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "59_INSTITUTIONAL_ORDER_FLOW_INTELLIGENCE",
    reviewedCount: analyzedSignals.length,
    eliteFlowCount: eliteFlowSignals.length,
    blockedFlowCount: blockedFlowSignals.length,
    averageOrderFlowScore: Number(averageOrderFlowScore.toFixed(2)),
    eliteFlowSignals: eliteFlowSignals.slice(0, 10),
    blockedFlowSignals: blockedFlowSignals.slice(0, 10),
    rankedOrderFlowSignals: analyzedSignals
      .sort(
        (a, b) =>
          Number(b.orderFlowConvictionScore || 0) -
          Number(a.orderFlowConvictionScore || 0)
      )
      .slice(0, 25),
    reason:
      `Phase 59 reviewed ${analyzedSignals.length} signals • ` +
      `${eliteFlowSignals.length} elite flow • ${blockedFlowSignals.length} blocked`,
  };

  return {
    state,
    analyzedSignals,
  };
}

function classifyTradeArchetype(signal = {}) {
  const symbol = normalizeSymbol(signal.symbol);
  const isCrypto =
    signal.assetType === "crypto" ||
    signal.assetClass === "crypto" ||
    String(symbol).includes("/") ||
    String(symbol).endsWith("USD");

  const runnerScore = Number(
    signal.runnerScore ||
    signal.explosiveRunnerScore ||
    signal.explosiveRunnerPrediction?.explosiveRunnerScore ||
    signal.adaptiveRunnerScore ||
    0
  );

  const velocityScore = Number(
    signal.profitVelocityScore ||
    signal.profitVelocityGovernor?.finalVelocityScore ||
    0
  );

  const premarketScore = Number(
    signal.premarketDominanceScore ||
    signal.premarketDominance?.dominanceScore ||
    signal.morningStrikeScore ||
    0
  );

  const accumulationScore = Number(
    signal.multiDayAccumulationScore ||
    signal.multiDayAccumulation?.accumulationScore ||
    0
  );

  const dcfScore = Number(
    signal.dcfValuationScore ||
    signal.dcfValuation?.valuationScore ||
    0
  );

  const defensiveScore = Number(
    signal.portfolioGovernorScore ||
    signal.macroRiskScore ||
    signal.correlationRiskScore ||
    0
  );

  if (isCrypto) return "CRYPTO_ROTATION";

  if (
    runnerScore >= 75 ||
    velocityScore >= 75 ||
    premarketScore >= 75 ||
    Number(signal.percentChange || signal.changePercent || 0) >= 8
  ) {
    return "EXPLOSIVE_RUNNER";
  }

  if (accumulationScore >= 70) {
    return "SWING_ACCUMULATION";
  }

  if (dcfScore >= 70) {
    return "VALUE_BREAKOUT";
  }

  if (defensiveScore >= 70) {
    return "DEFENSIVE_SETUP";
  }

  return "MEAN_REVERSION";
}

function getArchetypeEngineWeights(tradeArchetype) {
  const weightsByArchetype = {
    EXPLOSIVE_RUNNER: {
      base: 0.12,
      institutional: 0.16,
      execution: 0.12,
      runner: 0.25,
      orderFlow: 0.15,
      profitAggression: 0.08,
      personality: 0.04,
      strategyEvolution: 0.04,
      meta: 0.03,
      velocity: 0.20,
    },

    SWING_ACCUMULATION: {
      base: 0.14,
      institutional: 0.22,
      execution: 0.08,
      runner: 0.05,
      orderFlow: 0.08,
      profitAggression: 0.05,
      personality: 0.08,
      strategyEvolution: 0.14,
      meta: 0.08,
      velocity: 0.05,
    },

    VALUE_BREAKOUT: {
      base: 0.14,
      institutional: 0.22,
      execution: 0.08,
      runner: 0.03,
      orderFlow: 0.08,
      profitAggression: 0.04,
      personality: 0.08,
      strategyEvolution: 0.14,
      meta: 0.10,
      velocity: 0.04,
    },

    CRYPTO_ROTATION: {
      base: 0.14,
      institutional: 0.14,
      execution: 0.12,
      runner: 0.10,
      orderFlow: 0.18,
      profitAggression: 0.10,
      personality: 0.05,
      strategyEvolution: 0.08,
      meta: 0.08,
      velocity: 0.14,
    },

    DEFENSIVE_SETUP: {
      base: 0.14,
      institutional: 0.18,
      execution: 0.10,
      runner: 0.03,
      orderFlow: 0.08,
      profitAggression: 0.04,
      personality: 0.10,
      strategyEvolution: 0.12,
      meta: 0.12,
      velocity: 0.04,
    },

    MEAN_REVERSION: {
      base: 0.16,
      institutional: 0.18,
      execution: 0.12,
      runner: 0.06,
      orderFlow: 0.10,
      profitAggression: 0.06,
      personality: 0.08,
      strategyEvolution: 0.10,
      meta: 0.08,
      velocity: 0.06,
    },
  };

  return weightsByArchetype[tradeArchetype] || weightsByArchetype.MEAN_REVERSION;
}

function calculateArchetypeWeightedDecisionScore({
  signal,
  baseScore,
  institutionalScore,
  executionScore,
  runnerScore,
  orderFlowScore,
  profitAggressionScore,
  personalityScore,
  strategyEvolutionDecisionScore,
  metaScore,
  velocityScore,
  riskPenalty,
}) {
  const tradeArchetype = classifyTradeArchetype(signal);
  const weights = getArchetypeEngineWeights(tradeArchetype);

  const archetypeTrustAdjustment =
    getArchetypeTrustAdjustment({
      ...signal,
      tradeArchetype,
    });

  const archetypeMemoryBonus =
    Number(archetypeTrustAdjustment.archetypeTrustMultiplier || 1) > 1
      ? (Number(archetypeTrustAdjustment.archetypeTrustMultiplier || 1) - 1) * 25
      : 0;

  const archetypeMemoryPenalty =
    Number(archetypeTrustAdjustment.archetypeTrustMultiplier || 1) < 1
      ? (1 - Number(archetypeTrustAdjustment.archetypeTrustMultiplier || 1)) * 25
      : 0;

  const rawWeightedScore =
    baseScore * weights.base +
    institutionalScore * weights.institutional +
    executionScore * weights.execution +
    runnerScore * weights.runner +
    orderFlowScore * weights.orderFlow +
    profitAggressionScore * weights.profitAggression +
    personalityScore * weights.personality +
    strategyEvolutionDecisionScore * weights.strategyEvolution +
    metaScore * weights.meta +
    velocityScore * weights.velocity;

  const finalDecisionScore = clampScore(
    rawWeightedScore -
    riskPenalty +
    archetypeMemoryBonus -
    archetypeMemoryPenalty
  );

  return {
    tradeArchetype,
    dynamicEngineWeights: weights,
    archetypeAdjustedScore: finalDecisionScore,
    archetypeTrustAdjustment,
    archetypeMemoryBonus: Number(archetypeMemoryBonus.toFixed(2)),
    archetypeMemoryPenalty: Number(archetypeMemoryPenalty.toFixed(2)),
    finalDecisionScore,
    reason:
      `${tradeArchetype} weighted decision • ` +
      `Relevant engines dominate • Final ${finalDecisionScore}/100`,
  };
}

function calculateAutonomousHedgeFundLayer(signals = []) {
  const activeSignals = (Array.isArray(signals) ? signals : []).filter(Boolean);

  const marketStress = Number(engineState.marketStressLevel || 0);
  const portfolioPressure = Number(
    engineState.portfolioEcosystemState?.portfolioPressureScore || 0
  );

  const capitalMode =
    engineState.dynamicCapitalParliamentState?.capitalMode ||
    "UNKNOWN_CAPITAL_MODE";

  const metaMode =
    engineState.autonomousMetaReinforcementState?.aggressionMode ||
    "UNKNOWN_META_MODE";

  const trapCount = Number(
    engineState.liquiditySweepTrapState?.trapCount || 0
  );

  const squeezeIgnitionCount = Number(
    engineState.liquiditySweepTrapState?.squeezeIgnitionCount || 0
  );

  const eliteCandidates = activeSignals.filter((signal) => {
    const score = Number(
      signal.finalAutonomousDecisionScore ||
      signal.archetypeAdjustedScore ||
      signal.score ||
      0
    );

    return (
      score >= 82 &&
      signal.autoTradeApproved !== false &&
      signal.approved !== false
    );
  });

  const blockedSignals = activeSignals.filter(
    (signal) =>
      signal.autoTradeApproved === false ||
      signal.approved === false
  );

  const approvalRate =
    activeSignals.length > 0
      ? Number(
        (
          ((activeSignals.length - blockedSignals.length) /
            activeSignals.length) *
          100
        ).toFixed(2)
      )
      : 0;

  const hedgeFundMode =
    marketStress >= 85
      ? "CAPITAL_DEFENSE_MODE"
      : portfolioPressure >= 80
        ? "PORTFOLIO_DECONCENTRATION_MODE"
        : squeezeIgnitionCount >= 2 && eliteCandidates.length >= 2
          ? "RUNNER_EXPANSION_MODE"
          : capitalMode === "ELITE_CAPITAL_CONCENTRATION"
            ? "ELITE_CONCENTRATION_MODE"
            : metaMode === "SUPPRESSION_RELIEF_MODE"
              ? "SUPPRESSION_RELIEF_MODE"
              : "BALANCED_HEDGE_FUND_MODE";

  const globalCapitalMultiplier =
    hedgeFundMode === "CAPITAL_DEFENSE_MODE"
      ? 0.55
      : hedgeFundMode === "PORTFOLIO_DECONCENTRATION_MODE"
        ? 0.7
        : hedgeFundMode === "RUNNER_EXPANSION_MODE"
          ? 1.18
          : hedgeFundMode === "ELITE_CONCENTRATION_MODE"
            ? 1.12
            : hedgeFundMode === "SUPPRESSION_RELIEF_MODE"
              ? 1.05
              : 1;

  const shouldReduceNewTrades =
    ["CAPITAL_DEFENSE_MODE", "PORTFOLIO_DECONCENTRATION_MODE"].includes(
      hedgeFundMode
    );

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "78_AUTONOMOUS_HEDGE_FUND_LAYER",
    reviewedCount: activeSignals.length,
    hedgeFundMode,
    globalCapitalMultiplier,
    shouldReduceNewTrades,
    marketStress,
    portfolioPressure,
    capitalMode,
    metaMode,
    trapCount,
    squeezeIgnitionCount,
    eliteCandidateCount: eliteCandidates.length,
    approvalRate,
    reason:
      `${hedgeFundMode} • Global capital x${globalCapitalMultiplier} • ` +
      `Stress ${marketStress} • Portfolio pressure ${portfolioPressure} • ` +
      `Elite candidates ${eliteCandidates.length}`,
  };

  const adjustedSignals = activeSignals.map((signal) => {
    const score = Number(
      signal.finalAutonomousDecisionScore ||
      signal.archetypeAdjustedScore ||
      signal.score ||
      0
    );

    const isElite = score >= 82;
    const isSqueeze =
      signal.squeezeIgnition === true ||
      signal.liquiditySweepTrap?.squeezeIgnition === true;

    const protectCapital =
      hedgeFundMode === "CAPITAL_DEFENSE_MODE" && !isElite;

    const deconcentrate =
      hedgeFundMode === "PORTFOLIO_DECONCENTRATION_MODE" &&
      signal.portfolioEcosystem?.reduceSize === true;

    const expandRunner =
      hedgeFundMode === "RUNNER_EXPANSION_MODE" &&
      isSqueeze &&
      isElite;

    const hedgeFundSignalMultiplier =
      protectCapital
        ? 0.45
        : deconcentrate
          ? 0.65
          : expandRunner
            ? 1.22
            : globalCapitalMultiplier;

    const hedgeFundAction =
      protectCapital
        ? "DEFEND_CAPITAL_REDUCE"
        : deconcentrate
          ? "DECONCENTRATE_REDUCE"
          : expandRunner
            ? "EXPAND_RUNNER_CAPITAL"
            : hedgeFundMode;

    return {
      symbol: signal.symbol,
      score,
      isElite,
      isSqueeze,
      hedgeFundMode,
      hedgeFundAction,
      hedgeFundSignalMultiplier,
      reason:
        `${hedgeFundAction} • Signal multiplier x${hedgeFundSignalMultiplier}`,
    };
  });

  return {
    state,
    adjustedSignals,
  };
}

function calculateLiquiditySweepTrapIntelligence(signals = []) {
  const activeSignals = (Array.isArray(signals) ? signals : []).filter(Boolean);

  const reviewedSignals = activeSignals.map((signal) => {
    const tradeArchetype =
      signal.tradeArchetype ||
      classifyTradeArchetype(signal);

    const percentChange = Number(
      signal.percentChange ||
      signal.changePercent ||
      signal.dp ||
      0
    );

    const closeNearHighPercent = Number(
      signal.closeNearHighPercent ||
      signal.confirmations?.closeNearHighPercent ||
      0
    );

    const rvol = Number(
      signal.rvol ||
      signal.relativeVolume ||
      signal.relativeVolumeRatio ||
      0
    );

    const volumeSpike =
      signal.confirmations?.volumeSpike === true ||
      rvol >= 2.5;

    const fakeBreakout =
      signal.confirmations?.fakeBreakout === true ||
      signal.fakeBreakout === true;

    const liveMovePercent = Number(
      signal.liveMovePercent ||
      signal.liveMomentumMutation?.liveMovePercent ||
      0
    );

    const orderFlowScore = Number(
      signal.phase59InstitutionalOrderFlow?.orderFlowConvictionScore ||
      signal.orderFlowConvictionScore ||
      0
    );

    const runnerScore = Number(
      signal.runnerScore ||
      signal.explosiveRunnerScore ||
      signal.explosiveRunnerPrediction?.explosiveRunnerScore ||
      0
    );

    const extendedButStrong =
      percentChange >= 12 &&
      closeNearHighPercent >= 80 &&
      volumeSpike &&
      orderFlowScore >= 68;

    const likelyStopHunt =
      liveMovePercent <= -1.5 &&
      volumeSpike &&
      closeNearHighPercent <= 45 &&
      orderFlowScore >= 60;

    const failedBreakoutTrap =
      fakeBreakout ||
      (
        percentChange >= 8 &&
        closeNearHighPercent <= 35 &&
        liveMovePercent < 0
      );

    const squeezeIgnition =
      ["EXPLOSIVE_RUNNER", "CRYPTO_ROTATION"].includes(tradeArchetype) &&
      runnerScore >= 78 &&
      orderFlowScore >= 68 &&
      liveMovePercent >= 1.2 &&
      volumeSpike;

    const trapRiskScore = clampScore(
      (failedBreakoutTrap ? 45 : 0) +
      (likelyStopHunt ? 22 : 0) +
      (percentChange >= 20 && closeNearHighPercent < 50 ? 18 : 0) -
      (squeezeIgnition ? 30 : 0) -
      (extendedButStrong ? 12 : 0)
    );

    const liquiditySweepMode =
      squeezeIgnition
        ? "SQUEEZE_IGNITION"
        : failedBreakoutTrap
          ? "FAILED_BREAKOUT_TRAP"
          : likelyStopHunt
            ? "POSSIBLE_STOP_HUNT"
            : extendedButStrong
              ? "EXTENDED_BUT_CONFIRMED"
              : "NO_LIQUIDITY_TRAP";

    const shouldBlockForTrap =
      trapRiskScore >= 70 &&
      !squeezeIgnition;

    const shouldReduceForTrap =
      trapRiskScore >= 45 &&
      trapRiskScore < 70 &&
      !squeezeIgnition;

    const liquidityTrapMultiplier =
      shouldBlockForTrap
        ? 0
        : shouldReduceForTrap
          ? 0.65
          : squeezeIgnition
            ? 1.12
            : 1;

    return {
      symbol: signal.symbol,
      tradeArchetype,
      percentChange,
      closeNearHighPercent,
      rvol,
      volumeSpike,
      fakeBreakout,
      liveMovePercent,
      orderFlowScore,
      runnerScore,
      extendedButStrong,
      likelyStopHunt,
      failedBreakoutTrap,
      squeezeIgnition,
      trapRiskScore,
      liquiditySweepMode,
      shouldBlockForTrap,
      shouldReduceForTrap,
      liquidityTrapMultiplier,
      reason:
        `${liquiditySweepMode} • Trap risk ${trapRiskScore}/100 • ` +
        `Multiplier x${liquidityTrapMultiplier}`,
    };
  });

  const trapCount = reviewedSignals.filter(
    (item) => item.shouldBlockForTrap || item.shouldReduceForTrap
  ).length;

  const squeezeIgnitionCount = reviewedSignals.filter(
    (item) => item.squeezeIgnition
  ).length;

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "77_LIQUIDITY_SWEEP_TRAP_INTELLIGENCE",
    reviewedCount: reviewedSignals.length,
    trapCount,
    squeezeIgnitionCount,
    topTrapRisks: reviewedSignals
      .filter((item) => item.trapRiskScore >= 45)
      .sort((a, b) => b.trapRiskScore - a.trapRiskScore)
      .slice(0, 12),
    squeezeIgnitions: reviewedSignals
      .filter((item) => item.squeezeIgnition)
      .slice(0, 12),
    reason:
      `Liquidity trap engine reviewed ${reviewedSignals.length} signals, ` +
      `found ${trapCount} traps and ${squeezeIgnitionCount} squeeze ignitions.`,
  };

  return {
    state,
    reviewedSignals,
  };
}
function calculateAutonomousMetaReinforcement(signals = []) {
  const activeSignals = (Array.isArray(signals) ? signals : []).filter(Boolean);

  const approvedSignals = activeSignals.filter(
    (signal) =>
      signal.autoTradeApproved !== false &&
      signal.approved !== false
  );

  const eliteSignals = activeSignals.filter(
    (signal) =>
      Number(
        signal.finalAutonomousDecisionScore ||
        signal.archetypeAdjustedScore ||
        signal.score ||
        0
      ) >= 82
  );

  const blockedSignals = activeSignals.filter(
    (signal) =>
      signal.autoTradeApproved === false ||
      signal.approved === false
  );

  const averageScore =
    activeSignals.reduce(
      (sum, signal) =>
        sum +
        Number(
          signal.finalAutonomousDecisionScore ||
          signal.archetypeAdjustedScore ||
          signal.score ||
          0
        ),
      0
    ) / Math.max(1, activeSignals.length);

  const approvalRate =
    activeSignals.length > 0
      ? Number(((approvedSignals.length / activeSignals.length) * 100).toFixed(2))
      : 0;

  const blockRate =
    activeSignals.length > 0
      ? Number(((blockedSignals.length / activeSignals.length) * 100).toFixed(2))
      : 0;

  const marketStress = Number(engineState.marketStressLevel || 0);
  const portfolioPressure = Number(
    engineState.portfolioEcosystemState?.portfolioPressureScore || 0
  );

  const parliamentMode =
    engineState.aiParliamentVotingState?.topVotes?.[0]?.parliamentDecision ||
    "UNKNOWN_PARLIAMENT_MODE";

  const aggressionMode =
    marketStress >= 80 || portfolioPressure >= 80
      ? "DEFENSIVE_META_REINFORCEMENT"
      : eliteSignals.length >= 3 && approvalRate >= 35
        ? "AGGRESSIVE_META_REINFORCEMENT"
        : blockRate >= 75 && averageScore >= 70
          ? "SUPPRESSION_RELIEF_MODE"
          : "BALANCED_META_REINFORCEMENT";

  const metaAggressionMultiplier =
    aggressionMode === "AGGRESSIVE_META_REINFORCEMENT"
      ? 1.12
      : aggressionMode === "SUPPRESSION_RELIEF_MODE"
        ? 1.06
        : aggressionMode === "DEFENSIVE_META_REINFORCEMENT"
          ? 0.78
          : 1;

  const metaThresholdAdjustment =
    aggressionMode === "AGGRESSIVE_META_REINFORCEMENT"
      ? -2
      : aggressionMode === "SUPPRESSION_RELIEF_MODE"
        ? -1
        : aggressionMode === "DEFENSIVE_META_REINFORCEMENT"
          ? 4
          : 0;

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "76_AUTONOMOUS_META_REINFORCEMENT",
    reviewedCount: activeSignals.length,
    approvedCount: approvedSignals.length,
    blockedCount: blockedSignals.length,
    eliteCount: eliteSignals.length,
    averageScore: Number(averageScore.toFixed(2)),
    approvalRate,
    blockRate,
    marketStress,
    portfolioPressure,
    parliamentMode,
    aggressionMode,
    metaAggressionMultiplier,
    metaThresholdAdjustment,
    reason:
      `${aggressionMode} • Approval ${approvalRate}% • Block ${blockRate}% • ` +
      `Avg score ${averageScore.toFixed(2)} • Threshold adjust ${metaThresholdAdjustment}`,
  };

  const adjustedSignals = activeSignals.map((signal) => {
    const currentScore = Number(
      signal.finalAutonomousDecisionScore ||
      signal.archetypeAdjustedScore ||
      signal.score ||
      0
    );

    const eliteSetup = currentScore >= 82;
    const blockedButStrong =
      (
        signal.autoTradeApproved === false ||
        signal.approved === false
      ) &&
      currentScore >= 75 &&
      aggressionMode === "SUPPRESSION_RELIEF_MODE";

    const metaScoreAdjustment =
      aggressionMode === "AGGRESSIVE_META_REINFORCEMENT" && eliteSetup
        ? 3
        : blockedButStrong
          ? 2
          : aggressionMode === "DEFENSIVE_META_REINFORCEMENT"
            ? -4
            : 0;

    return {
      symbol: signal.symbol,
      currentScore,
      metaScoreAdjustment,
      metaAggressionMultiplier,
      metaThresholdAdjustment,
      aggressionMode,
      blockedButStrong,
      reason:
        `Meta reinforcement ${aggressionMode} adjusted score by ${metaScoreAdjustment}`,
    };
  });

  return {
    state,
    adjustedSignals,
  };
}

function calculateAiParliamentVote({
  signal,
  tradeArchetype,
  finalDecisionScore,
  institutionalScore,
  executionScore,
  runnerScore,
  orderFlowScore,
  velocityScore,
  riskPenalty,
  contradictionState,
  eliteOverride,
  marketStress,
}) {
  const votes = [];

  function addVote(engine, vote, confidence, reason) {
    votes.push({
      engine,
      vote,
      confidence: clampScore(confidence),
      reason,
    });
  }

  addVote(
    "RUNNER_AI",
    runnerScore >= 80 ? "BUY" : runnerScore >= 65 ? "WATCH" : "NEUTRAL",
    runnerScore,
    `Runner score ${runnerScore}/100`
  );

  addVote(
    "ORDER_FLOW_AI",
    orderFlowScore >= 75 ? "BUY" : orderFlowScore < 45 ? "REDUCE" : "NEUTRAL",
    orderFlowScore,
    `Order flow score ${orderFlowScore}/100`
  );

  addVote(
    "EXECUTION_AI",
    executionScore >= 70 ? "BUY_NOW" : executionScore < 50 ? "WAIT" : "NEUTRAL",
    executionScore,
    `Execution score ${executionScore}/100`
  );

  addVote(
    "INSTITUTIONAL_AI",
    institutionalScore >= 75 ? "BUY" : institutionalScore < 50 ? "WATCH" : "NEUTRAL",
    institutionalScore,
    `Institutional score ${institutionalScore}/100`
  );

  addVote(
    "RISK_AI",
    riskPenalty >= 30 || marketStress >= 80 ? "BLOCK" : riskPenalty >= 18 ? "REDUCE" : "ALLOW",
    clampScore(100 - riskPenalty),
    `Risk penalty ${riskPenalty}, market stress ${marketStress}`
  );

  addVote(
    "CENTRAL_CORE",
    finalDecisionScore >= 82 ? "ACCELERATE" : finalDecisionScore >= CONFIG.minScoreToBuy ? "ALLOW" : "WATCH",
    finalDecisionScore,
    `Final central score ${finalDecisionScore}/100`
  );

  const buyPower = votes
    .filter((v) => ["BUY", "BUY_NOW", "ACCELERATE", "ALLOW"].includes(v.vote))
    .reduce((sum, v) => sum + v.confidence, 0);

  const waitPower = votes
    .filter((v) => ["WAIT", "WATCH", "NEUTRAL"].includes(v.vote))
    .reduce((sum, v) => sum + v.confidence, 0);

  const defensivePower = votes
    .filter((v) => ["REDUCE", "BLOCK"].includes(v.vote))
    .reduce((sum, v) => sum + v.confidence, 0);

  const blockVote = votes.some((v) => v.vote === "BLOCK" && v.confidence >= 75);

  const parliamentDecision =
    blockVote && !eliteOverride?.eligibleForEliteOverride
      ? "PARLIAMENT_BLOCK"
      : eliteOverride?.eligibleForEliteOverride && defensivePower > 0
        ? "PARLIAMENT_REDUCED_SIZE_APPROVAL"
        : buyPower > defensivePower && buyPower > waitPower
          ? "PARLIAMENT_APPROVE"
          : waitPower >= buyPower
            ? "PARLIAMENT_WAIT"
            : "PARLIAMENT_REDUCE";

  const parliamentConfidence = clampScore(
    Math.max(buyPower, waitPower, defensivePower) /
    Math.max(1, votes.length)
  );

  return {
    phase: "75_AI_PARLIAMENT_VOTING_SYSTEM",
    updatedAt: new Date().toISOString(),
    symbol: signal.symbol,
    tradeArchetype,
    votes,
    buyPower: Number(buyPower.toFixed(2)),
    waitPower: Number(waitPower.toFixed(2)),
    defensivePower: Number(defensivePower.toFixed(2)),
    parliamentDecision,
    parliamentConfidence,
    contradictionLevel:
      contradictionState?.contradictionLevel || "NO_CONFLICT",
    eliteOverrideMode:
      eliteOverride?.overrideMode || "NO_OVERRIDE",
    reason:
      `${parliamentDecision} • Confidence ${parliamentConfidence}/100 • ` +
      `Buy ${buyPower.toFixed(1)} / Wait ${waitPower.toFixed(1)} / Defense ${defensivePower.toFixed(1)}`,
  };
}

function calculateCentralCoreExecutionStyle({
  signal,
  tradeArchetype,
  finalDecisionScore,
  executionScore,
  runnerScore,
  velocityScore,
  riskPenalty,
  contradictionState,
  eliteOverride,
}) {
  const percentChange = Number(
    signal.percentChange ||
    signal.changePercent ||
    signal.dp ||
    0
  );

  const closeNearHighPercent = Number(
    signal.closeNearHighPercent ||
    signal.confirmations?.closeNearHighPercent ||
    0
  );

  const isExtended =
    percentChange >= 18 ||
    closeNearHighPercent >= 95 ||
    riskPenalty >= 22;

  const isEliteRunner =
    tradeArchetype === "EXPLOSIVE_RUNNER" &&
    runnerScore >= 82 &&
    velocityScore >= 75 &&
    finalDecisionScore >= CONFIG.minScoreToBuy;

  const needsPullback =
    isExtended &&
    executionScore < 65 &&
    tradeArchetype !== "DEFENSIVE_SETUP";

  const reducedSize =
    eliteOverride?.adjustedAction === "ALLOW_REDUCED_SIZE" ||
    contradictionState?.hasContradiction === true ||
    riskPenalty >= 18;

  const executionStyleTrustAdjustment =
    getExecutionStyleTrustAdjustment({
      ...signal,
      tradeArchetype,
      executionStyle:
        needsPullback
          ? "WAIT_FOR_MICRO_PULLBACK"
          : reducedSize
            ? "ENTER_REDUCED_SIZE"
            : isEliteRunner
              ? "MOMENTUM_BREAKOUT_ENTRY"
              : finalDecisionScore >= 82
                ? "STANDARD_ENTRY"
                : "WATCH_FOR_CONFIRMATION",
    });

  const executionStyleTrustMultiplier = Number(
    executionStyleTrustAdjustment.executionTrustMultiplier || 1
  );

  const executionStyle =
    needsPullback
      ? "WAIT_FOR_MICRO_PULLBACK"
      : reducedSize
        ? "ENTER_REDUCED_SIZE"
        : isEliteRunner
          ? "MOMENTUM_BREAKOUT_ENTRY"
          : finalDecisionScore >= 82
            ? "STANDARD_ENTRY"
            : "WATCH_FOR_CONFIRMATION";

  const baseExecutionSizeMultiplier =
    executionStyle === "WAIT_FOR_MICRO_PULLBACK"
      ? 0
      : executionStyle === "ENTER_REDUCED_SIZE"
        ? 0.5
        : executionStyle === "MOMENTUM_BREAKOUT_ENTRY"
          ? 1.1
          : executionStyle === "STANDARD_ENTRY"
            ? 1
            : 0;

  const executionSizeMultiplier = Number(
    (
      baseExecutionSizeMultiplier *
      Math.min(
        1.25,
        Math.max(0.65, executionStyleTrustMultiplier)
      )
    ).toFixed(2)
  );

  const shouldWaitForPullback =
    executionStyle === "WAIT_FOR_MICRO_PULLBACK";

  return {
    executionStyle,
    executionSizeMultiplier,
    executionStyleTrustAdjustment,
    executionStyleTrustMultiplier,
    shouldWaitForPullback,
    isExtended,
    isEliteRunner,
    reducedSize,
    reason:
      `${executionStyle} • ${tradeArchetype} • ` +
      `Execution ${executionScore}/100 • Risk penalty ${riskPenalty}`,
  };
}

function detectCentralCoreContradictions({
  signal,
  finalDecisionScore,
  institutionalScore,
  executionScore,
  runnerScore,
  orderFlowScore,
  velocityScore,
  riskPenalty,
  marketStress,
}) {
  const bullishVotes = [];
  const defensiveVotes = [];

  if (runnerScore >= 80) bullishVotes.push("RUNNER_AI_BUY");
  if (velocityScore >= 75) bullishVotes.push("VELOCITY_AI_BUY");
  if (institutionalScore >= 75) bullishVotes.push("INSTITUTIONAL_AI_BUY");
  if (orderFlowScore >= 72) bullishVotes.push("ORDER_FLOW_BUY");

  if (executionScore < 45) defensiveVotes.push("EXECUTION_AI_WAIT");
  if (riskPenalty >= 25) defensiveVotes.push("RISK_AI_REDUCE");
  if (marketStress >= 70) defensiveVotes.push("MARKET_STRESS_DEFENSE");
  if (signal.phase59InstitutionalOrderFlow?.shouldBlock === true) {
    defensiveVotes.push("ORDER_FLOW_BLOCK");
  }

  const hasContradiction =
    bullishVotes.length >= 2 && defensiveVotes.length >= 1;

  const contradictionLevel =
    bullishVotes.length >= 3 && defensiveVotes.length >= 2
      ? "HIGH_CONFLICT"
      : hasContradiction
        ? "MODERATE_CONFLICT"
        : "NO_CONFLICT";

  return {
    hasContradiction,
    contradictionLevel,
    bullishVotes,
    defensiveVotes,
    reason: hasContradiction
      ? `${contradictionLevel}: bullish engines ${bullishVotes.join(", ")} vs defensive engines ${defensiveVotes.join(", ")}`
      : "No major engine contradiction detected.",
  };
}

function calculateEliteOverrideEscalation({
  signal,
  tradeArchetype,
  finalDecisionScore,
  institutionalScore,
  executionScore,
  runnerScore,
  orderFlowScore,
  velocityScore,
  riskPenalty,
  marketStress,
  contradictionState,
}) {
  const eliteRunnerSetup =
    tradeArchetype === "EXPLOSIVE_RUNNER" &&
    runnerScore >= 82 &&
    velocityScore >= 75 &&
    orderFlowScore >= 68 &&
    institutionalScore >= 68;

  const eliteCryptoSetup =
    tradeArchetype === "CRYPTO_ROTATION" &&
    velocityScore >= 78 &&
    orderFlowScore >= 72 &&
    finalDecisionScore >= 72;

  const eliteSwingSetup =
    tradeArchetype === "SWING_ACCUMULATION" &&
    institutionalScore >= 78 &&
    finalDecisionScore >= 76 &&
    riskPenalty <= 22;

  const hardRiskBlock =
    marketStress >= 90 ||
    signal.globalRiskOffDefense?.shouldBlock === true ||
    signal.confirmations?.fakeBreakout === true ||
    signal.confirmations?.newsRisk === true;

  const eligibleForEliteOverride =
    !hardRiskBlock &&
    riskPenalty <= 28 &&
    (
      eliteRunnerSetup ||
      eliteCryptoSetup ||
      eliteSwingSetup
    );

  const overrideMode =
    eligibleForEliteOverride && contradictionState?.hasContradiction
      ? "CONFLICT_RESOLVED_ELITE_ESCALATION"
      : eligibleForEliteOverride
        ? "ELITE_ESCALATION"
        : "NO_OVERRIDE";

  const adjustedAction =
    overrideMode === "CONFLICT_RESOLVED_ELITE_ESCALATION"
      ? "ALLOW_REDUCED_SIZE"
      : overrideMode === "ELITE_ESCALATION"
        ? "ALLOW"
        : null;

  return {
    eligibleForEliteOverride,
    overrideMode,
    adjustedAction,
    hardRiskBlock,
    reason: eligibleForEliteOverride
      ? `${overrideMode}: ${tradeArchetype} has elite relevant-engine confirmation.`
      : hardRiskBlock
        ? "No override: hard risk block active."
        : "No override: setup is not elite enough.",
  };
}

function calculateLiveMomentumMutation(signals = []) {
  const activeSignals = (Array.isArray(signals) ? signals : []).filter(Boolean);

  const mutatedSignals = activeSignals.map((signal) => {
    const symbol = normalizeSymbol(signal.symbol);
    const liveQuote = engineState.liveQuoteCache?.[symbol] || null;

    const scanPrice = Number(
      signal.staleScanPrice ||
      signal.scanPrice ||
      signal.price ||
      signal.current ||
      signal.c ||
      0
    );

    const livePrice = Number(
      liveQuote?.price ||
      liveQuote?.current ||
      signal.livePrice ||
      signal.displayPrice ||
      scanPrice ||
      0
    );

    const liveMovePercent =
      scanPrice > 0 && livePrice > 0
        ? Number((((livePrice - scanPrice) / scanPrice) * 100).toFixed(2))
        : 0;

    const secondsSinceLiveUpdate =
      liveQuote?.updatedAt
        ? Math.max(
          0,
          Math.round(
            (Date.now() - new Date(liveQuote.updatedAt).getTime()) / 1000
          )
        )
        : null;

    const tradeArchetype =
      signal.tradeArchetype ||
      classifyTradeArchetype(signal);

    const baseScore = Number(
      signal.finalAutonomousDecisionScore ||
      signal.archetypeAdjustedScore ||
      signal.score ||
      0
    );

    const liveIgnition =
      liveMovePercent >= 2.5 &&
      ["EXPLOSIVE_RUNNER", "CRYPTO_ROTATION"].includes(tradeArchetype);

    const liveAcceleration =
      liveMovePercent >= 1.2 &&
      Number(signal.volume || signal.v || 0) > 0;

    const liveFade =
      liveMovePercent <= -2.2;

    const staleLiveQuote =
      secondsSinceLiveUpdate !== null &&
      secondsSinceLiveUpdate > 90;

    const mutationBonus =
      liveIgnition
        ? 6
        : liveAcceleration
          ? 3
          : 0;

    const mutationPenalty =
      liveFade
        ? 7
        : staleLiveQuote
          ? 3
          : 0;

    const liveMutatedScore = clampScore(
      baseScore + mutationBonus - mutationPenalty
    );

    const mutationMode =
      liveIgnition
        ? "LIVE_RUNNER_IGNITION"
        : liveAcceleration
          ? "LIVE_ACCELERATION"
          : liveFade
            ? "LIVE_FADE_WARNING"
            : staleLiveQuote
              ? "STALE_LIVE_QUOTE"
              : "NO_LIVE_MUTATION";

    return {
      symbol,
      tradeArchetype,
      scanPrice,
      livePrice,
      liveMovePercent,
      secondsSinceLiveUpdate,
      baseScore,
      liveMutatedScore,
      mutationBonus,
      mutationPenalty,
      mutationMode,
      liveIgnition,
      liveAcceleration,
      liveFade,
      staleLiveQuote,
      reason:
        `${mutationMode} • Live move ${liveMovePercent}% • ` +
        `Score ${baseScore} → ${liveMutatedScore}`,
    };
  });

  const ignitionCount = mutatedSignals.filter((item) => item.liveIgnition).length;
  const fadeCount = mutatedSignals.filter((item) => item.liveFade).length;
  const staleCount = mutatedSignals.filter((item) => item.staleLiveQuote).length;

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "73_LIVE_MOMENTUM_MUTATION_ENGINE",
    reviewedCount: mutatedSignals.length,
    ignitionCount,
    fadeCount,
    staleCount,
    strongestLiveMutations: mutatedSignals
      .sort((a, b) => b.liveMutatedScore - a.liveMutatedScore)
      .slice(0, 12),
    reason:
      `Live mutation reviewed ${mutatedSignals.length} signals, ` +
      `ignitions ${ignitionCount}, fades ${fadeCount}, stale ${staleCount}.`,
  };

  return {
    state,
    mutatedSignals,
  };
}

function calculateDynamicCapitalParliament(signals = [], portfolioEcosystemState = null) {
  const activeSignals = (Array.isArray(signals) ? signals : []).filter(Boolean);

  const reviewedSignals = activeSignals.map((signal) => {
    const tradeArchetype =
      signal.tradeArchetype ||
      classifyTradeArchetype(signal);

    const score = Number(
      signal.finalAutonomousDecisionScore ||
      signal.archetypeAdjustedScore ||
      signal.score ||
      0
    );

    const riskPenalty = Number(
      signal.centralAutonomousDecisionCore?.riskPenalty ||
      signal.riskPenalty ||
      0
    );

    const ecosystemMultiplier = Number(
      signal.portfolioEcosystemMultiplier ||
      signal.portfolioEcosystem?.ecosystemMultiplier ||
      1
    );

    const executionMultiplier = Number(
      signal.executionSizeMultiplier ||
      signal.centralCoreExecution?.executionSizeMultiplier ||
      1
    );

    const approved =
      signal.autoTradeApproved !== false &&
      signal.approved !== false &&
      signal.shouldWaitForPullback !== true &&
      signal.centralAutonomousAction !== "WAIT_FOR_PULLBACK";

    const capitalVoteScore = clampScore(
      score * 0.58 +
      Math.max(0, 100 - riskPenalty) * 0.18 +
      ecosystemMultiplier * 10 +
      executionMultiplier * 8 +
      (approved ? 8 : -18)
    );

    const capitalPriority =
      capitalVoteScore >= 85
        ? "ELITE_CAPITAL_PRIORITY"
        : capitalVoteScore >= 75
          ? "HIGH_CAPITAL_PRIORITY"
          : capitalVoteScore >= 65
            ? "NORMAL_CAPITAL_PRIORITY"
            : capitalVoteScore >= 55
              ? "LOW_CAPITAL_PRIORITY"
              : "NO_CAPITAL_PRIORITY";

    return {
      symbol: signal.symbol,
      tradeArchetype,
      score,
      riskPenalty,
      ecosystemMultiplier,
      executionMultiplier,
      approved,
      capitalVoteScore,
      capitalPriority,
    };
  });

  const approvedVotes = reviewedSignals.filter((item) => item.approved);

  const archetypeBuckets = {};

  for (const vote of approvedVotes) {
    if (!archetypeBuckets[vote.tradeArchetype]) {
      archetypeBuckets[vote.tradeArchetype] = {
        tradeArchetype: vote.tradeArchetype,
        count: 0,
        totalCapitalVoteScore: 0,
        averageCapitalVoteScore: 0,
        strongestSymbol: null,
        strongestScore: 0,
      };
    }

    const bucket = archetypeBuckets[vote.tradeArchetype];

    bucket.count += 1;
    bucket.totalCapitalVoteScore += Number(vote.capitalVoteScore || 0);

    if (Number(vote.capitalVoteScore || 0) > bucket.strongestScore) {
      bucket.strongestScore = Number(vote.capitalVoteScore || 0);
      bucket.strongestSymbol = vote.symbol;
    }

    bucket.averageCapitalVoteScore = Number(
      (bucket.totalCapitalVoteScore / Math.max(1, bucket.count)).toFixed(2)
    );
  }

  const rankedArchetypes = Object.values(archetypeBuckets).sort(
    (a, b) => b.averageCapitalVoteScore - a.averageCapitalVoteScore
  );

  const dominantCapitalArchetype =
    rankedArchetypes[0]?.tradeArchetype || "NONE";

  const portfolioPressureScore = Number(
    portfolioEcosystemState?.portfolioPressureScore || 0
  );

  const capitalMode =
    portfolioPressureScore >= 75
      ? "DEFENSIVE_CAPITAL_ROUTING"
      : approvedVotes.some((item) => item.capitalVoteScore >= 85)
        ? "ELITE_CAPITAL_CONCENTRATION"
        : approvedVotes.some((item) => item.capitalVoteScore >= 75)
          ? "AGGRESSIVE_CAPITAL_ROUTING"
          : "BALANCED_CAPITAL_ROUTING";

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "72_DYNAMIC_CAPITAL_PARLIAMENT",
    reviewedCount: reviewedSignals.length,
    approvedVoteCount: approvedVotes.length,
    capitalMode,
    dominantCapitalArchetype,
    rankedArchetypes,
    topCapitalCandidates: reviewedSignals
      .sort((a, b) => b.capitalVoteScore - a.capitalVoteScore)
      .slice(0, 12),
    portfolioPressureScore,
    reason:
      `${capitalMode} • Dominant capital archetype ${dominantCapitalArchetype} • ` +
      `${approvedVotes.length}/${reviewedSignals.length} approved candidates`,
  };

  const adjustedSignals = reviewedSignals.map((vote) => {
    const isDominantArchetype =
      vote.tradeArchetype === dominantCapitalArchetype;

    const elitePriority =
      vote.capitalPriority === "ELITE_CAPITAL_PRIORITY";

    const highPriority =
      vote.capitalPriority === "HIGH_CAPITAL_PRIORITY";

    const capitalParliamentMultiplier =
      vote.approved === false
        ? 0
        : portfolioPressureScore >= 75 && !elitePriority
          ? 0.65
          : elitePriority
            ? 1.22
            : highPriority && isDominantArchetype
              ? 1.12
              : vote.capitalPriority === "LOW_CAPITAL_PRIORITY"
                ? 0.75
                : 1;

    const capitalParliamentAction =
      vote.approved === false
        ? "NO_CAPITAL"
        : elitePriority
          ? "ROUTE_ELITE_CAPITAL"
          : highPriority && isDominantArchetype
            ? "ROUTE_PRIORITY_CAPITAL"
            : portfolioPressureScore >= 75
              ? "DEFENSIVE_REDUCED_CAPITAL"
              : "STANDARD_CAPITAL";

    return {
      ...vote,
      dominantCapitalArchetype,
      capitalMode,
      capitalParliamentMultiplier,
      capitalParliamentAction,
      reason:
        `${capitalParliamentAction} • Vote ${vote.capitalVoteScore}/100 • ` +
        `Mode ${capitalMode}`,
    };
  });

  return {
    state,
    adjustedSignals,
  };
}

function calculatePortfolioEcosystemIntelligence(signals = [], openPositions = []) {
  const activeSignals = (Array.isArray(signals) ? signals : []).filter(Boolean);
  const activePositions = (Array.isArray(openPositions) ? openPositions : []).filter(Boolean);

  const archetypeCounts = {};
  const sectorCounts = {};
  const symbolExposure = {};

  for (const signal of activeSignals) {
    const symbol = normalizeSymbol(signal.symbol);
    const tradeArchetype =
      signal.tradeArchetype ||
      classifyTradeArchetype(signal);

    const sector =
      signal.estimatedSector ||
      signal.sector ||
      "Unknown Sector";

    archetypeCounts[tradeArchetype] =
      Number(archetypeCounts[tradeArchetype] || 0) + 1;

    sectorCounts[sector] =
      Number(sectorCounts[sector] || 0) + 1;

    symbolExposure[symbol] = {
      symbol,
      tradeArchetype,
      sector,
      score: Number(signal.score || 0),
      finalDecisionScore:
        Number(signal.finalAutonomousDecisionScore || 0),
    };
  }

  for (const position of activePositions) {
    const symbol = normalizeSymbol(position.symbol);
    const sector =
      position.estimatedSector ||
      position.sector ||
      "Open Position";

    sectorCounts[sector] =
      Number(sectorCounts[sector] || 0) + 1;

    if (!symbolExposure[symbol]) {
      symbolExposure[symbol] = {
        symbol,
        tradeArchetype: "OPEN_POSITION",
        sector,
        score: 0,
        finalDecisionScore: 0,
      };
    }
  }

  const dominantArchetype = Object.entries(archetypeCounts)
    .sort((a, b) => b[1] - a[1])[0] || ["NONE", 0];

  const dominantSector = Object.entries(sectorCounts)
    .sort((a, b) => b[1] - a[1])[0] || ["NONE", 0];

  const totalReviewed = activeSignals.length;
  const archetypeConcentrationPercent =
    totalReviewed > 0
      ? Number(((dominantArchetype[1] / totalReviewed) * 100).toFixed(2))
      : 0;

  const sectorConcentrationPercent =
    totalReviewed > 0
      ? Number(((dominantSector[1] / totalReviewed) * 100).toFixed(2))
      : 0;

  const portfolioPressureScore = clampScore(
    archetypeConcentrationPercent * 0.45 +
    sectorConcentrationPercent * 0.45 +
    Math.min(25, activePositions.length * 3)
  );

  const ecosystemMode =
    portfolioPressureScore >= 75
      ? "HIGH_PORTFOLIO_PRESSURE"
      : portfolioPressureScore >= 55
        ? "MODERATE_PORTFOLIO_PRESSURE"
        : "NORMAL_PORTFOLIO_PRESSURE";

  const state = {
    updatedAt: new Date().toISOString(),
    phase: "71_PORTFOLIO_ECOSYSTEM_INTELLIGENCE",
    reviewedSignals: totalReviewed,
    openPositionCount: activePositions.length,
    dominantArchetype: dominantArchetype[0],
    dominantArchetypeCount: dominantArchetype[1],
    dominantSector: dominantSector[0],
    dominantSectorCount: dominantSector[1],
    archetypeConcentrationPercent,
    sectorConcentrationPercent,
    portfolioPressureScore,
    ecosystemMode,
    archetypeCounts,
    sectorCounts,
    reason:
      `${ecosystemMode} • Dominant archetype ${dominantArchetype[0]} ` +
      `${archetypeConcentrationPercent}% • Dominant sector ${dominantSector[0]} ` +
      `${sectorConcentrationPercent}%`,
  };

  const adjustedSignals = activeSignals.map((signal) => {
    const tradeArchetype =
      signal.tradeArchetype ||
      classifyTradeArchetype(signal);

    const sector =
      signal.estimatedSector ||
      signal.sector ||
      "Unknown Sector";

    const sameArchetypePressure =
      tradeArchetype === dominantArchetype[0] &&
      archetypeConcentrationPercent >= 55;

    const sameSectorPressure =
      sector === dominantSector[0] &&
      sectorConcentrationPercent >= 55;

    const reduceSize =
      portfolioPressureScore >= 55 &&
      (sameArchetypePressure || sameSectorPressure);

    const blockNewTrade =
      portfolioPressureScore >= 80 &&
      sameArchetypePressure &&
      sameSectorPressure &&
      Number(signal.finalAutonomousDecisionScore || signal.score || 0) < 82;

    const ecosystemMultiplier =
      blockNewTrade
        ? 0
        : reduceSize
          ? 0.65
          : portfolioPressureScore <= 35
            ? 1.05
            : 1;

    return {
      symbol: signal.symbol,
      tradeArchetype,
      sector,
      sameArchetypePressure,
      sameSectorPressure,
      reduceSize,
      blockNewTrade,
      ecosystemMultiplier,
      portfolioPressureScore,
      ecosystemMode,
      reason: blockNewTrade
        ? "Blocked by portfolio ecosystem pressure."
        : reduceSize
          ? "Reduced because portfolio is crowded in same archetype/sector."
          : "Portfolio ecosystem clear.",
    };
  });

  return {
    state,
    adjustedSignals,
  };
}


function calculateCentralAutonomousDecisionCore(stockSignals = [], cryptoSignals = []) {
  const allSignals = [...stockSignals, ...cryptoSignals].filter(Boolean);

  const marketRegime = engineState.marketRegime?.state || "unknown";
  const marketStress = Number(engineState.marketStressLevel || 0);
  const governorMode =
    engineState.portfolioGovernorState?.governorMode || "UNKNOWN";
  const metaMode =
    engineState.autonomousMetaStrategyState?.capitalRoutingMode || "UNKNOWN";
  const unifiedMode =
    engineState.unifiedInstitutionalOrchestratorState?.orchestratorMode ||
    "UNKNOWN";
  const profitVelocityMode =
    engineState.profitVelocityGovernorState?.velocityMode || "UNKNOWN";

  const globalRiskMultiplier = Number(
    engineState.globalRiskOffDefenseState?.exposureMultiplier || 1
  );

  const unifiedCapitalMultiplier = Number(
    engineState.unifiedInstitutionalOrchestratorState
      ?.finalCapitalMultiplier || 1
  );

  const profitVelocityMultiplier = Number(
    engineState.profitVelocityGovernorState
      ?.velocityCapitalMultiplier || 1
  );

  const governorThrottle = Number(
    engineState.portfolioGovernorState?.capitalThrottleMultiplier || 1
  );

  const masterCapitalMultiplier = Number(
    (
      globalRiskMultiplier *
      unifiedCapitalMultiplier *
      profitVelocityMultiplier *
      governorThrottle
    ).toFixed(2)
  );

  const decisions = allSignals.map((signal) => {
    const baseScore = Number(signal.score || 0);
    const institutionalScore = Number(
      signal.institutionalBrainScore ||
      signal.fullInstitutionalAiBrain?.dynamicConvictionScore ||
      signal.fullInstitutionalAiBrain?.consensusScore ||
      signal.institutionalScore ||
      signal.aiConfidence ||
      0
    );

    const executionScore = Number(
      signal.executionConfidence ||
      signal.institutionalExecutionPlan?.executionConfidence ||
      0
    );

    const orderFlowScore = Number(
      signal.orderFlowConvictionScore ||
      signal.phase59InstitutionalOrderFlow?.orderFlowConvictionScore ||
      0
    );

    const runnerScore = Number(
      signal.runnerScore ||
      signal.explosiveRunnerScore ||
      signal.explosiveRunnerPrediction?.explosiveRunnerScore ||
      signal.adaptiveRunnerScore ||
      0
    );
    const metaScore = Number(
      signal.metaStrategyScore ||
      signal.autonomousMetaStrategy?.metaStrategyScore ||
      0
    );

    const velocityScore = Number(
      signal.profitVelocityScore ||
      signal.profitVelocityGovernor?.finalVelocityScore ||
      0
    );

    const profitAggressionScore = Number(
      signal.profitAggressionScore ||
      signal.phase61ProfitAggression?.profitAggressionScore ||
      0
    );

    const personalityScore = Number(
      signal.personalityFitScore ||
      signal.phase62MarketPersonality?.personalityFitScore ||
      0
    );

    const strategyEvolutionDecisionScore = Number(
      signal.strategyEvolutionScore ||
      signal.phase63StrategyEvolution?.strategyEvolutionScore ||
      0
    );

    const riskPenalty =
      (signal.confirmations?.fakeBreakout ? 18 : 0) +
      (signal.confirmations?.gapTooHigh ? 12 : 0) +
      (signal.confirmations?.newsRisk ? 20 : 0) +
      (marketStress >= 75 ? 18 : 0) +
      (signal.globalRiskOffDefense?.shouldBlock ? 30 : 0);

    const archetypeDecision =
      calculateArchetypeWeightedDecisionScore({
        signal,
        baseScore,
        institutionalScore,
        executionScore,
        runnerScore,
        orderFlowScore,
        profitAggressionScore,
        personalityScore,
        strategyEvolutionDecisionScore,
        metaScore,
        velocityScore,
        riskPenalty,
      });

    const finalDecisionScore =
      archetypeDecision.finalDecisionScore;

    const contradictionState =
      detectCentralCoreContradictions({
        signal,
        finalDecisionScore,
        institutionalScore,
        executionScore,
        runnerScore,
        orderFlowScore,
        velocityScore,
        riskPenalty,
        marketStress,
      });

    const eliteOverride =
      calculateEliteOverrideEscalation({
        signal,
        tradeArchetype: archetypeDecision.tradeArchetype,
        finalDecisionScore,
        institutionalScore,
        executionScore,
        runnerScore,
        orderFlowScore,
        velocityScore,
        riskPenalty,
        marketStress,
        contradictionState,
      });

    const hardBlock =
      signal.globalRiskOffDefense?.shouldBlock === true ||
      marketStress >= 90 ||
      signal.confirmations?.fakeBreakout === true ||
      signal.confirmations?.newsRisk === true;

    const softBlock =
      signal.autoTradeApproved === false ||
      signal.unifiedInstitutionalOrchestrator?.shouldBlock === true ||
      signal.phase59InstitutionalOrderFlow?.shouldBlock === true ||
      signal.phase61ProfitAggression?.shouldBlockAggression === true ||
      signal.phase62MarketPersonality?.shouldPersonalityBlock === true ||
      signal.phase63StrategyEvolution?.shouldStrategyBlock === true ||
      finalDecisionScore < CONFIG.minScoreToBuy;

    const shouldBlock =
      hardBlock ||
      (softBlock && !eliteOverride.eligibleForEliteOverride);

    const aiParliamentVote =
      calculateAiParliamentVote({
        signal,
        tradeArchetype: archetypeDecision.tradeArchetype,
        finalDecisionScore,
        institutionalScore,
        executionScore,
        runnerScore,
        orderFlowScore,
        velocityScore,
        riskPenalty,
        contradictionState,
        eliteOverride,
        marketStress,
      });


    const centralCoreExecution =
      calculateCentralCoreExecutionStyle({
        signal,
        tradeArchetype: archetypeDecision.tradeArchetype,
        finalDecisionScore,
        executionScore,
        runnerScore,
        velocityScore,
        riskPenalty,
        contradictionState,
        eliteOverride,
      });

    const shouldAccelerate =
      !shouldBlock &&
      centralCoreExecution.shouldWaitForPullback !== true &&
      finalDecisionScore >= 82 &&
      executionScore >= 60 &&
      institutionalScore >= 70 &&
      orderFlowScore >= 65 &&
      profitAggressionScore >= 65 &&
      personalityScore >= 55 &&
      strategyEvolutionDecisionScore >= 52 &&
      marketStress < 60;
    const action =
      aiParliamentVote.parliamentDecision === "PARLIAMENT_BLOCK"
        ? "BLOCK"
        : aiParliamentVote.parliamentDecision === "PARLIAMENT_REDUCED_SIZE_APPROVAL"
          ? "ALLOW_REDUCED_SIZE"
          : aiParliamentVote.parliamentDecision === "PARLIAMENT_WAIT"
            ? "WAIT_FOR_PULLBACK"
            : centralCoreExecution.shouldWaitForPullback === true
              ? "WAIT_FOR_PULLBACK"
              : eliteOverride.adjustedAction ||
              (shouldBlock
                ? "BLOCK"
                : shouldAccelerate
                  ? "ACCELERATE_CAPITAL"
                  : finalDecisionScore >= CONFIG.minScoreToBuy
                    ? "ALLOW"
                    : "WATCH");

    return {
      symbol: signal.symbol,
      assetClass:
        signal.assetType ||
        (String(signal.symbol || "").includes("/") ||
          String(signal.symbol || "").endsWith("USD")
          ? "crypto"
          : "stock"),
      tradeArchetype: archetypeDecision.tradeArchetype,
      dynamicEngineWeights: archetypeDecision.dynamicEngineWeights,
      archetypeAdjustedScore: archetypeDecision.archetypeAdjustedScore,
      archetypeTrustAdjustment: archetypeDecision.archetypeTrustAdjustment,
      archetypeMemoryBonus: archetypeDecision.archetypeMemoryBonus,
      archetypeMemoryPenalty: archetypeDecision.archetypeMemoryPenalty,
      baseScore,
      institutionalScore,
      executionScore,
      runnerScore,
      metaScore,
      orderFlowScore,
      velocityScore,
      profitAggressionScore,
      personalityScore,
      strategyEvolutionScore: strategyEvolutionDecisionScore,
      aiParliamentVote,
      parliamentDecision:
        aiParliamentVote.parliamentDecision,
      parliamentConfidence:
        aiParliamentVote.parliamentConfidence,
      contradictionState,
      eliteOverride,
      centralCoreExecution,
      executionStyle: centralCoreExecution.executionStyle,
      executionSizeMultiplier:
        centralCoreExecution.executionSizeMultiplier,
      shouldWaitForPullback:
        centralCoreExecution.shouldWaitForPullback,
      executionStyleTrustAdjustment:
        centralCoreExecution.executionStyleTrustAdjustment,

      executionStyleTrustMultiplier:
        centralCoreExecution.executionStyleTrustMultiplier,
      hardBlock,
      softBlock,
      riskPenalty,
      finalDecisionScore,
      action,
      shouldBlock,
      shouldAccelerate,
      masterCapitalMultiplier,
      reason:
        `${action} • ${archetypeDecision.tradeArchetype} • ` +
        `Final ${finalDecisionScore}/100 • ` +
        `${eliteOverride.overrideMode} • ${contradictionState.contradictionLevel}`,
    };
  });

  const rankedDecisions = decisions.sort(
    (a, b) => b.finalDecisionScore - a.finalDecisionScore
  );

  const approvedDecisions = rankedDecisions.filter(
    (decision) =>
      (!decision.shouldBlock || decision.action === "ALLOW_REDUCED_SIZE") &&
      decision.action !== "WATCH"
  );

  const blockedDecisions = rankedDecisions.filter(
    (decision) => decision.shouldBlock
  );

  const state = {
    phase: "58_CENTRAL_AUTONOMOUS_DECISION_CORE",
    updatedAt: new Date().toISOString(),
    reviewedCount: allSignals.length,
    approvedCount: approvedDecisions.length,
    blockedCount: blockedDecisions.length,
    marketRegime,
    marketStress,
    governorMode,
    metaMode,
    unifiedMode,
    profitVelocityMode,
    masterCapitalMultiplier,
    topApprovedSymbols: approvedDecisions.slice(0, 5).map((d) => d.symbol),
    topBlockedSymbols: blockedDecisions.slice(0, 5).map((d) => d.symbol),
    rankedDecisions: rankedDecisions.slice(0, 25),
    autonomousControlActive: true,
    reason:
      `Central core reviewed ${allSignals.length} signals • ` +
      `${approvedDecisions.length} approved • ${blockedDecisions.length} blocked`,
  };

  return {
    state,
    rankedDecisions,
  };
}


function calculateFinalMasterDecisionProfile(signal = {}) {
  const decision = signal.centralAutonomousDecisionCore || {};
  const centralExecution =
    signal.centralCoreExecution ||
    decision.centralCoreExecution ||
    {};

  const action =
    signal.centralAutonomousAction ||
    decision.action ||
    "WATCH";

  const finalScore = clampScore(
    Number(
      decision.finalDecisionScore ||
      signal.finalAutonomousDecisionScore ||
      signal.archetypeAdjustedScore ||
      signal.score ||
      0
    )
  );

  const hardBlock =
    decision.hardBlock === true ||
    signal.centralCoreHardBlock === true ||
    signal.confirmations?.fakeBreakout === true ||
    signal.confirmations?.newsRisk === true ||
    signal.globalRiskOffDefense?.shouldBlock === true;

  const softBlock =
    decision.softBlock === true ||
    signal.centralCoreSoftBlock === true ||
    signal.phase59InstitutionalOrderFlow?.shouldBlock === true ||
    signal.phase61ProfitAggression?.shouldBlockAggression === true ||
    signal.phase62MarketPersonality?.shouldPersonalityBlock === true ||
    signal.phase63StrategyEvolution?.shouldStrategyBlock === true;

  const waitForPullback =
    action === "WAIT_FOR_PULLBACK" ||
    signal.shouldWaitForPullback === true ||
    centralExecution.shouldWaitForPullback === true;

  const reducedApproval =
    action === "ALLOW_REDUCED_SIZE" ||
    centralExecution.executionStyle === "ENTER_REDUCED_SIZE";

  const suppressEntry =
    hardBlock ||
    waitForPullback ||
    (
      softBlock &&
      action !== "ALLOW_REDUCED_SIZE" &&
      decision.eliteOverride?.eligibleForEliteOverride !== true
    );

  const masterCapitalMultiplier = Number(
    signal.masterCapitalMultiplier ||
    decision.masterCapitalMultiplier ||
    engineState.centralAutonomousDecisionCoreState?.masterCapitalMultiplier ||
    1
  );

  const executionSizeMultiplier = Number(
    centralExecution.executionSizeMultiplier ||
    signal.executionSizeMultiplier ||
    1
  );

  const allocationMultiplier = Number(
    signal.allocationMultiplier || 1
  );

  const parliamentMultiplier =
    decision.parliamentDecision === "PARLIAMENT_REDUCED_SIZE_APPROVAL"
      ? 0.5
      : decision.parliamentDecision === "PARLIAMENT_BLOCK"
        ? 0
        : 1;

  const actionMultiplier =
    suppressEntry
      ? 0
      : action === "ACCELERATE_CAPITAL"
        ? 1.18
        : reducedApproval
          ? 0.5
          : action === "ALLOW"
            ? 1
            : action === "WATCH"
              ? 0.75
              : 1;

  const finalSizingMultiplier = Number(
    Math.max(
      0,
      Math.min(
        2.5,
        masterCapitalMultiplier *
        executionSizeMultiplier *
        allocationMultiplier *
        parliamentMultiplier *
        actionMultiplier
      )
    ).toFixed(2)
  );

  const executionDecision =
    suppressEntry
      ? waitForPullback
        ? "WAIT_FOR_PULLBACK"
        : "BLOCK_EXECUTION"
      : reducedApproval
        ? "EXECUTE_REDUCED_SIZE"
        : action === "ACCELERATE_CAPITAL"
          ? "EXECUTE_ACCELERATED"
          : "EXECUTE_NORMAL";

  const finalExitProfile = {
    assetClass:
      signal.assetClass ||
      signal.asset_class ||
      decision.assetClass ||
      (isCryptoSymbol(signal.symbol) ? "crypto" : "stock"),
    exitRiskScore: Number(
      signal.exitRiskScore ||
      signal.cryptoExitParliament?.exitRiskScore ||
      signal.phase46CryptoExitParliament?.exitRiskScore ||
      signal.smartExitDecision?.exitRiskScore ||
      0
    ),
    runnerProtectionScore: Number(
      signal.runnerProtectionScore ||
      signal.institutionalExitDecision?.runnerProtectionScore ||
      signal.explosiveRunnerScore ||
      signal.runnerScore ||
      0
    ),
    preserveRunner:
      Number(
        signal.explosiveRunnerScore ||
        signal.runnerScore ||
        signal.runnerProtectionScore ||
        0
      ) >= 75 &&
      hardBlock !== true,
    forceExitOnBreakdown:
      hardBlock ||
      signal.cryptoExitDecision === "EXIT" ||
      signal.phase46CryptoExitParliament?.shouldExit === true,
  };

  return {
    phase: "58.5_FINAL_MASTER_DECISION_PROFILE",
    updatedAt: new Date().toISOString(),
    symbol: signal.symbol,
    finalScore,
    finalSizingMultiplier,
    suppressEntry,
    hardBlock,
    softBlock,
    waitForPullback,
    action,
    executionDecision,
    masterCapitalMultiplier,
    executionSizeMultiplier,
    allocationMultiplier,
    parliamentMultiplier,
    actionMultiplier,
    finalExitProfile,
    reason:
      `${executionDecision} • Final ${finalScore}/100 • ` +
      `Size x${finalSizingMultiplier} • Action ${action}`,
  };
}

function syncFinalInstitutionalDashboardSignals(finalStockSignals = [], finalCryptoSignals = []) {
  const stockSignalsForDashboard =
    Array.isArray(finalStockSignals) && finalStockSignals.length > 0
      ? finalStockSignals
      : Array.isArray(engineState.lastStockSignals)
        ? engineState.lastStockSignals
        : [];

  const cryptoSignalsForDashboard =
    Array.isArray(finalCryptoSignals) && finalCryptoSignals.length > 0
      ? finalCryptoSignals
      : Array.isArray(engineState.lastCryptoSignals)
        ? engineState.lastCryptoSignals
        : [];

  const mergedDashboardSignals = [
    ...stockSignalsForDashboard,
    ...cryptoSignalsForDashboard,
  ].filter(Boolean);

  if (!mergedDashboardSignals.length) {
    engineState.finalDashboardSignalSyncState = {
      phase: "56.5_FINAL_INSTITUTIONAL_DASHBOARD_SIGNAL_SYNC",
      updatedAt: new Date().toISOString(),
      synced: false,
      stockSignalCount: stockSignalsForDashboard.length,
      cryptoSignalCount: cryptoSignalsForDashboard.length,
      reviewedCount: 0,
      topSymbols: [],
      reason: "No finalized signals available for dashboard sync.",
    };

    if (!Array.isArray(engineState.finalDashboardSignalSyncHistory)) {
      engineState.finalDashboardSignalSyncHistory = [];
    }

    engineState.finalDashboardSignalSyncHistory.unshift(
      engineState.finalDashboardSignalSyncState
    );

    engineState.finalDashboardSignalSyncHistory =
      engineState.finalDashboardSignalSyncHistory.slice(0, 200);

    return engineState.finalDashboardSignalSyncState;
  }

  if (typeof updateThemeMomentumState === "function") {
    engineState.themeMomentumState =
      updateThemeMomentumState(stockSignalsForDashboard);
  }

  if (typeof updateExplosiveRunnerState === "function") {
    engineState.explosiveRunnerState =
      updateExplosiveRunnerState(stockSignalsForDashboard);
  }

  if (typeof updateAdaptiveRunnerLearningState === "function") {
    engineState.adaptiveRunnerLearningState =
      updateAdaptiveRunnerLearningState(stockSignalsForDashboard);
  }

  if (typeof updatePremarketDominanceState === "function") {
    engineState.premarketDominanceState =
      updatePremarketDominanceState(stockSignalsForDashboard);
  }

  if (typeof updateMultiDayAccumulationState === "function") {
    engineState.multiDayAccumulationState =
      updateMultiDayAccumulationState(stockSignalsForDashboard);
  }

  if (typeof updateInstitutionalExecutionLayerState === "function") {
    engineState.institutionalExecutionLayerState =
      updateInstitutionalExecutionLayerState(mergedDashboardSignals);
  }

  if (typeof updateFullInstitutionalAiBrainState === "function") {
    engineState.fullInstitutionalAiBrainState =
      updateFullInstitutionalAiBrainState(mergedDashboardSignals);
  }

  if (typeof calculateAutonomousMetaStrategyOrchestrator === "function") {
    const metaStrategyResult =
      calculateAutonomousMetaStrategyOrchestrator(mergedDashboardSignals);

    if (metaStrategyResult?.state) {
      engineState.autonomousMetaStrategyState =
        metaStrategyResult.state;
    }
  }

  engineState.finalDashboardSignalSyncState = {
    phase: "56.5_FINAL_INSTITUTIONAL_DASHBOARD_SIGNAL_SYNC",
    updatedAt: new Date().toISOString(),
    synced: true,
    stockSignalCount: stockSignalsForDashboard.length,
    cryptoSignalCount: cryptoSignalsForDashboard.length,
    reviewedCount: mergedDashboardSignals.length,
    topSymbols: mergedDashboardSignals
      .slice()
      .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
      .slice(0, 10)
      .map((signal) => signal.symbol),
    reason:
      `Final dashboard sync reviewed ${mergedDashboardSignals.length} finalized signals ` +
      `(${stockSignalsForDashboard.length} stocks / ${cryptoSignalsForDashboard.length} crypto).`,
  };

  if (!Array.isArray(engineState.finalDashboardSignalSyncHistory)) {
    engineState.finalDashboardSignalSyncHistory = [];
  }

  engineState.finalDashboardSignalSyncHistory.unshift(
    engineState.finalDashboardSignalSyncState
  );

  engineState.finalDashboardSignalSyncHistory =
    engineState.finalDashboardSignalSyncHistory.slice(0, 200);

  return engineState.finalDashboardSignalSyncState;
}

function syncSignalObjectsBySymbol(primarySignals = [], secondarySignals = []) {
  const primaryBySymbol = new Map();

  primarySignals.forEach((signal) => {
    const symbol = normalizeSymbol(signal.symbol);
    if (!symbol) return;
    primaryBySymbol.set(symbol, signal);
  });

  secondarySignals.forEach((signal) => {
    const symbol = normalizeSymbol(signal.symbol);
    const primary = primaryBySymbol.get(symbol);

    if (!symbol || !primary || primary === signal) return;

    Object.assign(signal, primary);
  });

  return primarySignals.map((signal) => {
    const symbol = normalizeSymbol(signal.symbol);
    const freshest = primaryBySymbol.get(symbol);
    return freshest || signal;
  });
}

